# =====================================================================
# AUTO PWA PATCH (runs on every startup, so it also works on
# share.streamlit.io / Streamlit Community Cloud, where you can't run a
# separate command before the app starts). Safe no-op if anything about
# it fails or the static/ files aren't present yet.
# =====================================================================
def _auto_patch_pwa():
    try:
        from pathlib import Path
        index_html = Path(st.__path__[0]) / "static" / "index.html"
        marker = "<!-- BANDHAN-PWA-INJECTED -->"
        if not index_html.exists():
            return
        html = index_html.read_text(encoding="utf-8")
        if marker in html or "</head>" not in html:
            return
        tags = f"""{marker}
<link rel="manifest" href="./app/static/manifest.json">
<meta name="theme-color" content="#D4AF37">
<meta name="mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-capable" content="yes">
<meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">
<meta name="apple-mobile-web-app-title" content="Siddhivinayak">
<link rel="apple-touch-icon" href="./app/static/icon-192.png">
<script>
if ('serviceWorker' in navigator) {{
  window.addEventListener('load', function() {{
    navigator.serviceWorker.register('./app/static/sw.js').catch(function() {{}});
  }});
}}
</script>
"""
        index_html.write_text(html.replace("</head>", tags + "</head>"), encoding="utf-8")
    except Exception:
        pass  # never let a PWA-install nicety break the actual app


_auto_patch_pwa()

# ---- Siddhivinayak Matrimony logo, embedded directly in the code so it always
# shows (no separate image file needed, no old-logo fallback). ----
SIDDHIVINAYAK_LOGO_B64 = ""

def _favicon():
    try:
        import io as _io
        from PIL import Image as _Img
        _im = _Img.open(_io.BytesIO(base64.b64decode(SIDDHIVINAYAK_LOGO_B64))).convert("RGBA")
        _sq = _Img.new("RGBA", (max(_im.size), max(_im.size)), (255, 255, 255, 0))
        _sq.paste(_im, ((_sq.width - _im.width) // 2, (_sq.height - _im.height) // 2), _im)
        return _sq.resize((128, 128))
    except Exception:
        return "\U0001F48D"

st.set_page_config(page_title="Siddhivinayak Matrimony | Premium Wedding Ecosystem", page_icon=_favicon(), layout="wide", initial_sidebar_state="expanded")


