# ---------------------------------------------------------------------
# Secrets reader that understands BOTH styles of Streamlit secrets:
#   flat      ->  MONGODB_URI = "..."         AGORA_APP_ID = "..."
#   sectioned ->  [mongo] uri = "..."         [agora] app_id = "..."
#                 [cloudflare] access_key_id / secret_access_key /
#                              bucket_name / endpoint_url / account_id
# so keys pasted in either format are picked up (no more silent Demo Mode).
# ---------------------------------------------------------------------
_SECRET_SECTION_ALIASES = {
    "MONGODB_URI": [("mongo", "uri"), ("mongo", "MONGODB_URI"), ("mongodb", "uri"), ("mongodb", "MONGODB_URI")],
    "AGORA_APP_ID": [("agora", "app_id"), ("agora", "AGORA_APP_ID")],
    "AGORA_APP_CERTIFICATE": [("agora", "app_certificate"), ("agora", "AGORA_APP_CERTIFICATE")],
}
for _n in ("AWS_ACCESS_KEY_ID", "R2_ACCESS_KEY_ID", "CLOUDFLARE_R2_ACCESS_KEY_ID", "CLOUDFLARE_ACCESS_KEY_ID"):
    _SECRET_SECTION_ALIASES[_n] = [("cloudflare", "access_key_id"), ("r2", "access_key_id")]
for _n in ("AWS_SECRET_ACCESS_KEY", "R2_SECRET_ACCESS_KEY", "CLOUDFLARE_R2_SECRET_ACCESS_KEY", "CLOUDFLARE_SECRET_ACCESS_KEY"):
    _SECRET_SECTION_ALIASES[_n] = [("cloudflare", "secret_access_key"), ("r2", "secret_access_key")]
for _n in ("AWS_S3_BUCKET", "R2_BUCKET", "R2_BUCKET_NAME", "CLOUDFLARE_R2_BUCKET", "CLOUDFLARE_BUCKET"):
    _SECRET_SECTION_ALIASES[_n] = [("cloudflare", "bucket_name"), ("cloudflare", "bucket"), ("r2", "bucket_name")]
for _n in ("AWS_S3_ENDPOINT_URL", "R2_ENDPOINT_URL", "CLOUDFLARE_R2_ENDPOINT_URL", "CLOUDFLARE_ENDPOINT_URL"):
    _SECRET_SECTION_ALIASES[_n] = [("cloudflare", "endpoint_url"), ("r2", "endpoint_url")]
for _n in ("CLOUDFLARE_ACCOUNT_ID", "R2_ACCOUNT_ID", "CLOUDFLARE_R2_ACCOUNT_ID"):
    _SECRET_SECTION_ALIASES[_n] = [("cloudflare", "account_id"), ("r2", "account_id")]


def _secret(name):
    """Like st.secrets[name] (raises KeyError if missing) but also finds the
    value inside a [section] table when it was pasted in that style."""
    try:
        v = st.secrets[name]
        if v not in (None, ""):
            return v
    except Exception:
        pass
    for sec, key in _SECRET_SECTION_ALIASES.get(name, []):
        try:
            v = st.secrets[sec][key]
            if v not in (None, ""):
                return v
        except Exception:
            continue
    raise KeyError(name)


@st.cache_resource(show_spinner=False)
def _get_mongo_client_cached():
    """Only successful connections get cached and reused (Streamlit does
    not cache a call that raises an exception, so a failed attempt here
    will simply be retried fresh next time \u2014 a transient network hiccup
    won't get "stuck" as permanently broken for the rest of the app's
    life)."""
    mongo_uri = _secret("MONGODB_URI")
    client = pymongo.MongoClient(mongo_uri, serverSelectionTimeoutMS=5000)
    client.admin.command("ping")
    return client


def get_mongo_client():
    """BUG FIX: this used to create a brand-new pymongo.MongoClient (a
    real new TCP connection + handshake + ping) on every single call \u2014
    and since Streamlit reruns the whole script on almost every
    interaction, that meant dozens of fresh connections per page load.
    Against a free-tier MongoDB Atlas cluster this caused exactly the
    intermittent behavior reported: works right after signup, then
    randomly fails ("invalid account") on a later login, because that
    particular connection attempt happened to time out while a previous
    one had briefly succeeded. Caching the client via @st.cache_resource
    makes Streamlit create it ONCE and reuse the same live connection
    across every rerun, which is also how pymongo is meant to be used (a
    MongoClient already manages its own internal connection pool \u2014
    creating many separate MongoClient objects instead of reusing one
    defeats that entirely)."""
    try:
        st.session_state.pop("_mongo_last_error", None)
        return _get_mongo_client_cached()
    except Exception as _e:
        try:
            _msg = str(_e)
            _msg = re.sub(r"://[^@\s]+@", "://***:***@", _msg)  # never show the password
            st.session_state["_mongo_last_error"] = ("Secret MONGODB_URI / [mongo] uri is missing" if isinstance(_e, KeyError) else _msg[:300])
        except Exception:
            pass
        return None


def get_db():
    client = get_mongo_client()
    if client is None:
        return None
    return client["bandhan_db"]


# =====================================================================
# MEDIA STORAGE — separate from MongoDB on purpose.
#
# MongoDB here is used for structured/text data only (profiles, bookings,
# requests, etc.). Photos and videos are binary blobs that don't belong
# in MongoDB documents — they bloat the 16MB document size limit, slow
# down queries, and make backups unwieldy. Real media should live in
# object storage (S3, Cloudinary, GCS, etc.).
#
# This module is a small adapter: if AWS S3 credentials are configured in
# st.secrets, media uploads there and MongoDB only stores the resulting
# reference (bucket + key). If no credentials are configured, it falls
# back to local disk under ./media_uploads/ so the demo still works end
# to end — but note local disk is NOT persistent across redeploys or
# multiple server instances, so configure real object storage before
# going to production.
# =====================================================================
@st.cache_resource(show_spinner=False)
def media_get_s3_client():
    """Cloudflare R2 (an S3-compatible bucket) is where photos and videos
    are meant to live \u2014 MongoDB only ever stores a small {bucket, key}
    reference to them, never the binary itself. R2 credentials can be
    set in st.secrets under either the generic AWS_* names or R2's own
    naming (R2_*, CLOUDFLARE_*), whichever was actually used when the
    account was set up \u2014 this tries all of them rather than requiring
    one exact spelling. See media_storage_status() for a human-readable
    reason if this comes back empty."""
    try:
        import boto3
    except Exception:
        return None, None

    def first_secret(*names):
        for n in names:
            try:
                v = _secret(n)
            except Exception:
                continue
            if v:
                return v
        return None

    access_key = first_secret("AWS_ACCESS_KEY_ID", "R2_ACCESS_KEY_ID", "CLOUDFLARE_R2_ACCESS_KEY_ID", "CLOUDFLARE_ACCESS_KEY_ID")
    secret_key = first_secret("AWS_SECRET_ACCESS_KEY", "R2_SECRET_ACCESS_KEY", "CLOUDFLARE_R2_SECRET_ACCESS_KEY", "CLOUDFLARE_SECRET_ACCESS_KEY")
    bucket = first_secret("AWS_S3_BUCKET", "R2_BUCKET", "R2_BUCKET_NAME", "CLOUDFLARE_R2_BUCKET", "CLOUDFLARE_BUCKET")
    endpoint_url = first_secret("AWS_S3_ENDPOINT_URL", "R2_ENDPOINT_URL", "CLOUDFLARE_R2_ENDPOINT_URL", "CLOUDFLARE_ENDPOINT_URL")
    account_id = first_secret("CLOUDFLARE_ACCOUNT_ID", "R2_ACCOUNT_ID", "CLOUDFLARE_R2_ACCOUNT_ID")
    if not endpoint_url and account_id:
        # R2's endpoint is always this exact shape once you have the
        # account ID, so the account ID alone is enough to wire it up.
        endpoint_url = f"https://{account_id}.r2.cloudflarestorage.com"
    # R2 doesn't use real AWS regions \u2014 "auto" is what Cloudflare's own
    # docs use, and it's harmless to pass to real AWS S3 too if that's
    # what's actually configured instead.
    region = first_secret("AWS_S3_REGION", "R2_REGION") or "auto"

    if not (access_key and secret_key and bucket):
        return None, None
    try:
        client_kwargs = {"aws_access_key_id": access_key, "aws_secret_access_key": secret_key, "region_name": region}
        if endpoint_url:
            client_kwargs["endpoint_url"] = endpoint_url
        client = boto3.client("s3", **client_kwargs)
        return client, bucket
    except Exception:
        return None, None


def media_storage_status():
    """Human-readable diagnosis of why Cloudflare R2 (or S3) is or isn't
    connected \u2014 shown on the admin Email Notifications / System page so
    the setup can actually be verified instead of guessed at."""
    try:
        import boto3  # noqa: F401
    except Exception:
        return False, "The 'boto3' package isn't installed, so object storage can't be reached at all."
    client, bucket = media_get_s3_client()
    if client is None:
        return False, "No storage credentials found in Streamlit Secrets (checked AWS_*, R2_*, and CLOUDFLARE_* names) \u2014 photos/videos are falling back to MongoDB storage."
    try:
        client.head_bucket(Bucket=bucket)
        return True, f"Connected to bucket \u201c{bucket}\u201d."
    except Exception as e:
        return False, f"Credentials are set but the connection to bucket \u201c{bucket}\u201d failed: {e}"


def _media_local_dir():
    path = os.path.join(os.getcwd(), "media_uploads")
    os.makedirs(path, exist_ok=True)
    return path


def media_upload(file_bytes, filename, content_type="application/octet-stream"):
    """Returns a small reference dict to store in MongoDB — never the raw
    bytes themselves. {"backend": "s3"|"mongo"|"local", "key": ...}"""
    key = f"{uuid.uuid4().hex}_{filename}"
    client, bucket = media_get_s3_client()
    if client is not None:
        try:
            client.put_object(Bucket=bucket, Key=key, Body=file_bytes, ContentType=content_type)
            return {"backend": "s3", "bucket": bucket, "key": key}
        except Exception:
            pass  # fall through if the S3 upload fails
    # ---- BUG FIX: this used to fall straight through to local disk
    # whenever S3 wasn't configured. Local disk only lives as long as
    # this one server process — on Streamlit Cloud, every redeploy or
    # restart wipes it completely, while MongoDB (used for everything
    # else) keeps running unchanged. That mismatch is exactly why
    # uploaded photos kept vanishing app-wide (avatar circle, Search
    # Partner, Newly Registered Members all falling back to initials):
    # the profile document still pointed at a photo file that no
    # longer existed on disk. Storing the bytes inside MongoDB itself
    # (until real S3 credentials are configured) makes uploads survive
    # redeploys the same way every other saved fact already does. ----
    db = get_db()
    if db is not None:
        try:
            db.media_blobs.update_one(
                {"_key": key},
                {"$set": {"content_type": content_type, "data": base64.b64encode(file_bytes).decode()}},
                upsert=True,
            )
            return {"backend": "mongo", "key": key}
        except Exception:
            pass
    local_path = os.path.join(_media_local_dir(), key)
    with open(local_path, "wb") as f:
        f.write(file_bytes)
    return {"backend": "local", "key": key}


def media_get_bytes(media_ref):
    """Fetches the actual bytes given a reference dict from media_upload."""
    if not media_ref:
        return None
    backend = media_ref.get("backend")
    if backend == "s3":
        client, bucket = media_get_s3_client()
        if client is None:
            return None
        try:
            obj = client.get_object(Bucket=media_ref.get("bucket", bucket), Key=media_ref["key"])
            return obj["Body"].read()
        except Exception:
            return None
    if backend == "mongo":
        db = get_db()
        if db is None:
            return None
        try:
            doc = db.media_blobs.find_one({"_key": media_ref["key"]})
            if doc and doc.get("data"):
                return base64.b64decode(doc["data"])
        except Exception:
            return None
        return None
    local_path = os.path.join(_media_local_dir(), media_ref["key"])
    if os.path.exists(local_path):
        with open(local_path, "rb") as f:
            return f.read()
    return None


def media_delete(media_ref):
    if not media_ref:
        return
    backend = media_ref.get("backend")
    if backend == "s3":
        client, bucket = media_get_s3_client()
        if client is not None:
            try:
                client.delete_object(Bucket=media_ref.get("bucket", bucket), Key=media_ref["key"])
            except Exception:
                pass
        return
    if backend == "mongo":
        db = get_db()
        if db is not None:
            try:
                db.media_blobs.delete_one({"_key": media_ref["key"]})
            except Exception:
                pass
        return
    local_path = os.path.join(_media_local_dir(), media_ref["key"])
    if os.path.exists(local_path):
        os.remove(local_path)


def media_storage_is_cloud():
    client, _ = media_get_s3_client()
    return client is not None


import functools

# =====================================================================
# SMART CACHE INVALIDATION
#
# The old version of this cleared EVERY @st.cache_data cache in the whole
# app after ANY single write, anywhere. That's correct but wasteful: on a
# busy app with many people using it at once, someone else's unrelated
# write (e.g. another user sending a chat message) would throw away YOUR
# already-cached profile/search/dashboard data too, forcing an extra
# MongoDB round-trip on your very next click even though nothing you
# care about actually changed. Under heavy simultaneous traffic this
# wipes the shared cache constantly and the speed-up from caching mostly
# disappears.
#
# This version scopes invalidation to the actual MongoDB collection(s) a
# write touches. Each cached read function is registered (via
# @cached_read("collection_name", ...)) under the collection(s) it
# queries; each write function is annotated (via
# @_invalidate_cache_after("collection_name", ...)) with the
# collection(s) it modifies. After a write, only the read caches
# registered under those same collection(s) are cleared — every other
# cached read in the app (unrelated collections) is left untouched and
# stays fast for every other user.
#
# Both decorators still work with NO collection names given
# (@cached_read() / @_invalidate_cache_after with no args) as a safety
# fallback: an unscoped read is just a plain cache, and an unscoped
# write clears the WHOLE cache exactly like before \u2014 so nothing new
# added later can silently under-invalidate and show stale data.
# =====================================================================
_COLLECTION_CACHE_REGISTRY = {}  # collection name -> list of cached (wrapped) functions


def cached_read(*collections, ttl=30):
    """Use exactly like @st.cache_data(show_spinner=False), but also pass
    the MongoDB collection name(s) this function reads from, e.g.
    @cached_read("users", "profiles"). That registers it so a write to
    those collections (see _invalidate_cache_after below) knows to clear
    THIS cache \u2014 and only this one, not every cache in the app.

    BUG FIX: st.cache_data's cache lives inside ONE running Python
    process. _invalidate_cache_after only clears it for the process that
    performed the write. That's fine on a single shared deployment (e.g.
    one Streamlit Community Cloud app everyone opens via the same link),
    but if two people each run `streamlit run app.py` on their OWN
    separate computers \u2014 both pointed at the same shared MongoDB, which
    otherwise works correctly \u2014 a registration saved by process A never
    invalidates process B's cache, so process B keeps serving its old,
    already-cached Search Partner / profile results (or until it's
    restarted), even though the new profile really is sitting in MongoDB
    the whole time. ttl=30s means every cached read self-heals within 30
    seconds on its own in that scenario too, without needing a restart \u2014
    a safety net on top of (not a replacement for) the immediate
    same-process invalidation above."""
    def decorator(fn):
        wrapped = st.cache_data(show_spinner=False, ttl=ttl)(fn)
        for c in collections:
            _COLLECTION_CACHE_REGISTRY.setdefault(c, []).append(wrapped)
        return wrapped
    return decorator


def _invalidate_cache_after(*collections):
    """Wraps a DB write function. Pass the MongoDB collection name(s) it
    writes to, e.g. @_invalidate_cache_after("users", "profiles") \u2014 after
    the write runs, only @cached_read caches registered under those same
    collection(s) are cleared, leaving every unrelated cached read in the
    app untouched (much better under heavy concurrent traffic). Used
    bare with no names (@_invalidate_cache_after or
    @_invalidate_cache_after()) it falls back to clearing everything, so
    it's always at least as safe as the old behavior."""
    def _apply(fn):
        @functools.wraps(fn)
        def _wrapper(*args, **kwargs):
            result = fn(*args, **kwargs)
            if collections:
                seen = set()
                for c in collections:
                    for cached_fn in _COLLECTION_CACHE_REGISTRY.get(c, []):
                        if id(cached_fn) not in seen:
                            cached_fn.clear()
                            seen.add(id(cached_fn))
            else:
                st.cache_data.clear()
            return result
        return _wrapper

    # Support the old bare-decorator form (@_invalidate_cache_after with
    # no parentheses) as well as the new @_invalidate_cache_after(fn) call
    # form, purely as a safety net for any spot that isn't annotated with
    # collection names \u2014 it still works, just falls back to a full clear.
    if len(collections) == 1 and callable(collections[0]) and not isinstance(collections[0], str):
        fn = collections[0]
        collections = ()
        return _apply(fn)
    return _apply


def db_is_connected():
    return get_db() is not None


# =====================================================================
# "STAY LOGGED IN" — real persistence across an actual browser refresh.
# Previously this checkbox only skipped a 5-minute auto-logout WITHIN the
# same session; a genuine page refresh (F5, or Streamlit's server
# restarting the session) always logged the person out anyway, because
# st.session_state doesn't survive that. This stores a random token
# (never the password) in the URL's query params and its HASH in
# MongoDB, so a fresh page load can look up that hash and safely restore
# the login \u2014 the actual token is never stored anywhere in plain text.
# =====================================================================
@_invalidate_cache_after("users")
def db_set_remember_token(email, token_hash):
    db = get_db()
    if db is None:
        return False
    db.users.update_one({"email": email}, {"$set": {"remember_token_hash": token_hash}})
    return True


@_invalidate_cache_after("users")
def db_clear_remember_token(email):
    db = get_db()
    if db is None:
        return
    db.users.update_one({"email": email}, {"$unset": {"remember_token_hash": ""}})


@cached_read("users")
def db_find_user_by_remember_token(token_hash):
    db = get_db()
    if db is None:
        return None
    return db.users.find_one({"remember_token_hash": token_hash})


def issue_remember_me_session(email):
    """Call right after a successful login/signup when 'Stay logged in'
    is checked. Generates a fresh random token, saves only its hash to
    MongoDB, and puts the plain token in the URL so a later page load
    can prove identity by hashing it again and comparing."""
    if not db_is_connected():
        return
    token = pysecrets.token_urlsafe(32)
    token_hash = hashlib.sha256(token.encode()).hexdigest()
    if db_set_remember_token(email, token_hash):
        st.query_params["rt"] = token
        st.query_params["re"] = email


def try_auto_login_from_remember_me():
    """Runs once at app startup, before the login gate. If the URL
    carries a valid remember-me token matching what's hashed in MongoDB
    for that email, the session is restored automatically \u2014 this is
    what actually makes a browser refresh keep someone logged in."""
    if st.session_state.get("logged_in"):
        return
    token = st.query_params.get("rt")
    email = st.query_params.get("re")
    if not token or not email or not db_is_connected():
        return
    token_hash = hashlib.sha256(token.encode()).hexdigest()
    user_doc = db_find_user_by_remember_token(token_hash)
    if user_doc and user_doc.get("email") == email:
        st.session_state.logged_in = True
        st.session_state.user_email = user_doc["email"]
        st.session_state.user_role = user_doc.get("role", "client")
        st.session_state.user_name = user_doc.get("name", "")
        st.session_state.user_gender = user_doc.get("gender")
        st.session_state.user_language = "en"  # app is English-only now, regardless of any old saved value
        st.session_state.stay_logged_in = True
        db_update_last_login(user_doc["email"])


def get_own_gender():
    """Logged-in member's own gender ("Male"/"Female") or None.
    Order: registered profile -> account record -> session value, so a
    restored/refreshed session or an old account can never end up with a
    blank gender (which made Search Partner show the wrong gender).
    Result is cached in session_state per email."""
    email = st.session_state.get("user_email")
    cache = st.session_state.get("_own_gender_cache")
    if cache and cache[0] == email and cache[1] in ("Male", "Female"):
        return cache[1]
    g = None
    try:
        if email and db_is_connected():
            prof = db_get_profile(email)
            if prof and prof.get("gender") in ("Male", "Female"):
                g = prof["gender"]
            if g is None:
                ud = db_find_user(email)
                if ud and ud.get("gender") in ("Male", "Female"):
                    g = ud["gender"]
    except Exception:
        g = None
    if g is None and st.session_state.get("user_gender") in ("Male", "Female"):
        g = st.session_state.get("user_gender")
    if g in ("Male", "Female"):
        st.session_state.user_gender = g
        st.session_state["_own_gender_cache"] = (email, g)
    return g


def hash_password(plain_password):
    return bcrypt.hashpw(plain_password.encode(), bcrypt.gensalt()).decode()


def verify_password(plain_password, hashed_password):
    try:
        return bcrypt.checkpw(plain_password.encode(), hashed_password.encode())
    except Exception:
        return False


# =====================================================================
# ENGAGEMENT DASHBOARD — last-login tracking so DAU/MAU can be real
# =====================================================================
@_invalidate_cache_after("users", "login_events")
def db_update_last_login(email):
    db = get_db()
    if db is None:
        return
    db.users.update_one({"email": email}, {"$set": {"last_login": dt.datetime.utcnow()}})
    # ---- login_events keeps ONE row per login (last_login above only
    # ever holds the single most-recent timestamp, overwritten every
    # time), so day-by-day Retention on the Engagement Dashboard can
    # actually ask "did this user log in again on day N after signup" \u2014
    # which last_login alone can never answer once it's been overwritten. ----
    db.login_events.insert_one({"email": email, "at": dt.datetime.utcnow()})


@cached_read("users")
def db_find_user(email):
    db = get_db()
    if db is None:
        return None
    return db.users.find_one({"email": email})


def generate_referral_code(email):
    return "BND-" + hashlib.md5(email.encode()).hexdigest().upper()[:8]


@_invalidate_cache_after("users")
def db_set_user_language(email, language_code):
    db = get_db()
    if db is None or not email:
        return False
    db.users.update_one({"email": email}, {"$set": {"language": language_code}})
    return True


@_invalidate_cache_after("referrals", "users")
def db_create_user(email, password_hash, role, name, gender=None, referred_by_code=None, language="en"):
    db = get_db()
    if db is None:
        return False
    if db.users.find_one({"email": email}):
        return False
    doc = {
        "email": email,
        "password_hash": password_hash,
        "role": role,
        "name": name,
        "gender": gender,
        "language": language,
        "created_at": dt.datetime.utcnow(),
        "referral_code": generate_referral_code(email),
        "wallet_credit": 0,
        "referred_by": None,
    }
    if referred_by_code:
        referrer = db.users.find_one({"referral_code": referred_by_code.strip().upper()})
        if referrer and referrer["email"] != email:
            doc["referred_by"] = referrer["email"]
    db.users.insert_one(doc)
    if doc["referred_by"]:
        # ---- No reward yet at signup \u2014 only recorded as "Signed Up".
        # The actual \u20b9100 credit only happens once this referred person
        # buys a membership (see db_activate_membership), so referrers
        # can't just farm free credit by getting people to sign up
        # without ever subscribing. ----
        db.referrals.insert_one({
            "referrer_email": doc["referred_by"], "referred_email": email, "referred_name": name,
            "status": "Signed Up", "reward": 0, "joined_at": dt.datetime.utcnow(),
        })
    return True


# =====================================================================
# REAL PROFILE & MATCHING SYSTEM
#
# Before this, every "Search Partner" / "My Matches" / recommendation
# page showed the SAME hardcoded demo profiles no matter who registered
# — actual registered users were never saved as searchable profiles, so
# two real people could never find each other. This section is the fix:
# a real profiles collection, a real search function, and a real
# interest/mutual-match ledger, all backed by MongoDB.
# =====================================================================
@_invalidate_cache_after("profiles")
def db_save_profile(email, profile):
    db = get_db()
    if db is None:
        return False, None
    doc = dict(profile)
    doc["email"] = email
    doc["status"] = "Active"
    doc["updated_at"] = dt.datetime.utcnow()
    if isinstance(doc.get("dob"), dt.date):
        doc["dob"] = doc["dob"].isoformat()
    if doc.get("phone"):
        dupe = db.profiles.find_one({"phone": doc["phone"], "email": {"$ne": email}})
        if dupe:
            return False, "phone_duplicate"
    if doc.get("aadhaar_hash") and db.profiles.find_one({"aadhaar_hash": doc["aadhaar_hash"], "email": {"$ne": email}}):
        return False, "aadhaar_duplicate"
    if doc.get("reg_email") and doc["reg_email"] != email and (
            db.users.find_one({"email": doc["reg_email"]}) or db.profiles.find_one({"reg_email": doc["reg_email"], "email": {"$ne": email}})):
        return False, "email_duplicate"
    doc["photo_status"] = "Pending Review" if doc.get("photo_refs") else "No Photos"
    db.profiles.update_one({"email": email}, {"$set": doc}, upsert=True)
    return True, None


@cached_read("profiles")
def db_get_profile(email):
    db = get_db()
    if db is None:
        return None
    doc = db.profiles.find_one({"email": email})
    if doc and doc.get("dob"):
        try:
            doc["dob"] = dt.date.fromisoformat(doc["dob"])
        except Exception:
            pass
    return doc


def get_profile_photo_data_uri(profile_doc, require_approval=True, which="profile"):
    """Returns an uploaded photo as a data: URI, or None.

    which="profile" (default, used everywhere except the sidebar banner)
    uses profile_photo_index (defaults to 0, the first uploaded photo).
    which="cover" (used for the sidebar banner) uses cover_photo_index
    (defaults to the 2nd uploaded photo if there is one, else the same
    as the profile photo) \u2014 see the "Profile Photo vs Cover Photo"
    picker in Edit My Profile, which lets the person choose exactly
    which of their uploaded photos is which.

    require_approval=True (the public Search Partner listing / My Matches)
    keeps the existing moderation gate: a freshly-uploaded photo stays
    hidden from other users until an admin approves it.
    require_approval=False is for the account owner's own views (sidebar,
    Edit My Profile) and the "Newly Registered Members" showcase strip —
    a person should see their own uploaded photo immediately instead of
    it looking like the upload silently failed."""
    if not profile_doc:
        return None
    photo_refs = profile_doc.get("photo_refs") or []
    if not photo_refs:
        return None
    if require_approval and profile_doc.get("photo_status") != "Approved":
        return None
    if which == "cover":
        default_idx = 1 if len(photo_refs) > 1 else 0
        idx = profile_doc.get("cover_photo_index", default_idx)
    else:
        idx = profile_doc.get("profile_photo_index", 0)
    if not isinstance(idx, int) or idx < 0 or idx >= len(photo_refs):
        idx = 0
    photo_bytes = media_get_bytes(photo_refs[idx])
    if not photo_bytes:
        return None
    return f"data:image/jpeg;base64,{base64.b64encode(photo_bytes).decode()}"


def get_current_user_photo_data_uri(which="cover"):
    """The logged-in user's own photo, bypassing the approval gate (see
    get_profile_photo_data_uri) since it's their own account. Defaults to
    the Cover Photo since this is what the sidebar banner uses."""
    email = st.session_state.get("user_email")
    if not email or not db_is_connected():
        return None
    return get_profile_photo_data_uri(db_get_profile(email), require_approval=False, which=which)


@cached_read("profiles")
def db_list_recent_registered_profiles(limit=15, opposite_of_gender=None):
    """Recently-registered members for the 'Newly Registered Members'
    showcase strip on Home / Search Partner / Registration. This is a
    public highlight reel, not the actual searchable listing — it shows
    photos immediately (require_approval off) the same way a person's own
    profile view does; the real Search Partner results still respect
    photo moderation status.

    BUG FIX: this used to show BOTH genders mixed together no matter who
    was logged in. A matrimony site only ever shows a viewer profiles of
    the opposite gender, so `opposite_of_gender` — the logged-in viewer's
    own gender ("Male"/"Female") — restricts this feed the same way. Pass
    None (e.g. nobody logged in yet, or a vendor/boss account) to show
    everyone, unfiltered, as before."""
    db = get_db()
    if db is None:
        return []
    query = {"status": "Active", "aadhaar_verified": True, "photo_status": "Approved", "name": {"$exists": True, "$ne": ""}}
    if opposite_of_gender == "Male":
        query["gender"] = "Female"
    elif opposite_of_gender == "Female":
        query["gender"] = "Male"
    docs = list(
        db.profiles.find(query)
        .sort("updated_at", -1)
        .limit(limit)
    )
    result = []
    for d in docs:
        result.append({
            "email": d.get("email", ""),
            "name": d.get("name", "Siddhivinayak Matrimony Member"),
            "city": d.get("city", ""),
            "education": d.get("education", ""),
            "caste": d.get("caste", ""),
            "profession": d.get("profession", ""),
            "income": d.get("income", ""),
            "photo": get_profile_photo_data_uri(d, require_approval=False),
            # ---- extra fields so the showcase card can look like the
            # My Matches profile card (age, height, diet, bio, etc.) ----
            "age": _profile_age(d), "height_cm": d.get("height_cm"), "diet": d.get("diet", ""),
            "manglik": d.get("manglik", ""), "mother_tongue": d.get("mother_tongue", ""),
            "marital_status": d.get("marital_status", ""), "bio": d.get("bio", ""),
            "verified": d.get("id_verification_status") == "Verified",
        })
    return result


