def _initials_avatar_data_uri(name, size=200):
    """Per-person fallback avatar (coloured initial) used only when a
    member hasn't uploaded/approved a real photo yet. Colour is derived
    from the name itself, so two different people never end up showing
    the exact same picture \u2014 unlike a single shared stock placeholder
    image would."""
    clean = (name or "?").strip()
    initial = (clean[:1] or "?").upper()
    hue = (sum(ord(c) for c in clean) * 37) % 360 if clean else 210
    bg = f"hsl({hue},55%,42%)"
    svg = (
        f'<svg xmlns="http://www.w3.org/2000/svg" width="{size}" height="{size}" '
        f'viewBox="0 0 {size} {size}"><rect width="100%" height="100%" fill="{bg}"/>'
        f'<text x="50%" y="54%" font-family="Georgia,serif" font-size="{int(size * 0.42)}" '
        f'fill="#FFF3C4" font-weight="700" text-anchor="middle" dominant-baseline="middle">'
        f'{initial}</text></svg>'
    )
    return "data:image/svg+xml;base64," + base64.b64encode(svg.encode()).decode()


def render_registered_showcase():
    """Newly registered members \u2014 shown identically on Home, Search
    Partner, and Registration pages. Each member appears as the same kind
    of profile card used in My Matches (smaller photo), and the cards
    glide slowly from bottom to top one after another, like a live feed.
    Hover pauses the motion. Because moving HTML can't hold real buttons,
    a small "pick a member \u2192 View Full Profile" row sits below it.
    Silently does nothing if there aren't real registered profiles yet.
    Shows only the opposite gender to whoever is logged in (a male member
    sees female profiles here and vice versa), matching every other listing
    in the app; unfiltered only if nobody's gender is known yet."""
    profiles = db_list_recent_registered_profiles(limit=15, opposite_of_gender=get_own_gender())
    if not profiles:
        return

    st.markdown("<h3 style='text-align:center; color:#1A365D; margin-top:30px;'>\U0001F495 Newly Registered Members</h3>", unsafe_allow_html=True)

    cards = []
    for p in profiles:
        photo = p["photo"] or _initials_avatar_data_uri(p["name"])
        profession = (p.get("profession") or "").strip()
        if profession in NON_WORKING_PROFESSIONS:
            work_line = profession
        elif profession and p.get("income"):
            work_line = f"{profession} \u2022 {p['income']}"
        else:
            work_line = profession
        head_bits = []
        if p.get("age"):
            head_bits.append(f"{p['age']} yrs")
        if p.get("height_cm"):
            head_bits.append(f"{p['height_cm']} cm")
        if p.get("city"):
            head_bits.append(p["city"])
        head_extra = f" ({', '.join(head_bits)})" if head_bits else ""
        line2 = " \u2022 ".join(x for x in [work_line, p.get("diet"), p.get("manglik"), p.get("caste"), p.get("mother_tongue"), p.get("marital_status")] if x)
        line3 = " \u2022 ".join(x for x in [(p.get("education") or "")] if x)
        bio = (p.get("bio") or "").strip()
        bio_html = f"<div class='nm-bio'>\u201c{_html_escape(bio)}\u201d</div>" if bio else ""
        verified_html = "<span class='nm-ver'>\u2705 Verified Profile</span>" if p.get("verified") else ""
        cards.append(
            "<div class='nm-card'>"
            f"<img class='nm-photo' src='{photo}'>"
            "<div class='nm-body'>"
            f"<div class='nm-name'>{_html_escape(p['name'])}<span class='nm-sub'>{_html_escape(head_extra)}</span></div>"
            f"<div class='nm-line'>{_html_escape(line2)}</div>"
            f"<div class='nm-line'>{_html_escape(line3)}</div>"
            f"{bio_html}"
            f"<div class='nm-foot'>{verified_html}<span class='nm-live'>\U0001F7E2 Newly registered</span></div>"
            "</div></div>"
        )

    # ~9 seconds per card (bigger cards now, so a little more reading time).
    duration = max(len(cards) * 9, 18)
    st.markdown(f"""
<style>
.nm-window {{ --nmh: 370px; position: relative; height: var(--nmh); overflow: hidden; border-radius: 14px; background: #F8FAFC; border: 1px solid #E2E8F0; }}
.nm-track {{ position: absolute; left: 0; right: 0; top: 0; animation: nm-scroll {duration}s linear infinite; }}
.nm-window:hover .nm-track {{ animation-play-state: paused; }}
@keyframes nm-scroll {{ 0% {{ transform: translateY(370px); }} 100% {{ transform: translateY(-100%); }} }}
.nm-card {{ display: flex; gap: 18px; align-items: center; min-height: 3in; box-sizing: border-box; margin: 10px; padding: 14px 16px; background: white; border-radius: 14px; border: 1px solid #EAEAEA; box-shadow: 0 6px 14px rgba(0,0,0,0.06); }}
.nm-photo {{ width: 2in; height: 3in; flex: 0 0 2in; border-radius: 12px; object-fit: cover; border: 3px solid #D4AF37; }}
.nm-body {{ min-width: 0; flex: 1 1 auto; }}
.nm-name {{ font-size: 1.4rem; font-weight: 900; color: #1A365D; line-height: 1.25; }}
.nm-sub {{ font-size: 1.05rem; font-weight: 800; color: #475569; }}
.nm-line {{ color: #1E293B; font-size: 1.08rem; font-weight: 700; line-height: 1.4; margin-top: 6px; }}
.nm-bio {{ color: #334155; font-size: 1.02rem; font-weight: 600; font-style: italic; line-height: 1.4; margin-top: 8px; }}
.nm-foot {{ margin-top: 10px; font-size: 0.98rem; }}
.nm-ver {{ color: #166534; font-weight: 800; margin-right: 12px; }}
.nm-live {{ color: #B45309; font-weight: 800; }}
@media (max-width: 600px) {{
  .nm-window {{ --nmh: 620px; }}
  @keyframes nm-scroll {{ 0% {{ transform: translateY(620px); }} 100% {{ transform: translateY(-100%); }} }}
  .nm-card {{ flex-direction: column; align-items: center; text-align: center; }}
}}
</style>
<div class="nm-window"><div class="nm-track">{''.join(cards)}</div></div>
""", unsafe_allow_html=True)

    # ---- Real, clickable way to open someone's full profile (buttons
    # can't live inside the moving HTML above). ----
    pick_col, btn_col = st.columns([3, 1])
    labels = {f"{p['name']}" + (f" \u2014 {p['city']}" if p.get("city") else ""): p["email"] for p in profiles if p.get("email")}
    if labels:
        choice = pick_col.selectbox("Open a member's full profile", list(labels.keys()), key="showcase_pick", label_visibility="collapsed")
        if btn_col.button("\U0001F441\uFE0F View Full Profile", key="showcase_view_btn", use_container_width=True):
            st.session_state.global_viewing_profile_email = labels[choice]
            st.rerun()


def _render_profile_detail_fields(r, membership_tier=None):
    """Shared A-to-Z detail field list used by both the popup dialog
    (My Matches / AI Recommendations) and the full-page detail view
    (Search Partner)."""
    em_dash = "\u2014"
    match_line = f" \u2B50 {r['match']}% Match" if r.get("match") else ""
    st.markdown(f"## {r.get('name','')}, {r.get('age','')}{match_line}")
    st.caption(f"\U0001F4CD {r.get('city','')} \u2022 {r.get('marital_status','')}")
    detail_rows = [
        ("\U0001F393 Education", r.get("education")),
        ("\U0001F4BC Profession", r.get("profession")),
        ("\U0001F4B0 Income", r.get("income")),
        ("\U0001F6D5 Religion", r.get("religion")),
        ("\U0001F3F7\uFE0F Caste", r.get("caste")),
        ("\U0001F5E3\uFE0F Mother Tongue", r.get("mother_tongue")),
        ("\U0001F4CF Height", f"{r['height_cm']} cm" if r.get("height_cm") else None),
        ("\U0001F37D\uFE0F Diet", r.get("diet")),
        ("\U0001F6AC Habits", r.get("habits")),
        ("\u2728 Manglik", r.get("manglik")),
        ("\U0001F468\u200D\U0001F469\u200D\U0001F467 Family", (f"Father: {r.get('father_profession') or em_dash} | Mother: {r.get('mother_profession') or em_dash} | {r.get('num_brothers',0)} brother(s), {r.get('num_sisters',0)} sister(s)" if (r.get("num_brothers") is not None) else None)),
        ("\U0001F550 Status", r.get("active")),
    ]
    for label, val in detail_rows:
        if val:
            st.markdown(f"**{label}:** {val}")
    if r.get("shared_interests"):
        st.markdown(f"**\U0001F3AF Shared Interests:** {', '.join(r['shared_interests'])}")
    elif r.get("interests"):
        st.markdown(f"**\U0001F3AF Interests:** {', '.join(r['interests'])}")
    if membership_tier is not None:
        if membership_tier == "platinum" and r.get("phone"):
            st.markdown(f"**\U0001F4DE Phone:** {r['phone']}")
        else:
            st.markdown("**\U0001F4DE Phone:** \U0001F512 Platinum members only")
    if r.get("bio"):
        st.markdown("---")
        st.markdown(f"*\u201c{r['bio']}\u201d*")


def render_protected_profile_video(email):
    """Shows a member's approved intro video below their photo on the
    profile detail view, with the browser's native download button
    hidden and right-click/Picture-in-Picture disabled \u2014 a reasonable
    deterrent against casual downloading. Honest limitation: no
    browser-based player can fully stop someone from screen-recording
    their own device; true DRM (Widevine etc.) is out of scope here.
    Shows nothing if there's no video, or it isn't Approved yet."""
    if not email or not db_is_connected():
        return
    video_doc = db_get_profile_video(email)
    if not video_doc or video_doc.get("status") != "Approved":
        return
    video_bytes = media_get_bytes(video_doc.get("video_ref"))
    if not video_bytes:
        return
    st.markdown("##### \U0001F3A5 Video Profile")
    b64 = base64.b64encode(video_bytes).decode()
    render_html(f"""
    <video controls controlsList="nodownload noremoteplayback" disablePictureInPicture
           oncontextmenu="return false" playsinline
           style="width:100%; border-radius:12px; background:#000; max-height:400px;">
        <source src="data:video/mp4;base64,{b64}" type="video/mp4">
        Your browser doesn't support video playback.
    </video>
    """)
    st.caption("\U0001F512 Viewing only \u2014 download and picture-in-picture are disabled for this video.")


@st.dialog("Profile Details", width="large")
def show_profile_detail_modal(r):
    """Reusable 'View Profile' popup: big photo + full details on screen,
    used by 'View Profile' buttons in My Matches and AI Smart
    Recommendations. Search Partner uses render_full_profile_detail_page
    (a full page, not a popup) instead \u2014 see that function."""
    dcol1, dcol2 = st.columns([1, 1.4])
    with dcol1:
        st.image(r.get("photo", "") or "https://images.unsplash.com/photo-1531123897727-8f129e1688ce?auto=format&fit=crop&w=500&q=80", use_container_width=True)
        if r.get("id_verified"):
            st.success("\U0001F194 Government ID Verified")
        if r.get("verified") and r.get("verified") != "Not Yet Verified":
            st.caption(f"\u2705 {r['verified']}")
        render_protected_profile_video(r.get("email"))
    with dcol2:
        _render_profile_detail_fields(r)
    if st.button("Close", use_container_width=True):
        st.rerun()


def render_full_profile_detail_page(r, membership_tier=None):
    """Full A-to-Z profile detail view for Search Partner's 'View
    Profile' \u2014 a real page (not a popup dialog) with a big HD photo at
    the top of the left column and, right below it, their Video Profile
    (if they have an admin-approved one) \u2014 so clicking a profile shows
    the photo first, then the video, then the full details beside them.
    The caller (Search Partner) is responsible for rendering the 'Back
    to Search Results' button below this, since going back needs to
    update that page's own session state."""
    dcol1, dcol2 = st.columns([1, 1.4])
    with dcol1:
        photo = r.get("photo", "") or "https://images.unsplash.com/photo-1531123897727-8f129e1688ce?auto=format&fit=crop&w=500&q=80"
        if membership_tier not in ("silver", "gold", "platinum"):
            st.markdown(f"<img src='{photo}' class='result-photo result-photo-blurred' style='width:100%; border-radius:14px;'>", unsafe_allow_html=True)
            st.caption("\U0001F512 Upgrade your membership to unlock this photo.")
        else:
            st.image(photo, use_container_width=True)
        if r.get("id_verified"):
            st.success("\U0001F194 Government ID Verified")
        if r.get("verified") and r.get("verified") != "Not Yet Verified":
            st.caption(f"\u2705 {r['verified']}")
        if r.get("is_boosted"):
            st.markdown("<span style='background:#FF8C00; color:white; padding:2px 10px; border-radius:10px; font-size:0.8rem; font-weight:800;'>\U0001F680 Boosted</span>", unsafe_allow_html=True)
        if membership_tier in ("silver", "gold", "platinum"):
            render_protected_profile_video(r.get("email"))
        else:
            st.caption("\U0001F512 Upgrade your membership to watch this member's Video Profile.")
    with dcol2:
        _render_profile_detail_fields(r, membership_tier=membership_tier)


def _profile_age(doc):
    if not doc.get("dob"):
        return None
    dob = doc["dob"]
    if isinstance(dob, str):
        try:
            dob = dt.date.fromisoformat(dob)
        except Exception:
            return None
    today = dt.date.today()
    return today.year - dob.year - ((today.month, today.day) < (dob.month, dob.day))


@cached_read("profile_blocks", "profiles")
def db_search_profiles(exclude_email, gender_wanted=None, limit=100):
    """Returns REAL registered profiles (status=Active), reshaped into the
    same dict shape the Search Partner / recommendation pages already
    render, so real and demo profiles can be filtered identically.

    Results are PRIORITIZED (never filtered out, except blocked profiles
    — see below) so the searcher doesn't have to dig through manual
    filters to find the most relevant people: same city + same caste +
    shared interests first, then same city, then same caste, then shared
    interests, then everyone else. True geographic "nearby city" ranking
    isn't possible yet since the city list has no latitude/longitude or
    state grouping behind it — this only matches on exact city name.

    "Who Can See Me" / mutual blocking: a block hides each side from the
    other's search results, but only for that one pair — anyone else can
    still see both profiles normally. See db_block_viewer()."""
    db = get_db()
    if db is None:
        return []
    block_records = db.profile_blocks.find({"$or": [{"blocker_email": exclude_email}, {"blocked_email": exclude_email}]})
    blockers = set()
    for b in block_records:
        blockers.add(b["blocker_email"])
        blockers.add(b["blocked_email"])
    blockers.add(exclude_email)
    # Listing rule: a member shows up in Search / Matches / Recommendations
    # ONLY after admin has verified BOTH the Aadhaar card (aadhaar_verified)
    # AND the profile photo (photo_status == "Approved").
    query = {"status": "Active", "aadhaar_verified": True, "photo_status": "Approved", "email": {"$nin": list(blockers)}}
    if gender_wanted and gender_wanted != "Any":
        query["gender"] = gender_wanted
    # Pull a larger pool than `limit` before re-ranking by relevance, then
    # trim down, so the most relevant results aren't cut off by whatever
    # order MongoDB happened to return them in.
    docs = list(db.profiles.find(query).limit(max(limit, 200)))

    viewer_profile = db_get_profile(exclude_email)
    viewer_city = (viewer_profile.get("city") or "").strip().lower() if viewer_profile else ""
    viewer_caste = (viewer_profile.get("caste") or "").strip().lower() if viewer_profile else ""
    viewer_interests = set(viewer_profile.get("interests") or []) if viewer_profile else set()

    def relevance_key(d):
        same_city = bool(viewer_city) and (d.get("city") or "").strip().lower() == viewer_city
        same_caste = bool(viewer_caste) and (d.get("caste") or "").strip().lower() == viewer_caste
        shared_interests = len(viewer_interests & set(d.get("interests") or []))
        # False < True in Python, so negating puts the best matches first;
        # negative shared_interests so a higher overlap sorts first too.
        return (not same_city, not same_caste, -shared_interests)

    docs.sort(key=relevance_key)
    docs = docs[:limit]

    reshaped = []
    for d in docs:
        # ---- BUG FIX: a registered profile with no/unparseable date-of-
        # birth used to be silently dropped ("continue") from every
        # listing this function feeds — Search Partner, My Matches, AND
        # AI Smart Recommendations — so a real registered member could
        # vanish from recommendations no matter what filters were applied,
        # from any city. A missing DOB should never hide someone; fall
        # back to a neutral age instead of skipping the profile. ----
        age = _profile_age(d)
        if age is None:
            age = 28
        photo_url = ""
        photo_refs = d.get("photo_refs") or []
        if photo_refs and d.get("photo_status") == "Approved":
            photo_bytes = media_get_bytes(photo_refs[0])
            if photo_bytes:
                photo_url = f"data:image/jpeg;base64,{base64.b64encode(photo_bytes).decode()}"
        reshaped.append({
            "email": d["email"], "name": d.get("name", "Siddhivinayak Matrimony Member"), "age": age,
            "city": d.get("city", ""), "religion": d.get("religion", ""), "manglik": d.get("manglik", ""),
            "caste": d.get("caste", ""), "diet": d.get("diet", ""), "habits": d.get("habits", ""),
            "marital_status": d.get("marital_status", ""), "height_cm": d.get("height_cm", 165),
            "mother_tongue": d.get("mother_tongue", ""), "profession": d.get("profession", ""),
            "education": d.get("education", ""), "income": d.get("income", ""),
            "verified": d.get("verified", "Not Yet Verified"), "active": "Registered on Siddhivinayak Matrimony",
            # ---- BUG FIX: used to fall back to one shared stock photo
            # for every member without an approved upload, making
            # unrelated profiles look like they had "the same photo".
            # Now each person without a real photo gets their own
            # unique (name-based) placeholder instead. ----
            "bio": d.get("bio", ""), "photo": photo_url or _initials_avatar_data_uri(d.get("name", "Siddhivinayak Matrimony Member")),
            "phone": d.get("phone", ""), "gender": d.get("gender", ""), "is_real": True,
            "father_profession": d.get("father_profession", ""), "mother_profession": d.get("mother_profession", ""),
            "num_brothers": d.get("num_brothers", 0), "num_sisters": d.get("num_sisters", 0),
            "interests": d.get("interests", []),
            "shared_interests": sorted(viewer_interests & set(d.get("interests") or [])),
            "id_verified": d.get("id_verification_status") == "Verified",
        })
    return reshaped


def db_get_one_profile_for_display(email):
    """Fetches a single real registered member's profile and reshapes it
    into the exact dict shape render_full_profile_detail_page() expects
    \u2014 the same shape db_search_profiles() builds for its results. Used
    by the clickable "Newly Registered Members" cards (Home / Search
    Partner) to open someone's full profile straight from that list."""
    d = db_get_profile(email)
    if not d:
        return None
    age = _profile_age(d)
    if age is None:
        age = 28
    photo_url = ""
    photo_refs = d.get("photo_refs") or []
    if photo_refs and d.get("photo_status") == "Approved":
        photo_bytes = media_get_bytes(photo_refs[0])
        if photo_bytes:
            photo_url = f"data:image/jpeg;base64,{base64.b64encode(photo_bytes).decode()}"
    return {
        "_uid": email, "email": d["email"], "name": d.get("name", "Siddhivinayak Matrimony Member"), "age": age,
        "city": d.get("city", ""), "religion": d.get("religion", ""), "manglik": d.get("manglik", ""),
        "caste": d.get("caste", ""), "diet": d.get("diet", ""), "habits": d.get("habits", ""),
        "marital_status": d.get("marital_status", ""), "height_cm": d.get("height_cm", 165),
        "mother_tongue": d.get("mother_tongue", ""), "profession": d.get("profession", ""),
        "education": d.get("education", ""), "income": d.get("income", ""),
        "verified": d.get("verified", "Not Yet Verified"), "active": "Registered on Siddhivinayak Matrimony",
        "bio": d.get("bio", ""), "photo": photo_url or _initials_avatar_data_uri(d.get("name", "Siddhivinayak Matrimony Member")),
        "phone": d.get("phone", ""), "gender": d.get("gender", ""), "is_real": True,
        "father_profession": d.get("father_profession", ""), "mother_profession": d.get("mother_profession", ""),
        "num_brothers": d.get("num_brothers", 0), "num_sisters": d.get("num_sisters", 0),
        "interests": d.get("interests", []), "shared_interests": [],
        "id_verified": d.get("id_verification_status") == "Verified",
        "is_boosted": bool(db_get_active_boost(email, "Profile")),
        "match": None,
    }


# =====================================================================
# MY FAVORITES & SHORTLIST \u2014 saved per account in MongoDB (kind =
# "favorite" or "shortlist"), so they survive logout/refresh and can be
# shown as full profiles from the round profile menu on every page.
# =====================================================================
@_invalidate_cache_after("profile_saves")
def db_set_profile_save(owner, target, kind, on, snapshot=None):
    """target is the person's `_uid` (their email for a real member, or
    'demo::Name::City' for a demo/sample profile — see how search results
    build `_uid`). BUG FIX: this used to only be called for real members
    with an email; demo/sample profiles (most of what a brand-new account
    sees in Search Partner) were silently never saved at all, so clicking
    Shortlist/Favorite on them looked like it worked but nothing showed up
    in My Shortlist / My Favorites afterwards. Now every profile can be
    saved. `snapshot` (name/city/age/profession/is_real) is stored so a
    demo profile — which has no DB document to re-fetch later — can still
    be displayed correctly on the saved-profiles page."""
    db = get_db()
    if db is None or not owner or not target:
        return False
    if on:
        update = {"$setOnInsert": {"saved_at": dt.datetime.utcnow()}}
        if snapshot:
            update["$set"] = {f"snapshot.{k}": v for k, v in snapshot.items()}
        db.profile_saves.update_one({"owner": owner, "target": target, "kind": kind}, update, upsert=True)
    else:
        db.profile_saves.delete_one({"owner": owner, "target": target, "kind": kind})
    return True


@cached_read("profile_saves")
def db_list_profile_saves(owner, kind):
    """Target ids (emails, or 'demo::...' ids) this person saved, newest first."""
    db = get_db()
    if db is None or not owner:
        return []
    return [d["target"] for d in db.profile_saves.find({"owner": owner, "kind": kind}).sort("saved_at", -1)]


@cached_read("profile_saves")
def db_list_profile_save_records(owner, kind):
    """Like db_list_profile_saves, but returns the stored snapshot too, so
    a demo/sample profile (no DB document of its own to re-fetch) can
    still be rendered on the My Favorites / My Shortlist page."""
    db = get_db()
    if db is None or not owner:
        return []
    out = []
    for d in db.profile_saves.find({"owner": owner, "kind": kind}).sort("saved_at", -1):
        snap = d.get("snapshot") or {}
        out.append({
            "target": d["target"], "is_real": bool(snap.get("is_real")),
            "name": snap.get("name") or d["target"], "city": snap.get("city", ""),
            "age": snap.get("age"), "profession": snap.get("profession", ""),
            "photo": snap.get("photo", ""),
        })
    return out


# ---- Favorite VENDORS: saved in MongoDB (kind="vendor_favorite") so they
# survive refresh/logout and show up in the round-menu "My Favorites" page
# together with favorite profiles. st.session_state.vendor_favorites is kept
# as a fast in-session copy of the same list. ----
def vendor_fav_sync():
    owner = st.session_state.get("user_email")
    if "vendor_favorites" not in st.session_state:
        st.session_state.vendor_favorites = []
    if not owner or not db_is_connected():
        return
    if st.session_state.get("_vendor_fav_synced_for") == owner:
        return
    try:
        db = get_db()
        saved = [d["target"] for d in db.profile_saves.find({"owner": owner, "kind": "vendor_favorite"}).sort("saved_at", -1)]
        for t_ in st.session_state.vendor_favorites:  # keep anything favorited before sync
            if t_ not in saved:
                saved.append(t_)
        st.session_state.vendor_favorites = saved
        st.session_state["_vendor_fav_synced_for"] = owner
    except Exception:
        pass


def vendor_fav_add(uid, v):
    if "vendor_favorites" not in st.session_state:
        st.session_state.vendor_favorites = []
    if uid not in st.session_state.vendor_favorites:
        st.session_state.vendor_favorites.append(uid)
    owner = st.session_state.get("user_email")
    if owner and db_is_connected():
        snap = {"name": v.get("name", ""), "category": v.get("category", ""), "city": v.get("city", ""),
                "phone": v.get("phone", ""), "tier": v.get("tier", "free"), "rating": v.get("rating", ""),
                "is_real": bool(v.get("is_real") and v.get("email")), "email": v.get("email", "")}
        try:
            db_set_profile_save(owner, uid, "vendor_favorite", True, snapshot=snap)
        except Exception:
            pass


def vendor_fav_remove(uid):
    if uid in st.session_state.get("vendor_favorites", []):
        st.session_state.vendor_favorites.remove(uid)
    owner = st.session_state.get("user_email")
    if owner and db_is_connected():
        try:
            db_set_profile_save(owner, uid, "vendor_favorite", False)
        except Exception:
            pass


def vendor_fav_clear():
    for u_ in list(st.session_state.get("vendor_favorites", [])):
        vendor_fav_remove(u_)
    st.session_state.vendor_favorites = []


def db_list_vendor_favorite_records(owner):
    db = get_db()
    if db is None or not owner:
        return []
    out = []
    for d in db.profile_saves.find({"owner": owner, "kind": "vendor_favorite"}).sort("saved_at", -1):
        snap = d.get("snapshot") or {}
        snap["target"] = d["target"]
        out.append(snap)
    return out


def render_favorite_button(col, owner, r, key):
    """Heart toggle for ANY profile card — real member or demo/sample —
    persisted so it survives logout/refresh. BUG FIX: this used to be
    disabled entirely for demo/sample profiles, which is most of what a
    brand-new account sees in Search Partner, so Favorite looked broken."""
    uid = r.get("_uid") or (r.get("email") if r.get("is_real") else None)
    if not uid:
        col.button("\u2661 Favorite", key=key, use_container_width=True, disabled=True)
        return
    is_fav = uid in set(db_list_profile_saves(owner, "favorite")) if db_is_connected() else False
    if col.button("\u2764\uFE0F Favorited" if is_fav else "\U0001F90D Favorite", key=key, use_container_width=True):
        snap = {"name": r.get("name", ""), "city": r.get("city", ""), "age": r.get("age"),
                "profession": r.get("profession", ""), "is_real": bool(r.get("is_real") and r.get("email"))}
        db_set_profile_save(owner, uid, "favorite", not is_fav, snapshot=snap)
        st.toast("\u2764\uFE0F Added to My Favorites" if not is_fav else "Removed from My Favorites")
        st.rerun()


def _render_favorite_vendors_section(owner):
    """All vendors this member has favorited (real + demo), listed on My Favorites."""
    vendor_fav_sync()
    recs = db_list_vendor_favorite_records(owner) if db_is_connected() else []
    # anything favorited in this session but not yet in DB (e.g. DB was offline)
    known = {r["target"] for r in recs}
    for u_ in st.session_state.get("vendor_favorites", []):
        if u_ not in known:
            nm = u_.split("::")[-1] if u_.startswith("demo::") else u_
            recs.append({"target": u_, "name": nm, "category": "", "city": "", "phone": "", "tier": "free", "is_real": not u_.startswith("demo::"), "email": "" if u_.startswith("demo::") else u_})
    st.markdown("### \U0001F3EA Favorite Vendors")
    if not recs:
        st.caption("No favorite vendors yet. Use \U0001FA76 Add to Favorites on any vendor in Wedding Services.")
        st.markdown("---")
        return
    st.caption(f"{len(recs)} vendor{'s' if len(recs) != 1 else ''} saved.")
    paid = st.session_state.get("is_paid_member", False)
    tier_chip = {"platinum": "\U0001F48E Platinum", "gold": "\U0001F947 Gold", "silver": "\U0001F948 Silver", "free": "Free Listing"}
    for i, v in enumerate(recs):
        with st.container(border=True):
            c1, c2 = st.columns([3, 2])
            bits = [x for x in [v.get("category", ""), v.get("city", "")] if x]
            c1.markdown(f"**{v.get('name','')}**" + (" \U0001F396\uFE0F" if v.get("is_real") else "") + f" \u2014 {tier_chip.get(v.get('tier','free'), 'Free Listing')}")
            if bits:
                c1.caption(" \u2022 ".join(bits))
            if v.get("tier", "free") == "free":
                c2.caption("\U0001F512 Number not shown (Free listing)")
            elif paid and v.get("phone"):
                c2.markdown(f"\U0001F4DE **{v['phone']}**")
            elif v.get("phone"):
                c2.caption("\U0001F512 Phone visible to paid members only")
            b1, b2 = st.columns(2)
            if b1.button("\U0001F4AC Message", key=f"fav_vendor_msg_{i}", use_container_width=True):
                st.session_state.chat_preselect_contact_id = v["target"]
                st.session_state.chat_preselect_contact = v.get("name", "")
                go_to("chat_alerts")
            if b2.button("\U0001F494 Remove", key=f"fav_vendor_rm_{i}", use_container_width=True):
                vendor_fav_remove(v["target"])
                st.toast("Removed from My Favorites")
                st.rerun()
    st.markdown("---")


def _render_extra_profile_fields(email):
    """Remaining registration details (beyond the common list) for the saved-profile cards."""
    d = db_get_profile(email) or {}
    rows = [
        ("\u2696\uFE0F Weight", f"{d['weight_kg']} kg" if d.get("weight_kg") else None),
        ("\U0001F4CD Birth Place", d.get("birth_place")),
        ("\U0001F550 Birth Time", d.get("birth_time")),
        ("\U0001F54A\uFE0F Gotra", d.get("gotra")),
        ("\U0001F3E0 Lives With Family", d.get("lives_with_family")),
        ("\U0001F46A Managed By", d.get("managed_by")),
    ]
    for label, val in rows:
        if val and str(val).strip() not in ("", "None"):
            st.markdown(f"**{label}:** {val}")
    pref = []
    if d.get("pref_age_range"):
        pref.append(f"Age {d['pref_age_range'][0]}\u2013{d['pref_age_range'][-1]}")
    if d.get("pref_min_height"):
        pref.append(f"Min height {d['pref_min_height']} cm")
    if d.get("pref_city") and d.get("pref_city") not in ("Any", "Select..."):
        pref.append(f"City: {d['pref_city']}")
    if pref:
        st.markdown(f"**\U0001F491 Partner Preference:** {' | '.join(pref)}")


def render_saved_profiles_page(kind):
    """Full-profile list for My Favorites (kind='favorite') or Shortlist
    (kind='shortlist', shown with a star). Every saved person gets:
    Message, Call, Remove and Send Interest buttons."""
    is_fav = kind == "favorite"
    title = "\u2764\ufe0f My Favorites" if is_fav else "\u2B50 My Shortlist"
    icon = "\u2764\ufe0f" if is_fav else "\u2B50"
    # This page never applied the global page styling before.
    render_global_css(bg_color="#F8F9FA")
    st.markdown(f"<h1 style='color:#1A365D;'>{title}</h1>", unsafe_allow_html=True)
    owner = st.session_state.get("user_email")
    if not db_is_connected() or not owner:
        st.info("\U0001F4F1 Connect MongoDB and log in to keep your saved profiles here.")
        return
    records = db_list_profile_save_records(owner, kind)
    if is_fav:
        _render_favorite_vendors_section(owner)
        st.markdown("### \U0001F464 Favorite Profiles")
    if not records:
        st.info("Nothing here yet. Use the " + ("\U0001F90D Favorite" if is_fav else "\u2606 Shortlist") + " button on any profile in Search Partner or My Matches.")
        return
    st.caption(f"{len(records)} profile{'s' if len(records) != 1 else ''} saved.")
    tier = st.session_state.get("membership_tier", "free")

    def _remove(target):
        db_set_profile_save(owner, target, kind, False)
        if not is_fav:
            st.session_state.my_matches_shortlist.discard(target) if "my_matches_shortlist" in st.session_state else None
            st.session_state.search_partner_shortlist.discard(target) if "search_partner_shortlist" in st.session_state else None
            st.session_state.chat_shortlist.discard(target) if "chat_shortlist" in st.session_state else None
        st.toast("Removed from My Favorites" if is_fav else "Removed from Shortlist")
        st.rerun()

    for i, rec in enumerate(records):
        target = rec["target"]
        r = None
        # A real member's profile is re-fetched live (fresh photo, bio,
        # phone, verification status). A demo/sample profile has no DB
        # document of its own, so it's rebuilt from the snapshot captured
        # at save time — this is the part that used to be missing
        # entirely, which is why saved demo profiles never showed up here.
        if rec["is_real"]:
            try:
                r = db_get_one_profile_for_display(target)
            except Exception:
                r = None
        if not r:
            r = {"name": rec["name"], "city": rec.get("city", ""), "age": rec.get("age"),
                 "profession": rec.get("profession", ""),
                 "photo": rec.get("photo") or DEMO_PROFILE_PHOTOS.get(rec["name"]) or _initials_avatar_data_uri(rec["name"]),
                 "phone": "", "id_verified": False, "is_real": rec["is_real"]}
        with st.container(border=True):
            st.markdown(f"<div style='text-align:right; font-size:1.6rem;'>{icon}</div>", unsafe_allow_html=True)
            if not rec["is_real"]:
                st.caption("\U0001F4CB Sample profile shown while browsing \u2014 not yet a registered member.")
            c1, c2 = st.columns([1, 2.4])
            with c1:
                blur = "" if tier in ("silver", "gold", "platinum") else " filter:blur(10px);"
                # Profile-style portrait photo (3:4), compact instead of full-width square.
                st.markdown(f"<img src='{r['photo']}' style='width:100%; max-width:190px; aspect-ratio:3/4; object-fit:cover; border-radius:12px; border:2px solid #D4AF37;{blur}'>", unsafe_allow_html=True)
                if blur != "":
                    st.caption("\U0001F512 Upgrade to unblur")
                if r.get("id_verified"):
                    st.success("\U0001F194 Government ID Verified")
            with c2:
                if rec["is_real"]:
                    try:
                        _render_profile_detail_fields(r, membership_tier=tier)
                        _render_extra_profile_fields(target)
                    except Exception:
                        st.markdown(f"## {r.get('name', '')}")
                else:
                    st.markdown(f"## {r['name']}")
                    bits = [x for x in [f"{r['age']} yrs" if r.get("age") else "", r.get("city", ""), r.get("profession", "")] if x]
                    if bits:
                        st.write(" \u2022 ".join(bits))
            b1, b2, b3, b4 = st.columns(4)
            if b1.button("\U0001F4AC Message", key=f"saved_msg_{kind}_{i}", use_container_width=True):
                st.session_state.chat_preselect_contact_id = target
                st.session_state.chat_preselect_contact = r["name"]
                go_to("chat_alerts")
            if b2.button("\U0001F4DE Call", key=f"saved_call_{kind}_{i}", use_container_width=True):
                phone = (r.get("phone") or "").strip()
                if not rec["is_real"]:
                    st.info("Calling is only available for registered members, not sample profiles.")
                elif tier == "platinum" and phone:
                    st.success(f"\U0001F4DE {r['name']}: **{phone}**")
                    st.markdown(f"<a href='tel:{phone}' style='display:block; text-align:center; background:#16A34A; color:white; padding:8px; border-radius:8px; font-weight:800; text-decoration:none;'>\U0001F4DE Tap to call {phone}</a>", unsafe_allow_html=True)
                elif tier == "platinum":
                    st.info(f"{r['name']} hasn't added a phone number yet \u2014 send a message instead.")
                else:
                    st.warning("\U0001F512 Contact numbers are a Platinum feature. Upgrade to unlock direct calling.")
                    if st.button("\U0001F451 Upgrade to Platinum", key=f"saved_upg_{kind}_{i}"):
                        go_to("vip_membership")
            if b3.button("\U0001F494 Remove" if is_fav else "\u2716\ufe0f Remove", key=f"saved_rm_{kind}_{i}", use_container_width=True, help="Remove from My Favorites" if is_fav else "Remove from Shortlist"):
                _remove(target)
            already_sent = target in st.session_state.get("search_partner_interest_sent", set())
            if b4.button("\u2705 Interest Sent" if already_sent else "\U0001F49B Send Interest", key=f"saved_int_{kind}_{i}", use_container_width=True, disabled=already_sent):
                st.session_state.setdefault("search_partner_interest_sent", set()).add(target)
                db_send_interest(owner, target)
                st.toast(f"\U0001F49B Interest sent to {r['name']}!")
                st.rerun()


