def db_notify_saved_search_alerts(new_profile_doc):
    """Called right after a new registration is saved. Emails anyone
    whose saved search criteria the new profile matches (opposite gender
    they want, age range, city, caste) — so people don't have to keep
    re-searching manually to catch new registrations."""
    db = get_db()
    if db is None or not new_profile_doc:
        return
    new_gender = new_profile_doc.get("gender")
    new_city = (new_profile_doc.get("city") or "").strip().lower()
    new_caste = (new_profile_doc.get("caste") or "").strip().lower()
    new_age = _profile_age(new_profile_doc)
    new_email = new_profile_doc.get("email")
    for saved in db.saved_searches.find({}):
        if saved.get("email") == new_email:
            continue
        c = saved.get("criteria") or {}
        wanted_gender = c.get("gender_wanted")
        if wanted_gender and wanted_gender != new_gender:
            continue
        age_min, age_max = c.get("age_range", [18, 60])
        if new_age is None or not (age_min <= new_age <= age_max):
            continue
        wanted_city = (c.get("city") or "").strip().lower()
        if wanted_city and wanted_city not in ("any city", "") and wanted_city != new_city:
            continue
        wanted_caste = (c.get("caste") or "").strip().lower()
        if wanted_caste and wanted_caste != new_caste:
            continue
        send_notification_email(
            saved["email"], "New Matches", "\U0001F514 A new profile matches your saved search on Siddhivinayak Matrimony!",
            "A new member just registered on Siddhivinayak Matrimony matching your saved search criteria!\n\n"
            "Log in and check Search Partner to view their profile.",
        )


