def notify_interest_email(from_email, to_email):
    """Emails the recipient that someone showed interest ('liked') in them.
    WhatsApp notification for this was a paid feature (Meta Business API);
    Email is free and already wired up via send_generic_email(). If the
    recipient hasn't upgraded to a paid membership, the sender's name is
    withheld ("Someone liked you") as an incentive to upgrade, matching
    the free-tier photo-blur behavior already used on Search Partner."""
    recipient_user = db_find_user(to_email)
    if not recipient_user:
        return
    is_paid = TESTING_MODE_ALL_FEATURES_FREE or bool(recipient_user.get("is_paid_member"))
    sender_profile = db_get_profile(from_email)
    sender_name = sender_profile.get("name") if (sender_profile and is_paid) else None

    if is_paid and sender_name:
        subject = f"\U0001F49B {sender_name} liked you on Siddhivinayak Matrimony!"
        body = (
            f"Good news! {sender_name} just showed interest in your profile on Siddhivinayak Matrimony.\n\n"
            f"Log in to view their profile and respond \u2014 they're waiting to hear from you!\n\n"
            f"https://bandhan.com/login"
        )
    else:
        subject = "\U0001F49B Someone liked you on Siddhivinayak Matrimony!"
        body = (
            "Good news! Someone on Siddhivinayak Matrimony just showed interest in your profile.\n\n"
            "Upgrade your membership to see exactly who it is and connect with them right away.\n\n"
            "Log in to Siddhivinayak Matrimony and visit VIP Membership to upgrade."
        )
    send_notification_email(to_email, "New Matches", subject, body, reply_to=(from_email if (is_paid and sender_name) else None))


@_invalidate_cache_after("activity_log", "interests", "profiles", "user_notifications")
def db_send_interest(from_email, to_email):
    db = get_db()
    if db is None:
        return False
    existing = db.interests.find_one({"from_email": from_email, "to_email": to_email})
    if existing:
        return True
    db.interests.insert_one({"from_email": from_email, "to_email": to_email, "status": "Pending", "sent_at": dt.datetime.utcnow()})
    # if the other person already sent US an interest, this makes it mutual
    reverse = db.interests.find_one({"from_email": to_email, "to_email": from_email})
    if reverse:
        db.interests.update_many(
            {"$or": [{"from_email": from_email, "to_email": to_email}, {"from_email": to_email, "to_email": from_email}]},
            # ---- matched_at added so "Matches Made Today" (Engagement
            # Dashboard) can be computed for real instead of showing N/A
            # \u2014 sent_at is the ORIGINAL interest time, which could be
            # days/weeks before the match actually became mutual. ----
            {"$set": {"status": "Matched", "matched_at": dt.datetime.utcnow()}},
        )
    # ---- WhatsApp "someone liked you" notification removed (paid Meta
    # Business API); replaced with a free email to the recipient instead. ----
    notify_interest_email(from_email, to_email)
    # ---- This used to only email the recipient \u2014 nothing showed up
    # in their own in-app Chat & Alerts feed, so "who sent me interest"
    # was invisible unless they happened to check email. Now it's also a
    # real in-app notification (and drives the red unread badge). ----
    sender_profile = db_get_profile(from_email)
    sender_name = (sender_profile or {}).get("name", "Someone")
    db_add_user_notification(
        to_email, "interest", f"{sender_name} sent you interest \U0001F49B",
        icon="\U0001F49B", link_view="chat_alerts", extra={"contact_id": from_email, "contact_name": sender_name},
    )
    to_profile = db_get_profile(to_email)
    db_log_activity(from_email, "interest_sent", (to_profile or {}).get("name", "a profile"), to_email)
    return True


