@cached_read("blocks", "interests", "profile_blocks", "profiles")
def db_list_mutual_matches(email, exclude_blocked=False):
    db = get_db()
    if db is None:
        return []
    docs = list(db.interests.find({"$or": [{"from_email": email}, {"to_email": email}], "status": "Matched"}))
    other_emails = {d["to_email"] if d["from_email"] == email else d["from_email"] for d in docs}
    matches = []
    for other_email in other_emails:
        if exclude_blocked and db_is_pair_blocked(email, other_email):
            continue
        profile = db_get_profile(other_email)
        if profile:
            age = _profile_age(profile)
            photo_url = ""
            photo_refs = profile.get("photo_refs") or []
            if photo_refs and profile.get("photo_status") == "Approved":
                photo_bytes = media_get_bytes(photo_refs[0])
                if photo_bytes:
                    photo_url = f"data:image/jpeg;base64,{base64.b64encode(photo_bytes).decode()}"
            matches.append({
                "email": other_email, "name": profile.get("name", "Siddhivinayak Matrimony Member"), "age": age,
                "city": profile.get("city", ""), "caste": profile.get("caste", ""), "profession": profile.get("profession", ""),
                # ---- Same fix as Search Partner: a unique per-person
                # placeholder instead of one shared stock photo. ----
                "bio": profile.get("bio", ""), "photo": photo_url or _initials_avatar_data_uri(profile.get("name", "Siddhivinayak Matrimony Member")),
            })
    return matches


