@cached_read("blocks")
def db_list_blocked(email):
    """Returns [{'id':..., 'name':...}, ...]. Falls back to treating legacy
    documents (saved before this fix, which only had 'blocked_name') as
    their own id, so nothing already blocked gets silently un-blocked."""
    db = get_db()
    if db is None:
        return []
    out = []
    for b in db.blocks.find({"email": email}):
        bid = b.get("blocked_id") or b.get("blocked_name")
        out.append({"id": bid, "name": b.get("blocked_name", bid)})
    return out


@cached_read("blocks")
def db_is_blocked(email, other_id):
    """Mutual: true if EITHER side has blocked the other. Once one side
    blocks, neither can message the other any more via this check \u2014
    but the block only affects this one pair; the blocked person's
    profile is completely unaffected for everyone else."""
    db = get_db()
    if db is None:
        return False
    forward = db.blocks.find_one({"email": email, "$or": [{"blocked_id": other_id}, {"blocked_name": other_id}]})
    if forward:
        return True
    reverse = db.blocks.find_one({"email": other_id, "$or": [{"blocked_id": email}, {"blocked_name": email}]})
    return reverse is not None


# =====================================================================
# REPORT & BLOCK / VIDEO-CALL SHARED HELPERS
# ---------------------------------------------------------------------
# * Public Profile ID (BND-XXXXXXXX) shown next to every name so a
#   person can be reported / called by ID.
# * "Pair-only" blocking: blocking someone hides you and them from each
#   other ONLY. Every other member can still see both profiles.
# * Company alerts: every safety report lands on the Company Dashboard
#   (and is e-mailed to the company inbox, if SMTP is configured).
# * In-app notifications for real users (video-call requests/reminders).
# =====================================================================
IST = dt.timezone(dt.timedelta(hours=5, minutes=30))
COMPANY_ALERT_EMAIL_DEFAULT = "support@firstchoiceinnovations.com"


def now_ist():
    return dt.datetime.now(IST)


def utc_to_ist(utc_naive):
    """MongoDB hands back naive UTC datetimes \u2014 show them in IST."""
    if utc_naive is None:
        return None
    if utc_naive.tzinfo is None:
        utc_naive = utc_naive.replace(tzinfo=dt.timezone.utc)
    return utc_naive.astimezone(IST)


def humanize_ago(utc_naive):
    if not utc_naive:
        return ""
    secs = (dt.datetime.utcnow() - utc_naive).total_seconds()
    if secs < 60:
        return "Just now"
    if secs < 3600:
        return f"{int(secs // 60)} min ago"
    if secs < 86400:
        return f"{int(secs // 3600)} hr ago"
    return utc_to_ist(utc_naive).strftime("%d %b %Y, %I:%M %p")


def profile_public_id(uid):
    """Short public Profile ID (e.g. BND-1A2B3C4D) for a member. Same
    value as the member's referral code, so it is stable and unique per
    account and the company can look a person up by it."""
    if not uid:
        return ""
    return generate_referral_code(str(uid))


@cached_read("users")
def db_lookup_user_by_public_id(public_id):
    """Resolve a typed Profile ID back to the real account (email+name)."""
    db = get_db()
    if db is None or not public_id:
        return None
    pid = str(public_id).strip().upper().lstrip("#")
    if not pid:
        return None
    found = db.users.find_one({"referral_code": pid}, {"email": 1, "name": 1})
    if found:
        return found
    # Older accounts may not have the referral_code field saved yet.
    for u in db.users.find({}, {"email": 1, "name": 1}).limit(20000):
        if u.get("email") and generate_referral_code(u["email"]) == pid:
            return u
    return None


# ---------------------------------------------------------------------
# Pair-only blocking
# ---------------------------------------------------------------------
def db_block_pair(blocker_email, blocked_uid, blocked_name=None):
    """Blocks ONE person for ONE person. Chat/video-call are blocked
    both ways (db.blocks) and, when the other person is a real account,
    the two also disappear from each other's Search Partner / My Matches
    / recommendations (db.profile_blocks). Nobody else is affected."""
    ok = db_block_profile(blocker_email, blocked_uid, blocked_name)
    if blocked_uid and "@" in str(blocked_uid):
        db_block_viewer(blocker_email, blocked_uid)
    return ok


def db_unblock_pair(blocker_email, blocked_uid):
    ok = db_unblock_profile(blocker_email, blocked_uid)
    if blocked_uid and "@" in str(blocked_uid):
        db_unblock_viewer(blocker_email, blocked_uid)
    return ok


@cached_read("blocks", "profile_blocks")
def db_is_pair_blocked(email_a, uid_b):
    """True if either side has blocked the other (any block type)."""
    db = get_db()
    if db is None or not email_a or not uid_b:
        return False
    if db_is_blocked(email_a, uid_b):
        return True
    if "@" in str(uid_b):
        hit = db.profile_blocks.find_one({"$or": [
            {"blocker_email": email_a, "blocked_email": uid_b},
            {"blocker_email": uid_b, "blocked_email": email_a},
        ]})
        return hit is not None
    return False


def open_report_for(name, uid):
    """Used by every \"Report & Block\" button: remembers WHO is being
    reported (name + stable id + public Profile ID) and opens the Report &
    Safety page with those fields already filled in."""
    uid = str(uid) if uid else ""
    email = uid if "@" in uid else None
    if email and not name and db_is_connected():
        prof = db_get_profile(email) or {}
        name = prof.get("name", email)
    st.session_state.report_target = {
        "name": name or uid, "uid": uid, "email": email, "public_id": profile_public_id(uid),
    }
    go_to("report_safety")


