def notify_company_of_report(report_id, ref_display, reporter, reported, reason, details, has_evidence, blocked):
    """Tells the company about a new safety report: (1) a dashboard alert
    and (2) an e-mail to the company inbox. reporter / reported are dicts
    with name, public_id, email. Returns (alert_saved, email_sent, info)."""
    reporter_label = reporter.get("name") or reporter.get("email") or "A member"
    reported_label = reported.get("name") or reported.get("public_id") or "a profile"
    title = f"{reporter_label} reported {reported_label}"
    blocked_txt = "Yes - only between these two profiles" if blocked else "No"
    body = "\n".join([
        f"A member has reported (and {'BLOCKED' if blocked else 'not blocked'}) another profile on Siddhivinayak Matrimony.",
        "",
        f"Reference: {ref_display}",
        f"Reason: {reason}",
        f"Details: {details or '(none given)'}",
        f"Evidence attached: {'Yes' if has_evidence else 'No'}",
        f"Blocked by reporter: {blocked_txt}",
        "",
        "REPORTED BY",
        f"  Name: {reporter.get('name') or '-'}",
        f"  Profile ID: {reporter.get('public_id') or '-'}",
        f"  Email: {reporter.get('email') or '-'}",
        "",
        "REPORTED PROFILE",
        f"  Name: {reported.get('name') or '-'}",
        f"  Profile ID: {reported.get('public_id') or '-'}",
        f"  Email: {reported.get('email') or 'not on file (demo / unregistered profile)'}",
        "",
        f"Time: {now_ist().strftime('%d %b %Y, %I:%M %p')} IST",
        "",
        "Open the Company Dashboard \u2192 Pending Safety Reports to review, warn, block or unblock.",
    ])
    alert_saved = db_add_company_alert("safety_report", title, body, {"report_id": report_id, "ref": ref_display})
    sent, info = send_generic_email(
        company_alert_email(), f"\U0001F6A8 [Siddhivinayak Matrimony Safety Report {ref_display}] {title}", body,
        reply_to=reporter.get("email") or None,
    )
    return alert_saved, sent, info


# ---------------------------------------------------------------------
# Notification Preference Center — category catalogue, shared by the
# settings page (page_notification_preferences, further down) and by
# every real notification trigger in this file. Previously the settings
# page only ever WROTE these to the database and nothing ever READ them
# back before sending a push/email, so every toggle was cosmetic. Now
# db_add_user_notification() (push) and send_notification_email() (email)
# both check here first, so turning a category or channel off actually
# stops that notification, and leaving it on guarantees it goes out.
# ---------------------------------------------------------------------
DEFAULT_NOTIFICATION_PREFS = {
    "New Matches": True, "Messages & Chat": True, "Family Meet Requests": True,
    "Boost / Offers & Promotions": False, "Daily Horoscope": False,
    "Wedding & Anniversary Reminders": True, "Vendor Booking Updates": True,
    "Marketing Emails": False,
}
DEFAULT_NOTIFICATION_CHANNELS = {"push": True, "email": True}

# Maps the internal "kind" tag already used at every db_add_user_notification()
# call site across the app to one of the 8 categories above.
NOTIFICATION_CATEGORY_BY_KIND = {
    "interest": "New Matches", "match": "New Matches", "profile_view": "New Matches", "shortlisted": "New Matches",
    "chat_message": "Messages & Chat", "vendor_message": "Messages & Chat", "vendor_reply": "Messages & Chat",
    "family_meet": "Family Meet Requests",
    "vendor_interest": "Vendor Booking Updates", "vendor_booking_update": "Vendor Booking Updates",
    "astro_accepted": "Vendor Booking Updates", "astro_declined": "Vendor Booking Updates",
    "astro_booking": "Vendor Booking Updates", "astro_paid": "Vendor Booking Updates",
    "boost_active": "Boost / Offers & Promotions", "daily_horoscope": "Daily Horoscope",
}


def _notification_category_for_kind(kind):
    if kind in NOTIFICATION_CATEGORY_BY_KIND:
        return NOTIFICATION_CATEGORY_BY_KIND[kind]
    if kind and kind.startswith("video_call"):
        return "Messages & Chat"
    return None  # not one of the 8 preference categories -> never gated


def db_get_notification_settings(email):
    """(prefs, channels) for `email`, merged over the defaults so a
    category/channel added after someone last saved still behaves
    sensibly instead of being silently treated as off."""
    prefs, channels = dict(DEFAULT_NOTIFICATION_PREFS), dict(DEFAULT_NOTIFICATION_CHANNELS)
    if not email:
        return prefs, channels
    loaded = db_load_notification_prefs(email)
    if loaded:
        prefs.update(loaded.get("prefs") or {})
        channels.update(loaded.get("channels") or {})
    return prefs, channels


def notification_allowed(email, category, channel):
    """True if `email` wants `category` notifications delivered on
    `channel` ("push" or "email"). `category=None` (a kind/email that
    isn't one of the 8 Notification Preference Center options, e.g.
    OTPs or admin mail) is always allowed \u2014 only the 8 listed
    categories are ever gated. In demo mode (no database) everything is
    allowed too, since there's nowhere for a real preference to live."""
    if category is None or not email or not db_is_connected():
        return True
    prefs, channels = db_get_notification_settings(email)
    return bool(prefs.get(category, True)) and bool(channels.get(channel, True))


