def send_notification_email(to_email, category, subject, body, reply_to=None):
    """Like send_generic_email(), but first checks the Notification
    Preference Center: if `to_email` has turned `category` or the Email
    channel off, the email is silently skipped (that's the point of the
    toggle) instead of sent. Returns the same (sent, info) shape as
    send_generic_email, with info="skipped_by_preference" when suppressed.
    Only use this for the 8 preference categories (New Matches, Messages
    & Chat, Family Meet Requests, Boost / Offers & Promotions, Daily
    Horoscope, Wedding & Anniversary Reminders, Vendor Booking Updates,
    Marketing Emails) \u2014 OTPs, password resets, complaint receipts and
    other account/security mail should keep calling send_generic_email
    directly so they can never be accidentally muted."""
    if not notification_allowed(to_email, category, "email"):
        return False, "skipped_by_preference"
    return send_generic_email(to_email, subject, body, reply_to=reply_to)


def get_chat_alerts_badge_count():
    """Total unread count for the little red badge next to 'Chat &
    Alerts' in the sidebar \u2014 persisted unread notifications (new
    interests, match/video-call updates, etc.) plus any pending
    interests waiting on a response, plus this session's simulated
    unread chat pings. Best-effort: chat pings are session-only since
    this prototype's demo chat isn't truly real-time between two real
    accounts."""
    email = st.session_state.get("user_email")
    total = sum((st.session_state.get("chat_unread") or {}).values())
    if db_is_connected() and email:
        total += db_count_unread_notifications(email)
        total += len(db_list_received_interests(email, status="Pending"))
    return total



# =====================================================================
# CONTACT-INFO FILTER — best-effort detection of phone numbers, emails,
# and "message me on WhatsApp/Instagram" style attempts inside chat text,
# including some common evasions (spelled-out digits, spaced-out digits).
# Used to keep free members chatting IN-APP (curiosity that drives a
# membership upgrade) instead of immediately exchanging numbers and
# leaving the platform. No filter can catch every possible deliberate
# evasion — this is a strong first line of defence, backed up by the
# Report & Safety flow (db_send_safety_warning) for anything that slips
# through and gets reported.
# =====================================================================
NUMBER_WORDS = {
    "zero": "0", "oh": "0", "one": "1", "two": "2", "three": "3", "four": "4", "for": "4",
    "five": "5", "six": "6", "seven": "7", "eight": "8", "ate": "8", "nine": "9",
    "double": "d", "triple": "t",
}

# ---- Stricter "phone-number fragment" check (used for ALL in-app chats,
# including client <-> vendor messages) --------------------------------
# A phone number is often leaked in pieces ("89933" in one message,
# "9326" in the next), with a digit spelled out ("eight 89933"), in Hindi
# ("नौ आठ चार पांच", "ek do teen char") or in Devanagari digits ("९३२६").
# So instead of only counting a whole message's digits we look at each
# RUN of digits / digit-words and block any run worth 4+ digits, unless it
# is clearly a year, a date, or a round amount of money / a headcount.
_DIGIT_WORDS = {
    "zero": 0, "shunya": 0, "one": 1, "ek": 1, "two": 2, "do": 2, "three": 3, "teen": 3, "four": 4,
    "char": 4, "chaar": 4, "five": 5, "paanch": 5, "panch": 5, "six": 6, "chhe": 6, "chhah": 6,
    "chah": 6, "che": 6, "seven": 7, "saat": 7, "eight": 8, "aath": 8, "nine": 9, "nau": 9, "nav": 9,
    "शून्य": 0, "जीरो": 0, "एक": 1, "दो": 2, "तीन": 3, "चार": 4, "पांच": 5, "पाँच": 5, "छह": 6,
    "छः": 6, "छे": 6, "सात": 7, "आठ": 8, "नौ": 9,
}
_DIGIT_MULT = {"double": 2, "dabal": 2, "triple": 3, "tripal": 3}
_MONEY_WORDS = {"rs", "inr", "rupees", "rupee", "\u20b9", "budget", "price", "cost", "fee", "fees",
                "charge", "charges", "amount", "quote", "package", "per"}
_UNIT_WORDS = {"rs", "inr", "rupees", "rupee", "lakh", "lakhs", "lac", "lacs", "k", "thousand", "guests",
               "guest", "people", "persons", "pax", "members", "plates", "plate", "sqft", "sq", "ft", "km",
               "kg", "rooms", "seats", "cars", "days", "hours", "hrs", "years", "yrs", "minutes", "mins", "cm", "inches"}
_DATE_RE = re.compile(r"\b(?:0?[1-9]|[12]\d|3[01])\s*[/\-.]\s*(?:0?[1-9]|1[0-2])\s*[/\-.]\s*(?:\d{4}|\d{2})\b")
_COMMA_NUM_RE = re.compile(r"(?<![\d,])\d{1,3}(?:,\d{2,3})+(?![\d,])")
_YEAR_RE = re.compile(r"(?:19|20)\d\d")


def _phone_fragment_runs(s):
    """Splits text into runs of consecutive digits / digit-words (allowing
    spaces, dashes, brackets etc. between them)."""
    runs, cur, prev_word, mult = [], None, "", 1
    toks = list(re.finditer(r"\d+|[a-z\u0900-\u097f]+|\s+|.", s))
    for i, m in enumerate(toks):
        t = m.group(0)
        if t.isdigit():
            if cur is None:
                cur = {"digits": 0, "nums": [], "words": 0, "before": prev_word, "after": ""}
            cur["digits"] += len(t)
            cur["nums"].append(t)
            mult = 1
        elif t in _DIGIT_WORDS:
            if cur is None:
                cur = {"digits": 0, "nums": [], "words": 0, "before": prev_word, "after": ""}
            cur["digits"] += mult
            cur["words"] += 1
            mult = 1
        elif t in _DIGIT_MULT:
            mult = _DIGIT_MULT[t]
        elif t.isspace() or (len(t) == 1 and t in "-+()/_*|"):
            pass
        elif t in (".", ","):
            nxt = toks[i + 1].group(0) if i + 1 < len(toks) else " "
            if nxt.isspace() and cur is not None:   # "guests. 2026" ends a sentence; "98.45" does not
                runs.append(cur)
                cur = None
        else:
            if cur is not None:
                cur["after"] = t
                runs.append(cur)
                cur = None
            prev_word = t
            mult = 1
    if cur is not None:
        runs.append(cur)
    return runs


def _fragment_run_is_benign(run):
    """A year (2026), a pair of years, or a ROUND amount / headcount next to
    a money word or unit (\u20b950,000 · 500000 rupees · 1200 guests)."""
    nums = run["nums"]
    if run["words"] or not nums:
        return False
    if len(nums) <= 2 and all(_YEAR_RE.fullmatch(n) for n in nums):
        return True
    ctx = run["before"] in _MONEY_WORDS or run["after"] in _UNIT_WORDS
    if ctx and len(nums) <= 2 and all(len(n) <= 8 and (n.endswith("00") or len(n) <= 3) for n in nums):
        return True
    return False


def _has_phone_fragments(lowered):
    import unicodedata
    s = "".join(str(unicodedata.digit(c, c)) if (c.isdigit() and not c.isascii()) else c for c in lowered)
    s = _DATE_RE.sub(" ", s)
    s = _COMMA_NUM_RE.sub(lambda m: " " if m.group(0).replace(",", "").endswith("00") else m.group(0), s)
    scattered = 0
    for run in _phone_fragment_runs(s):
        if _fragment_run_is_benign(run):
            continue
        if run["digits"] >= 4:
            return True
        scattered += sum(len(n) for n in run["nums"] if len(n) >= 2) + run["words"]
    # Many small chunks spread through one message that together add up to
    # most of a phone number ("984 ... 501 ... 110 ...").
    return scattered >= 8


def contains_contact_info(text):
    if not text:
        return False
    lowered = text.lower()

    # 1. Phone numbers \u2014 whole, partial ("89933", "9326"), spaced-out,
    #    spelled-out ("eight 89933", "double nine"), Hindi or Devanagari digits
    if _has_phone_fragments(lowered):
        return True

    # 2. Email addresses, including "at gmail dot com" style spelled-out attempts
    if re.search(r"[a-z0-9._%+-]+\s*@\s*[a-z0-9.-]+\s*\.\s*[a-z]{2,}", lowered):
        return True
    if re.search(r"\b(at|@)\s*(g\s*mail|gmail|yahoo|hotmail|outlook|rediffmail|i\s*cloud)\b", lowered):
        return True

    # 3. Spelled-out digits in a row (e.g. "nine one nine one eight...")
    words = re.findall(r"[a-z]+", lowered)
    run = best_run = 0
    for w in words:
        if w in NUMBER_WORDS:
            run += 1
            best_run = max(best_run, run)
        else:
            run = 0
    if best_run >= 5:
        return True

    # 4. Explicit mentions of taking the conversation off-platform / asking for a number
    if re.search(r"\b(whatsapp|whats\s*app|insta(gram)?\s*id|telegram|snapchat|call\s*me|my\s*number|contact\s*me\s*on|reach\s*me\s*at|my\s*(mobile|cell))\b", lowered):
        return True
    if re.search(r"\b((phone|mobile|contact|cell)\s*(no|num|number)|(mera|apna|aapka|apka|tumhara|tumhara)\s*(number|no|mobile|nambar)|number\s*(de\s*do|dena|bhejo|share|send)|(give|send|share)\s*(me\s*)?(your|ur)\s*(number|no|phone|mobile|contact)|(call|phone)\s*karo)\b", lowered):
        return True
    if re.search(r"(नंबर|नम्बर|व्हाट्?सएप|व्हाट्?सऐप|वॉट्?सएप|वाट्?सएप|व्हाट्सअप)", lowered):
        return True

    return False


