@_invalidate_cache_after("activity_log", "profile_views", "profiles", "user_notifications")
def db_log_profile_view(viewer_email, viewed_email):
    db = get_db()
    if db is None:
        return
    if viewer_email == viewed_email:
        return
    existing = db.profile_views.find_one({"viewer_email": viewer_email, "viewed_email": viewed_email})
    # ---- Notify the person being viewed \u2014 but only once per ~6 hours
    # per viewer, so re-opening the same profile a few times in a row
    # doesn't spam them with a dozen identical notifications. ----
    should_notify = (not existing) or (dt.datetime.utcnow() - existing.get("last_viewed_at", dt.datetime.min)) > dt.timedelta(hours=6)
    db.profile_views.update_one(
        {"viewer_email": viewer_email, "viewed_email": viewed_email},
        {"$set": {"last_viewed_at": dt.datetime.utcnow()}, "$inc": {"view_count": 1}},
        upsert=True,
    )
    if should_notify:
        viewer_profile = db_get_profile(viewer_email)
        viewer_name = (viewer_profile or {}).get("name", "Someone")
        db_add_user_notification(
            viewed_email, "profile_view", f"\U0001F441\uFE0F {viewer_name} viewed your profile",
            icon="\U0001F441\uFE0F", link_view="chat_alerts", extra={"contact_id": viewer_email, "contact_name": viewer_name},
        )
    db_log_activity(viewer_email, "profile_viewed", (db_get_profile(viewed_email) or {}).get("name", "a profile"), viewed_email)


