def db_log_page_view(view_name, email):
    """Best-effort page-view logging so the Engagement Dashboard's
    'Most-Used Features' chart can be built from real navigation instead
    of a hardcoded sample list. Fire-and-forget: never blocks or breaks
    navigation if MongoDB isn't connected or the write fails for any
    reason \u2014 analytics logging should never be able to break the app."""
    try:
        db = get_db()
        if db is not None:
            db.page_views.insert_one({"view": view_name, "email": email, "at": dt.datetime.utcnow()})
    except Exception:
        pass


def go_to(view_name):
    """The core of the fix: switch pages WITHOUT Streamlit treating it as a
    real page navigation. Sidebar never remounts because of this."""
    db_log_page_view(view_name, st.session_state.get("user_email"))
    st.session_state.current_view = view_name
    st.rerun()


