def t(text):
    """Translate a UI string to the current session's chosen language.
    Falls back to the original English text unchanged if no translation
    exists for that string/language yet \u2014 always safe to wrap any
    string in t(...), even ones not translated yet."""
    lang = st.session_state.get("user_language", "en")
    if lang == "en":
        return text
    return UI_TRANSLATIONS.get(lang, {}).get(text, text)


