def occupation_block(label_prefix, key_prefix):
    occ_type = st.selectbox(f"{label_prefix} Occupation Type", ["Select...", "Service", "Business", "Retired", "Homemaker", "Not Working"], key=f"{key_prefix}_occ_type")
    department = ""
    post = ""
    business_type = ""
    if occ_type == "Service":
        department = st.selectbox(f"{label_prefix} Department", DEPARTMENT_OPTIONS, key=f"{key_prefix}_dept")
        post = st.text_input(f"{label_prefix} Post / Designation", key=f"{key_prefix}_post", placeholder="e.g., Senior Manager")
    elif occ_type == "Business":
        business_type = st.selectbox(f"{label_prefix} Business Type", BUSINESS_TYPE_OPTIONS, key=f"{key_prefix}_biz")
    return occ_type, department, post, business_type


def encode_jpeg_to_target_band(img, target_min_kb=500, target_max_kb=700, quality_start=88):
    """Shared binary-search JPEG encoder used by both profile-photo
    compression and the Success Stories couple-photo frame below \u2014
    lands inside a target size band (in KB) without a fixed, one-size
    guess at quality. If the image can't be shrunk into the band, it
    keeps the closest attempt rather than looping forever."""
    def encode(q):
        buf = io.BytesIO()
        img.save(buf, format="JPEG", quality=q, optimize=True)
        return buf.getvalue()

    low, high = 35, 95
    best_bytes = encode(quality_start)
    for _ in range(8):
        test_q = (low + high) // 2
        test_bytes = encode(test_q)
        test_kb = len(test_bytes) / 1024
        best_bytes = test_bytes
        if target_min_kb <= test_kb <= target_max_kb:
            break
        if test_kb > target_max_kb:
            high = test_q - 1
        else:
            low = test_q + 1
        if low > high:
            break
    return best_bytes


def compress_uploaded_image(uploaded_file, quality=88, target_min_kb=500, target_max_kb=700, max_dimension=1920):
    """Compresses an uploaded photo down to a 500-700 KB target band while
    keeping it Full-HD-capable (longest side capped at 1920px) — so a 5-10
    MB phone-camera photo still looks crisp after compression instead of
    just being crushed with one fixed quality setting. Uses a resize (only
    if larger than max_dimension) plus a binary search over JPEG quality to
    land inside the target band. If the original is already smaller than
    the target band, it's kept as high-quality as possible without being
    artificially inflated to hit the target."""
    try:
        original_bytes = uploaded_file.getvalue()
        original_kb = len(original_bytes) / 1024
        img = Image.open(io.BytesIO(original_bytes))
        if img.mode in ("RGBA", "P"):
            img = img.convert("RGB")

        if max(img.size) > max_dimension:
            ratio = max_dimension / max(img.size)
            img = img.resize((int(img.size[0] * ratio), int(img.size[1] * ratio)), Image.LANCZOS)

        best_bytes = encode_jpeg_to_target_band(img, target_min_kb, target_max_kb, quality)

        compressed_bytes = best_bytes
        compressed_kb = len(compressed_bytes) / 1024
        return compressed_bytes, original_kb, compressed_kb, img
    except Exception:
        return None, None, None, None


def max_profile_photos(email=None):
    """2 free photo slots for everyone; paid (Silver/Gold/Platinum)
    members get 5. Checks the real DB membership record when available,
    falling back to the session's membership flag in demo mode."""
    if TESTING_MODE_ALL_FEATURES_FREE:
        return 5
    is_paid = False
    if email and db_is_connected():
        user = db_find_user(email)
        is_paid = bool(user and user.get("is_paid_member"))
    else:
        is_paid = bool(st.session_state.get("is_paid_member"))
    return 5 if is_paid else 2


