INDIAN_CITIES_SEARCH = INDIAN_CITIES[:-1]  # same list minus the trailing "Other"


def render_photo_preview_row(items, size_px=480):
    """Photo previews for Edit My Profile: each photo is a fixed ~5in x 5in
    square (480 CSS px = 5 inches at 96 dpi), placed side by side (wrapping
    to the next line only if the screen is too narrow), so nobody has to
    scroll a huge full-width image. items = [(image_bytes, caption), ...]"""
    tiles = []
    for data, caption in items:
        if not data:
            continue
        uri = "data:image/jpeg;base64," + base64.b64encode(data).decode()
        tiles.append(
            f"<figure style='margin:0; text-align:center;'>"
            f"<img src='{uri}' style='width:{size_px}px; height:{size_px}px; max-width:100%; aspect-ratio:1/1; object-fit:cover; border-radius:12px; border:2px solid #D4AF37;'>"
            f"<figcaption style='font-size:0.85rem; color:#64748B; margin-top:4px;'>{_html_escape(caption)}</figcaption></figure>"
        )
    if tiles:
        st.markdown(f"<div style='display:flex; flex-wrap:wrap; gap:16px; align-items:flex-start;'>{''.join(tiles)}</div>", unsafe_allow_html=True)


def page_edit_profile():
    render_global_css(bg_color="#F8F9FA", page_css=""".editprof-header { background: linear-gradient(135deg, #1A365D 0%, #0F2027 100%); padding: 30px; border-radius: 18px; color: white; text-align: center; border: 2px solid #D4AF37; margin-bottom: 25px; }
.sync-pill { display:inline-block; padding: 4px 12px; border-radius: 20px; font-size: 0.8rem; font-weight: 600; }""")

    render_name_note()
    user_email = st.session_state.get("user_email") or ""
    sync_ok = db_is_connected()
    profile = db_get_profile(user_email) if sync_ok else None

    # ---- The registered person's own photo now shows right beside the
    # "Edit My Profile" heading, bypassing the moderation-approval gate
    # (it's their own account) so it's visible immediately after upload. ----
    photo_uri = get_profile_photo_data_uri(profile, require_approval=False) if profile else None
    photo_html = (
        f'<img src="{photo_uri}" style="width:90px; height:90px; border-radius:50%; '
        f'object-fit:cover; border:3px solid #D4AF37; box-shadow:0 4px 10px rgba(0,0,0,0.3); '
        f'margin-right:22px; flex-shrink:0;">'
        if photo_uri else ""
    )
    render_html(f"""
    <div class="editprof-header" style="display:flex; align-items:center; justify-content:center; text-align:left;">
        {photo_html}
        <div>
            <h1 style="margin:0; font-family:'Georgia', serif;">\u270F\uFE0F Edit My Profile</h1>
            <p style="color:#FBF5B7; margin-top:8px;">Keep your profile up to date so your matches stay accurate.</p>
        </div>
    </div>
    """)

    if not sync_ok:
        st.warning("\u26A0\uFE0F Demo mode: connect MongoDB to load and save your real profile here. Complete Registration first if you haven't yet.")
        return

    if not profile:
        st.info("You haven't completed your matrimonial profile yet.")
        if st.button("\U0001F4DD Go to Registration", type="primary"):
            go_to("registration")
        return

    pill_style = "background:#DCFCE7; color:#166534;"
    st.markdown(f"<span class='sync-pill' style='{pill_style}'>\u2601\uFE0F Editing your live profile \u2014 changes are visible to others immediately (except new photos, which need re-approval)</span>", unsafe_allow_html=True)
    st.markdown("<br>", unsafe_allow_html=True)

    completeness_pct, missing_fields = profile_completeness(profile)
    st.markdown(f"##### \U0001F4CA Profile Completeness: {completeness_pct}%")
    st.progress(completeness_pct / 100)
    if missing_fields:
        st.caption(f"\u26A0\uFE0F Add these to get more matches: {', '.join(missing_fields)}.")
    else:
        st.caption("\u2705 Your profile is fully complete \u2014 nice work!")
    st.markdown("<br>", unsafe_allow_html=True)

    with st.form("edit_profile_form"):
        c1, c2 = st.columns(2)
        with c1:
            name = st.text_input("Full Name", value=profile.get("name", ""))
            city = st.text_input("City", value=profile.get("city", ""))
            income = st.text_input("Annual Income", value=profile.get("income", ""))
            profession = st.text_input("Profession", value=profile.get("profession", ""))
        with c2:
            marital_status = st.selectbox("Marital Status", ["Never Married", "Divorced", "Widowed", "Separated", "Annulled"],
                                           index=["Never Married", "Divorced", "Widowed", "Separated", "Annulled"].index(profile.get("marital_status", "Never Married")) if profile.get("marital_status") in ["Never Married", "Divorced", "Widowed", "Separated", "Annulled"] else 0)
            diet = st.selectbox("Diet", ["Vegetarian", "Non-Vegetarian", "Eggetarian", "Vegan"],
                                 index=["Vegetarian", "Non-Vegetarian", "Eggetarian", "Vegan"].index(profile.get("diet", "Vegetarian")) if profile.get("diet") in ["Vegetarian", "Non-Vegetarian", "Eggetarian", "Vegan"] else 0)
            habits = st.text_input("Drinking / Smoking Habits", value=profile.get("habits", ""))
            phone = st.text_input("Phone", value=profile.get("phone", ""))

        bio = st.text_area("About Me / Bio", value=profile.get("bio", ""), height=100)
        interests_selected = st.multiselect("Interests & Hobbies (helps us match you with like-minded people)", INTEREST_OPTIONS, default=[i for i in (profile.get("interests") or []) if i in INTEREST_OPTIONS], max_selections=8)

        # ---- These were all collected at Registration but had NO way to be
        # edited afterward — Religion, Education, Mother Tongue, Height,
        # Weight, and Manglik Status were locked forever once you registered. ----
        st.markdown("##### Background Details")
        bg1, bg2, bg3 = st.columns(3)
        with bg1:
            religion_options = ["Hindu", "Muslim", "Sikh", "Christian", "Jain", "Other"]
            current_religion = profile.get("religion", "Hindu")
            religion_idx = religion_options.index(current_religion) if current_religion in religion_options else religion_options.index("Other")
            religion = st.selectbox("Religion", religion_options, index=religion_idx)
            custom_religion_edit = ""
            if religion == "Other":
                custom_religion_edit = st.text_input("Specify Religion", value=current_religion if current_religion not in religion_options else "")
            caste = st.text_input("Community / Caste", value=profile.get("caste", ""))
        with bg2:
            education_options = ["10th Pass", "12th Pass", "Diploma", "Graduate", "Post Graduate", "B.Tech / B.E.", "MBA / PG", "MBBS / MD", "Doctorate", "Other"]
            current_education = profile.get("education", "Graduate")
            education_idx = education_options.index(current_education) if current_education in education_options else education_options.index("Other")
            education = st.selectbox("Highest Education", education_options, index=education_idx)
            custom_education_edit = ""
            if education == "Other":
                custom_education_edit = st.text_input("Specify Education", value=current_education if current_education not in education_options else "")
            mt_options = [o for o in MOTHER_TONGUE_OPTIONS if o != "Select..."]
            current_mt = profile.get("mother_tongue", "Hindi")
            mt_idx = mt_options.index(current_mt) if current_mt in mt_options else mt_options.index("Other")
            mother_tongue = st.selectbox("Mother Tongue", mt_options, index=mt_idx)
        with bg3:
            height_cm = st.number_input("Height (cm)", min_value=120, max_value=220, value=int(profile.get("height_cm", 165)))
            weight_kg = st.number_input("Weight (kg)", min_value=30, max_value=200, value=int(profile.get("weight_kg", 60)))
            manglik = st.selectbox("Manglik Status", ["Non-Manglik", "Manglik", "Anshik Manglik", "Not Sure"],
                                    index=["Non-Manglik", "Manglik", "Anshik Manglik", "Not Sure"].index(profile.get("manglik", "Non-Manglik")) if profile.get("manglik") in ["Non-Manglik", "Manglik", "Anshik Manglik", "Not Sure"] else 0)

        st.markdown("##### Family Background")
        f1, f2, f3 = st.columns(3)
        father_profession = f1.text_input("Father's Profession", value=profile.get("father_profession", ""))
        mother_profession = f2.text_input("Mother's Profession", value=profile.get("mother_profession", ""))
        f3.write("")
        s1, s2 = st.columns(2)
        num_brothers = s1.number_input("Number of Brothers", min_value=0, max_value=15, value=int(profile.get("num_brothers", 0)))
        num_sisters = s2.number_input("Number of Sisters", min_value=0, max_value=15, value=int(profile.get("num_sisters", 0)))

        st.markdown("##### Partner Preferences")
        p1, p2, p3 = st.columns(3)
        pref_city = p1.text_input("Preferred City", value=profile.get("pref_city", ""))
        pref_min_height = p2.number_input("Minimum Height Preference (cm)", min_value=140, max_value=210, value=int(profile.get("pref_min_height", 150)))
        pref_gender_options = ["Male", "Female", "Other"]
        current_pref_gender = profile.get("pref_gender", "Male")
        pref_gender = p3.selectbox("Looking For", pref_gender_options, index=pref_gender_options.index(current_pref_gender) if current_pref_gender in pref_gender_options else 0)
        default_age_range = tuple(profile.get("pref_age_range", [25, 30])) if profile.get("pref_age_range") else (25, 30)
        pref_age_range = st.slider("Preferred Age Range", 21, 60, default_age_range)

        # ---- Privacy Settings were only ever set once, at Registration —
        # there was no way to change them afterward from here. ----
        st.markdown("##### \U0001F512 Privacy Settings")
        pv1, pv2 = st.columns(2)
        with pv1:
            photo_vis_options = ["Everyone (Recommended)", "Only Premium Members", "Only Members I Accept (Blur for others)"]
            current_photo_vis = profile.get("photo_visibility", "Everyone (Recommended)")
            photo_visibility = st.radio("Who can see your profile photos?", photo_vis_options,
                                         index=photo_vis_options.index(current_photo_vis) if current_photo_vis in photo_vis_options else 0)
            screenshot_block_enabled = st.toggle("Block Screenshots (Requires Platinum Plan)", value=bool(profile.get("screenshot_block_enabled", False)))
        with pv2:
            contact_vis_options = ["Hide Completely", "Show to Accepted Matches", "Show to Premium Members"]
            current_contact_vis = profile.get("phone_visibility", "Hide Completely")
            phone_visibility = st.selectbox("Phone Number Visibility", contact_vis_options,
                                             index=contact_vis_options.index(current_contact_vis) if current_contact_vis in contact_vis_options else 0)
            incognito_browsing = st.toggle("Incognito Mode (Browse silently)", value=bool(profile.get("incognito_browsing", False)))

        st.markdown("##### Photos")
        st.caption(f"Current status: **{profile.get('photo_status', 'No Photos')}**" + (" \u2014 re-uploading will require re-approval." if profile.get("photo_refs") else ""))
        # ---- 2 free photo slots; paid (Silver/Gold/Platinum) members get 5. ----
        edit_photo_limit = max_profile_photos(user_email)
        st.caption(f"You can upload up to {edit_photo_limit} photos on your current plan." + ("" if edit_photo_limit >= 5 else " Upgrade your membership in VIP Membership for more slots."))
        new_photos = st.file_uploader(f"Replace photos (optional, up to {edit_photo_limit})", type=["jpg", "jpeg", "png"], accept_multiple_files=True)

        # ---- Profile Photo vs Cover Photo picker: previously the first
        # uploaded photo was always used everywhere with no choice.
        # Profile Photo = shown on Search Partner / My Matches / cards.
        # Cover Photo = the bigger banner shown at the top of the left
        # sidebar menu. Only applies to already-saved photos \u2014 if you
        # upload new photos above in this same save, they start back at
        # the default (Photo 1 / Photo 2) and you can re-pick next time. ----
        existing_photo_refs = profile.get("photo_refs") or []
        profile_photo_index = profile.get("profile_photo_index", 0)
        cover_photo_index = profile.get("cover_photo_index", 1 if len(existing_photo_refs) > 1 else 0)
        if new_photos:
            # ---- Same chooser, but for photos being uploaded right now
            # in this save \u2014 previously this only appeared on a LATER
            # visit after the upload was already saved, which made the
            # feature easy to miss / feel like it didn't exist. ----
            _staged = new_photos[:edit_photo_limit]
            st.caption("Choose which of these uploaded photos is your main Profile Photo vs your Cover Photo (sidebar banner):")
            render_photo_preview_row([(pf.getvalue(), f"Photo {i + 1}") for i, pf in enumerate(_staged)])
            photo_options = [f"Photo {i + 1}" for i in range(len(_staged))]
            pp_col, cp_col = st.columns(2)
            profile_photo_choice = pp_col.selectbox("\U0001F464 Profile Photo", photo_options, index=0, key="new_profile_photo_choice")
            cover_photo_choice = cp_col.selectbox("\U0001F5BC\uFE0F Cover Photo (sidebar banner)", photo_options, index=min(1, len(photo_options) - 1), key="new_cover_photo_choice")
            profile_photo_index = photo_options.index(profile_photo_choice)
            cover_photo_index = photo_options.index(cover_photo_choice)
        elif existing_photo_refs:
            st.caption("Choose which of your current photos is your main Profile Photo vs your Cover Photo (sidebar banner):")
            render_photo_preview_row([(media_get_bytes(ref), f"Photo {i+1}") for i, ref in enumerate(existing_photo_refs)])
            photo_options = [f"Photo {i+1}" for i in range(len(existing_photo_refs))]
            pp_col, cp_col = st.columns(2)
            profile_photo_choice = pp_col.selectbox("\U0001F464 Profile Photo", photo_options, index=min(profile_photo_index, len(photo_options) - 1))
            cover_photo_choice = cp_col.selectbox("\U0001F5BC\uFE0F Cover Photo (sidebar banner)", photo_options, index=min(cover_photo_index, len(photo_options) - 1))
            profile_photo_index = photo_options.index(profile_photo_choice)
            cover_photo_index = photo_options.index(cover_photo_choice)

        st.markdown("##### \U0001F194 Government ID Verification")
        id_status = profile.get("id_verification_status")
        if id_status == "Verified":
            st.success("\u2705 Your Government ID is Verified \u2014 a trust badge shows on your profile to other members.")
        elif id_status == "Pending":
            st.info("\u23F3 Your Government ID is under review. We'll email you once it's checked.")
        elif id_status == "Rejected":
            st.warning("\u26A0\uFE0F Your last ID submission was rejected \u2014 please make sure the photo/scan is clear and upload again below.")
        else:
            st.caption("Upload your Aadhaar or PAN card to get a 'Government ID Verified' badge on your profile \u2014 builds extra trust with other members. This is checked manually by our team (not an automatic government database lookup).")
        id_doc_type = st.selectbox("Document type", ["Aadhaar Card", "PAN Card", "Passport", "Voter ID"], key="id_doc_type")
        id_doc_file = st.file_uploader("Upload a clear photo/scan of your ID", type=["jpg", "jpeg", "png", "pdf"], key="id_doc_upload")

        submitted = st.form_submit_button("\U0001F4BE Save Changes", type="primary", use_container_width=True)
        if submitted:
            final_religion_edit = custom_religion_edit.strip() if religion == "Other" and custom_religion_edit.strip() else religion
            final_education_edit = custom_education_edit.strip() if education == "Other" and custom_education_edit.strip() else education
            updated_fields = {
                "name": name.strip(), "city": city.strip(), "income": income.strip(), "profession": profession.strip(),
                "marital_status": marital_status, "diet": diet, "habits": habits.strip(), "phone": phone.strip(),
                "bio": bio.strip(), "interests": interests_selected, "pref_city": pref_city.strip(), "pref_min_height": pref_min_height,
                "father_profession": father_profession.strip(), "mother_profession": mother_profession.strip(),
                "num_brothers": num_brothers, "num_sisters": num_sisters,
                "religion": final_religion_edit, "caste": caste.strip(), "education": final_education_edit,
                "mother_tongue": mother_tongue, "height_cm": height_cm, "weight_kg": weight_kg, "manglik": manglik,
                "pref_gender": pref_gender, "pref_age_range": list(pref_age_range),
                "photo_visibility": photo_visibility, "screenshot_block_enabled": screenshot_block_enabled,
                "phone_visibility": phone_visibility, "incognito_browsing": incognito_browsing,
                "profile_photo_index": profile_photo_index, "cover_photo_index": cover_photo_index,
            }
            if new_photos:
                if len(new_photos) > edit_photo_limit:
                    st.warning(f"\u26A0\uFE0F Only the first {edit_photo_limit} photos will be used on your current plan \u2014 upgrade your membership for more slots.")
                photo_refs = []
                for i, photo_file in enumerate(new_photos[:edit_photo_limit]):
                    compressed_bytes, _, _, _ = compress_uploaded_image(photo_file, quality=90)
                    if compressed_bytes:
                        photo_refs.append(media_upload(compressed_bytes, f"profile_{i}.jpg", "image/jpeg"))
                updated_fields["photo_refs"] = photo_refs
                updated_fields["photo_status"] = "Pending Review"
                # ---- BUG FIX: this used to hard-reset to Photo 1 / Photo 2
                # no matter what the person just picked above, silently
                # throwing away their choice. Now it actually saves what
                # they chose (clamped in case fewer photos were kept than
                # slots picked from). ----
                updated_fields["profile_photo_index"] = min(profile_photo_index, len(photo_refs) - 1) if photo_refs else 0
                updated_fields["cover_photo_index"] = min(cover_photo_index, len(photo_refs) - 1) if photo_refs else 0
            saved_ok, save_error = db_save_profile(user_email, {**profile, **updated_fields})
            if save_error == "phone_duplicate":
                st.error("\u26A0\uFE0F This phone number is already registered on another account.")
            else:
                id_doc_submitted = False
                if id_doc_file is not None:
                    doc_bytes = id_doc_file.getvalue()
                    if id_doc_file.type and id_doc_file.type.startswith("image/"):
                        compressed_bytes, _, _, _ = compress_uploaded_image(id_doc_file, quality=92)
                        doc_bytes = compressed_bytes or doc_bytes
                    doc_ref = media_upload(doc_bytes, id_doc_file.name, id_doc_file.type or "application/octet-stream")
                    db_submit_id_verification(user_email, doc_ref, id_doc_type, doc_bytes=doc_bytes, mime_type=id_doc_file.type, registered_name=updated_fields.get("name"))
                    id_doc_submitted = True
                st.success("\u2705 Profile updated!" + (" New photos are queued for admin review." if new_photos else "") + (" Your Government ID has been submitted for verification." if id_doc_submitted else ""))
                st.rerun()

    # ---- "Who Can See Me": manage the list of people you've hidden your
    # profile from. Blocking itself happens from a "Block this profile"
    # button on Search Partner / My Matches; this is just the management
    # view. Outside the form above since Streamlit forms can't have
    # independent per-row action buttons. ----
    if sync_ok and profile:
        st.markdown("<br>", unsafe_allow_html=True)
        with st.expander("\U0001F3A5 Video Intro \u2014 record, replace or remove"):
            render_video_profile_section(user_email, sync_ok)
        with st.expander("\U0001F576\uFE0F Who Can See Me \u2014 Blocked Profiles"):
            st.caption("People you've hidden your profile from. They will never see you in Search Partner, My Matches, or AI Recommendations \u2014 they won't be notified.")
            blocked_list = db_list_blocked_viewers(user_email)
            if not blocked_list:
                st.caption("You haven't blocked anyone yet.")
            else:
                for b in blocked_list:
                    bp = db_get_profile(b["blocked_email"])
                    label = bp.get("name", b["blocked_email"]) if bp else b["blocked_email"]
                    bcol1, bcol2 = st.columns([3, 1])
                    bcol1.markdown(f"**{label}** ({b['blocked_email']})")
                    if bcol2.button("Unblock", key=f"unblock_{b['blocked_email']}", use_container_width=True):
                        db_unblock_pair(user_email, b["blocked_email"])
                        st.rerun()
            st.markdown("---")
            block_email_input = st.text_input("Block someone by their registered email", key="new_block_email", placeholder="name@example.com")
            if st.button("\U0001F6AB Block This Profile", key="new_block_submit"):
                target = block_email_input.strip().lower()
                if not target:
                    st.warning("Please enter an email address.")
                elif target == user_email:
                    st.warning("You can't block your own profile.")
                elif not db_get_profile(target):
                    st.warning("No registered profile found with that email.")
                else:
                    db_block_viewer(user_email, target)
                    st.success(f"\u2705 {target} can no longer see your profile.")
                    st.rerun()


def render_ask_jia_assistant():
    """A lightweight, free-text \"Ask JIA\" search assistant (the same
    idea referenced in the reference screenshot) \u2014 you type what you
    want in plain words and it picks out a city, an age, and a
    profession/keyword from that sentence, then shows a few matching
    real profiles right away, without having to touch the full filter
    form below. This is a simple keyword parser, not a general AI model
    \u2014 it recognizes known city names, numbers as ages, and a short list
    of common professions/keywords."""
    st.markdown("""
    <div style="background:linear-gradient(135deg,#7B1E3A,#4A1030); border-radius:14px; padding:18px 22px; margin-bottom:18px; color:white;">
    <b>\U0001F916 Ask JIA</b> <span style="opacity:0.85; font-size:0.85rem;">\u2014 your AI matchmaking assistant</span>
    </div>
    """, unsafe_allow_html=True)
    jia_col1, jia_col2 = st.columns([4, 1])
    with jia_col1:
        jia_query = st.text_input("Tell us what you're looking for", key="jia_query", placeholder="e.g. \u201ca teacher from Nagpur, around 26\u201d", label_visibility="collapsed")
    with jia_col2:
        jia_go = st.button("\U0001F50D Ask JIA", key="jia_search_btn", use_container_width=True)

    if not jia_go or not jia_query.strip():
        return

    q = jia_query.lower()
    own_gender = get_own_gender()
    gender_wanted = "Female" if own_gender == "Male" else ("Male" if own_gender == "Female" else None)

    found_city = next((c for c in INDIAN_CITIES_SEARCH if c.lower() in q), None)
    age_matches = [int(n) for n in re.findall(r"\b\d{2}\b", q) if 18 <= int(n) <= 70]
    found_age = age_matches[0] if age_matches else None
    KNOWN_KEYWORDS = ["teacher", "doctor", "engineer", "business", "banker", "ca", "chartered accountant",
                       "civil servant", "software", "nurse", "artist", "lawyer", "government", "professor"]
    found_keyword = next((k for k in KNOWN_KEYWORDS if k in q), None)

    my_email = st.session_state.get("user_email") or "guest@bandhan.com"
    candidates = db_search_profiles(my_email, gender_wanted) if db_is_connected() else []

    def jia_match(p):
        if found_city and (p.get("city") or "").strip().lower() != found_city.lower():
            return False
        if found_age is not None and abs((p.get("age") or 0) - found_age) > 3:
            return False
        if found_keyword and found_keyword not in (p.get("profession") or "").lower():
            return False
        return True

    picked = [p for p in candidates if jia_match(p)]
    understood_bits = []
    if found_city:
        understood_bits.append(f"city: **{found_city}**")
    if found_age is not None:
        understood_bits.append(f"age around **{found_age}**")
    if found_keyword:
        understood_bits.append(f"profession: **{found_keyword.title()}**")
    understood_txt = ", ".join(understood_bits) if understood_bits else "no specific city/age/profession recognized \u2014 showing general matches"
    st.caption(f"\U0001F916 JIA understood: {understood_txt}")

    if not db_is_connected():
        st.info("\U0001F4F1 Demo mode \u2014 connect MongoDB so JIA can search real registered profiles.")
        return
    if not picked:
        st.warning("\U0001F625 JIA couldn't find a matching profile for that \u2014 try the full filters below instead.")
        return

    for p in picked[:3]:
        jc1, jc2 = st.columns([1, 4])
        with jc1:
            st.markdown(f"<img src='{p['photo']}' style='width:100%; border-radius:8px; height:90px; object-fit:cover;'>", unsafe_allow_html=True)
        with jc2:
            st.markdown(f"**{p['name']}**, {p['age']} yrs \u2014 {p.get('profession','')} \u2022 {p.get('city','')}")
            jb1, jb2 = st.columns(2)
            if jb1.button("\u2B50 Shortlist", key=f"jia_short_{p['_uid']}", use_container_width=True):
                st.session_state.search_partner_shortlist.add(p["_uid"])
                db_set_profile_save(my_email, p["_uid"], "shortlist", True, snapshot={"name": p.get("name", ""), "city": p.get("city", ""), "age": p.get("age"), "profession": p.get("profession", ""), "is_real": bool(p.get("is_real") and p.get("email"))})
                st.rerun()
            already_sent = p["_uid"] in st.session_state.search_partner_interest_sent
            if jb2.button("\u2705 Sent" if already_sent else "\U0001F49B Interest", key=f"jia_int_{p['_uid']}", use_container_width=True, disabled=already_sent):
                st.session_state.search_partner_interest_sent.add(p["_uid"])
                if p.get("is_real") and p.get("email"):
                    db_send_interest(my_email, p["email"])
                st.success(f"\U0001F49B Interest sent to {p['name']}!")
                st.rerun()
    st.markdown("---")


def render_search_partner_card_view(results, searcher_email, membership_tier):
    """Swipe-card style single-profile browsing \u2014 the same idea as the
    reference screenshot's Tinder-style card (one profile at a time,
    with Interest / Shortlist / Ignore / Chat as the four quick
    actions). Streamlit has no real swipe gesture, so Prev/Next buttons
    stand in for the swipe motion; everything else (badges, blur rules,
    actions) reuses the exact same data and handlers as the List view
    above, just laid out as one card instead of a long list."""
    idx = st.session_state.search_partner_card_idx
    if idx >= len(results):
        idx = 0
        st.session_state.search_partner_card_idx = 0
    r = results[idx]

    blur_class = "" if membership_tier in ("silver", "gold", "platinum") else " result-photo-blurred"
    is_most_compatible = idx == 0
    is_active_today = any(w in (r.get("active") or "").lower() for w in ("now", "today", "hour", "min"))
    is_verified = bool(r.get("id_verified")) or bool(r.get("verified") and r["verified"] not in ("Not Yet Verified", ""))

    badges_html = ""
    if is_most_compatible:
        badges_html += "<span style='background:white; color:#1A365D; padding:4px 12px; border-radius:14px; font-size:0.78rem; font-weight:800; margin-right:6px;'>\U0001F44D Most Compatible</span>"
    if is_active_today:
        badges_html += "<span style='background:#27AE60; color:white; padding:4px 12px; border-radius:14px; font-size:0.78rem; font-weight:800;'>\U0001F7E2 Active Today</span>"

    st.markdown(f"""
    <div style="border:3px solid #D4AF37; border-radius:18px; overflow:hidden; box-shadow:0 10px 25px rgba(0,0,0,0.12);">
        <div style="position:relative;">
            <img src="{r['photo']}" class="{blur_class.strip()}" style="width:100%; height:340px; object-fit:cover; display:block;">
            <div style="position:absolute; top:12px; left:12px;">{badges_html}</div>
        </div>
        <div style="background:linear-gradient(180deg, rgba(15,32,39,0.05), #0F2027); color:white; padding:18px 22px;">
            <h2 style="margin:0; font-family:'Georgia',serif;">{r['name']}, {r['age']} {"\u2705" if is_verified else ""}</h2>
            <p style="margin:6px 0 0; color:#E2E8F0;">{r.get('height_cm','')} cm \u2022 {r.get('city','')} \u2022 {r.get('caste','')}</p>
            <p style="margin:2px 0 0; color:#E2E8F0;">{r.get('profession','')} \u2022 {r.get('income','')}</p>
            <p style="margin:2px 0 0; color:#E2E8F0;">{r.get('education','')}</p>
            <p style="margin:10px 0 0; color:#94A3B8; font-size:0.8rem;">\U0001F194 {profile_public_id(r['_uid'])} \u2022 {idx + 1} of {len(results)}</p>
        </div>
    </div>
    """, unsafe_allow_html=True)

    nav1, nav2, nav3 = st.columns([1, 3, 1])
    if nav1.button("\u2B05\uFE0F Prev", key="card_prev", use_container_width=True, disabled=(idx == 0)):
        st.session_state.search_partner_card_idx = max(0, idx - 1)
        st.rerun()
    if nav3.button("Next \u27A1\uFE0F", key="card_next", use_container_width=True, disabled=(idx >= len(results) - 1)):
        st.session_state.search_partner_card_idx = min(len(results) - 1, idx + 1)
        st.rerun()

    a1, a2, a3, a4, a5 = st.columns(5)
    already_sent = r["_uid"] in st.session_state.search_partner_interest_sent
    if a1.button("\u2705 Sent" if already_sent else "\U0001F49B Interest", key=f"card_int_{r['_uid']}", use_container_width=True, disabled=already_sent):
        st.session_state.search_partner_interest_sent.add(r["_uid"])
        if r.get("is_real") and r.get("email"):
            db_send_interest(searcher_email, r["email"])
        st.success(f"\U0001F49B Interest sent to {r['name']}!")
        st.rerun()
    is_shortlisted = r["_uid"] in st.session_state.search_partner_shortlist
    render_favorite_button(a5, searcher_email, r, f"card_fav_{r['_uid']}")
    if a2.button("\u2B50 Saved" if is_shortlisted else "\u2606 Shortlist", key=f"card_short_{r['_uid']}", use_container_width=True):
        db_set_profile_save(searcher_email, r["_uid"], "shortlist", not is_shortlisted, snapshot={"name": r.get("name", ""), "city": r.get("city", ""), "age": r.get("age"), "profession": r.get("profession", ""), "is_real": bool(r.get("is_real") and r.get("email"))})
        if is_shortlisted:
            st.session_state.search_partner_shortlist.discard(r["_uid"])
        else:
            st.session_state.search_partner_shortlist.add(r["_uid"])
        st.rerun()
    if a3.button("\u2716\uFE0F Ignore", key=f"card_ignore_{r['_uid']}", use_container_width=True):
        st.session_state.search_partner_not_interested.add(r["_uid"])
        db_log_activity(searcher_email, "not_interested", r["name"], r["_uid"])
        st.rerun()
    if a4.button("\U0001F4AC Chat", key=f"card_chat_{r['_uid']}", use_container_width=True):
        st.session_state.chat_preselect_contact_id = r["_uid"]
        st.session_state.chat_preselect_contact = r["name"]
        go_to("chat_alerts")


def page_search_partner():
    render_global_css(bg_color="#F8F9FA", page_css=""".search-header { background: linear-gradient(135deg, #0F2027 0%, #203A43 50%, #2C5364 100%); padding: 35px; border-radius: 15px; color: white; text-align: center; border-bottom: 5px solid #D4AF37; margin-bottom: 30px; box-shadow: 0 10px 25px rgba(0,0,0,0.15); }
.search-title { font-family: 'Georgia', serif; font-size: 2.8rem; font-weight: 900; margin: 0; background: linear-gradient(to right, #BF953F, #FCF6BA, #B38728, #FBF5B7, #AA771C); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
.filter-card { background: white; padding: 30px; border-radius: 15px; box-shadow: 0 10px 25px rgba(0,0,0,0.06); border: 1px solid #EAEAEA; }
.profile-result-card { background: white; padding: 20px; border-radius: 12px; margin-top: 15px; box-shadow: 0 5px 15px rgba(0,0,0,0.05); border-left: 6px solid #27AE60; border-top: 1px solid #EAEAEA; border-right: 1px solid #EAEAEA; border-bottom: 1px solid #EAEAEA; }
.result-photo { width: 100%; border-radius: 10px; height: 150px; object-fit: cover; }
.result-photo-blurred { filter: blur(10px); }
.tier-badge-gold { background: #D4AF37; color: white; padding: 3px 10px; border-radius: 12px; font-size: 0.72rem; font-weight: 800; }
.tier-badge-platinum { background: linear-gradient(90deg, #6D6D6D, #C0C0C0, #6D6D6D); color: white; padding: 3px 10px; border-radius: 12px; font-size: 0.72rem; font-weight: 800; }
.bio-snippet { color: #444; font-size: 0.88rem; font-style: italic; margin-top: 6px; }""")

    st.markdown("""
    <div class="search-header">
        <h1 class="search-title">Search Partner</h1>
        <p style="font-size:1.1rem; margin-top:10px; color:#FBF5B7; font-style:italic;">Filter through verified profiles to find your perfect life partner.</p>
    </div>
    """, unsafe_allow_html=True)

    if "search_partner_shortlist" not in st.session_state:
        st.session_state.search_partner_shortlist = set()
    if "search_partner_interest_sent" not in st.session_state:
        st.session_state.search_partner_interest_sent = set()
    if "search_partner_not_interested" not in st.session_state:
        st.session_state.search_partner_not_interested = set()
