# =====================================================================
# REAL PAYMENTS (Razorpay Payment Links)
#
# Before this, clicking any membership "Choose Plan" button just
# activated the plan instantly \u2014 no money was ever collected. Now, if
# RAZORPAY_KEY_ID + RAZORPAY_KEY_SECRET are set in Streamlit Secrets, the
# flow is: create a Razorpay Payment Link -> person pays on Razorpay's own
# hosted page -> they come back and click "I've paid \u2014 verify", and the
# membership is only activated after the server confirms with Razorpay's
# API that THAT link is really paid for the right amount. If the keys
# aren't set, it falls back to the old instant-activate demo behaviour
# (clearly labelled), so nothing breaks before you add your keys.
# =====================================================================
def razorpay_keys():
    try:
        return _secret("RAZORPAY_KEY_ID"), _secret("RAZORPAY_KEY_SECRET")
    except Exception:
        return None


def razorpay_create_payment_link(amount_rupees, description, customer_email):
    keys = razorpay_keys()
    if not keys:
        return None, "Razorpay keys not configured"
    try:
        resp = requests.post(
            "https://api.razorpay.com/v1/payment_links",
            auth=keys,
            json={
                "amount": int(amount_rupees) * 100,  # paise
                "currency": "INR",
                "description": description,
                "customer": {"email": customer_email},
                "notify": {"email": False, "sms": False},
                "reminder_enable": False,
            },
            timeout=15,
        )
        data = resp.json()
        if resp.status_code >= 400:
            return None, (data.get("error") or {}).get("description", f"Razorpay error {resp.status_code}")
        return {"id": data["id"], "url": data["short_url"]}, None
    except Exception as e:
        return None, f"Couldn't reach Razorpay: {e}"


def razorpay_link_is_paid(link_id, expected_amount_rupees):
    """True only if Razorpay itself says this link is 'paid' AND for the
    exact expected amount \u2014 never trusts anything the browser claims."""
    keys = razorpay_keys()
    if not keys:
        return False
    try:
        resp = requests.get(f"https://api.razorpay.com/v1/payment_links/{link_id}", auth=keys, timeout=15)
        data = resp.json()
        return resp.status_code == 200 and data.get("status") == "paid" and int(data.get("amount_paid", 0)) >= int(expected_amount_rupees) * 100
    except Exception:
        return False


@_invalidate_cache_after("payments")
def db_record_payment_once(link_id, email, tier, amount):
    """Returns False if this payment link was already used to activate a
    plan (prevents one payment being redeemed twice)."""
    db = get_db()
    if db is None:
        return False
    if db.payments.find_one({"link_id": link_id}):
        return False
    db.payments.insert_one({"link_id": link_id, "email": email, "tier": tier, "amount": amount, "at": dt.datetime.utcnow()})
    return True


def start_membership_purchase(tier, days, amount, plan_label, on_demo_success=None, session_key="membership_tier"):
    """Called by every paid 'Choose Plan' button. Live Razorpay flow when
    keys exist; otherwise the old demo instant-activate. Returns True only
    when the demo path activated immediately."""
    email = st.session_state.get("user_email", "")
    if razorpay_keys() and db_is_connected():
        link, err = razorpay_create_payment_link(amount, f"Siddhivinayak Matrimony {plan_label}", email)
        if err:
            st.error(f"\u26A0\uFE0F Couldn't start payment: {err}")
            return False
        st.session_state.pending_payment = {"link_id": link["id"], "url": link["url"], "tier": tier, "days": days,
                                            "amount": amount, "label": plan_label, "email": email, "session_key": session_key, "started": time.time()}
        st.rerun()
    if on_demo_success:
        on_demo_success()
    return True


def make_boost_receipt(kind, label, price, name_line):
    return f"""SIDDHIVINAYAK MATRIMONY \u2014 BOOST VISIBILITY RECEIPT
Type: {kind}
{name_line}
Plan: {label}
Amount Paid: {price}
Activated: {dt.datetime.now().strftime('%d %b %Y, %I:%M %p')}
"""


def activate_boost(bp):
    """Actually switches a boost on (session + MongoDB + notification +
    email + receipt). Called either right after Razorpay confirms payment,
    or immediately in demo mode when no Razorpay keys are configured.
    bp = dict(boost_type, key, label, price, hours, session_key, user_email)"""
    expires_at = dt.datetime.now() + dt.timedelta(hours=bp["hours"])
    boost_state = {"label": bp["label"], "expires_at": expires_at}
    if bp["boost_type"] == "Vendor":
        boost_state["name"] = bp["key"]
    st.session_state[bp["session_key"]] = boost_state
    if db_is_connected():
        db_save_boost(bp["key"], bp["boost_type"], bp["label"], bp["price"], expires_at)
        if bp.get("user_email"):
            what = "Profile Boost" if bp["boost_type"] == "Profile" else f"{bp['key']}'s listing boost"
            db_add_user_notification(
                bp["user_email"], "boost_active", f"\U0001F680 Your {bp['label']} {what} is now live!",
                icon="\U0001F680", link_view="boost_visibility",
            )
            send_notification_email(
                bp["user_email"], "Boost / Offers & Promotions", f"\U0001F680 Your {bp['label']} Boost is live \u2014 Siddhivinayak Matrimony",
                f"Your boost ({bp['label']}, {bp['price']}) is now active for the next {bp['hours'] // 24} days.\n\n\u2014 Team Siddhivinayak Matrimony",
            )
    receipt_key = "_last_boost_receipt" if bp["boost_type"] == "Profile" else "_last_boost_receipt_vendor"
    name_line = f"Account: {bp['user_email']}" if bp["boost_type"] == "Profile" else f"Business: {bp['key']}"
    st.session_state[receipt_key] = make_boost_receipt(f"{bp['boost_type']} Boost", bp["label"], bp["price"], name_line)


def start_boost_purchase(bp):
    """Called by every 'Activate Boost' button. With Razorpay keys: creates a
    payment link and the customer pays on Razorpay's billing page; the boost
    switches on automatically once the payment is confirmed. Without keys:
    old demo behaviour (activates immediately, no money collected)."""
    amount = int("".join(ch for ch in bp["price"] if ch.isdigit()) or 0)
    email = st.session_state.get("user_email", "")
    if razorpay_keys() and db_is_connected():
        link, err = razorpay_create_payment_link(amount, f"Siddhivinayak Matrimony Boost {bp['label']}", email)
        if err:
            st.error(f"\u26A0\uFE0F Couldn't start payment: {err}")
            return
        st.session_state.pending_payment = {
            "kind": "boost", "boost": bp, "link_id": link["id"], "url": link["url"], "tier": f"boost:{bp['boost_type']}:{bp['label']}",
            "amount": amount, "label": f"{bp['boost_type']} Boost \u2014 {bp['label']}", "email": email, "started": time.time(),
        }
    else:
        activate_boost(bp)
    st.rerun()


def _finish_pending_payment(p):
    """Runs once Razorpay says the link is paid. Returns True on success."""
    if not db_record_payment_once(p["link_id"], p["email"], p["tier"], p["amount"]):
        st.error("This payment was already used.")
        st.session_state.pending_payment = None
        return False
    if p.get("kind") == "boost":
        activate_boost(p["boost"])
    else:
        db_activate_membership(p["email"], p["tier"], p["days"])
        st.session_state.is_paid_member = True
        st.session_state[p.get("session_key", "membership_tier")] = p["tier"]
    st.session_state.pending_payment = None
    st.session_state.payment_success_msg = f"\U0001F389 Payment confirmed \u2014 {p['label']} is now active!"
    return True


def _pending_payment_body():
    p = st.session_state.get("pending_payment")
    if not p:
        return
    # Auto-check Razorpay every few seconds (up to 30 min) so the plan/boost
    # switches on by itself right after the customer pays.
    if time.time() - p.get("started", time.time()) < 1800 and razorpay_link_is_paid(p["link_id"], p["amount"]):
        if _finish_pending_payment(p):
            st.rerun()
        return
    with st.container(border=True):
        st.markdown(f"#### \U0001F4B3 Complete payment \u2014 {p['label']} (\u20b9{p['amount']:,})")
        st.link_button("\U0001F4B3 Pay now on Razorpay \u2192", p["url"], type="primary", use_container_width=True)
        st.caption("You'll get your billing/payment page. After paying, come back here \u2014 this box checks automatically and turns your plan on within a few seconds.")
        c1, c2 = st.columns(2)
        if c1.button("\u2705 I've paid \u2014 check now", key="verify_payment_btn", use_container_width=True):
            if razorpay_link_is_paid(p["link_id"], p["amount"]):
                if _finish_pending_payment(p):
                    st.rerun()
            else:
                st.warning("Payment not received yet. If you just paid, wait a few seconds and try again.")
        if c2.button("Cancel", key="cancel_payment_btn", use_container_width=True):
            st.session_state.pending_payment = None
            st.rerun()


def render_pending_payment():
    """Shows the 'Pay now' box for a payment that was started but not yet
    confirmed (membership or boost). Safe to call on every paid page."""
    if st.session_state.get("payment_success_msg"):
        st.balloons()
        st.success(st.session_state.pop("payment_success_msg"))
    p = st.session_state.get("pending_payment")
    if not p or p.get("email") != st.session_state.get("user_email", ""):
        return
    frag = getattr(st, "fragment", None)
    if frag:
        frag(run_every=5)(_pending_payment_body)()
    else:
        _pending_payment_body()


