# PAGE: REPORT & SAFETY
# =====================================================================
def page_report_safety():
    render_global_css(bg_color="#F8F9FA", page_css=""".safety-header { background: linear-gradient(135deg, #7B1113 0%, #1A365D 100%); padding: 30px; border-radius: 18px; color: white; text-align: center; border: 2px solid #D4AF37; margin-bottom: 25px; }
.safety-card { background: white; padding: 25px; border-radius: 15px; box-shadow: 0 8px 20px rgba(0,0,0,0.06); border: 1px solid #EAEAEA; }
.blocked-item { background: #FFF5F5; border-left: 4px solid #E53E3E; padding: 12px 15px; border-radius: 8px; margin-bottom: 10px; }
.report-history-item { background: #F8F9FA; border-left: 4px solid #D4AF37; padding: 12px 15px; border-radius: 8px; margin-bottom: 10px; }
.target-card { background: #FFFBEB; border: 2px solid #D4AF37; border-radius: 12px; padding: 12px 18px; margin-bottom: 12px; }""")

    import html as _html

    st.markdown("""
    <div class="safety-header">
        <h1 style="margin:0; font-family:'Georgia', serif;">\U0001F6A8 Report & Safety Center</h1>
        <p style="color:#FBF5B7; margin-top:8px;">Your safety matters. Report suspicious profiles and manage your blocked list.</p>
    </div>
    """, unsafe_allow_html=True)

    user_email = st.session_state.get("user_email") or "guest@bandhan.com"
    user_name = st.session_state.get("user_name") or ""
    sync_ok = db_is_connected()

    if sync_ok:
        st.session_state.blocked_profiles = db_list_blocked(user_email)
    elif "blocked_profiles" not in st.session_state:
        st.session_state.blocked_profiles = [{"id": "Unknown_User_4521", "name": "Unknown_User_4521"}, {"id": "Suspicious_Profile_882", "name": "Suspicious_Profile_882"}]
    if "report_history" not in st.session_state:
        st.session_state.report_history = []

    # Older entry points only set these two keys \u2014 fold them into the
    # single "report_target" the new form uses.
    legacy_id = st.session_state.pop("report_prefill_id", None)
    legacy_name = st.session_state.pop("report_prefill_name", None)
    if legacy_id or legacy_name:
        _uid = str(legacy_id or legacy_name)
        st.session_state.report_target = {
            "name": legacy_name or _uid, "uid": _uid, "email": _uid if "@" in _uid else None,
            "public_id": profile_public_id(_uid),
        }

    flash = st.session_state.pop("report_flash", None)
    if flash:
        st.success(flash)

    is_boss = st.session_state.get("user_role") == "boss"
    tab_labels = ["\U0001F6A9 Report a Profile", "\U0001F6AB Blocked Profiles"]
    if is_boss:
        tab_labels.append("\U0001F916 Fake Profile Detection (Admin)")
    tabs = st.tabs(tab_labels)
    tab1, tab2 = tabs[0], tabs[1]
    tab3 = tabs[2] if is_boss else None

    with tab1:
        st.markdown("<div class='safety-card'>", unsafe_allow_html=True)
        st.markdown("### Report Suspicious or Inappropriate Behaviour")
        nonce = st.session_state.get("report_form_nonce", 0)
        target = st.session_state.get("report_target")

        # ---- Name + Profile ID: filled in automatically when you arrive
        # via a "Report & Block" button (Search Partner, My Matches, Chat,
        # Video Call). Manual entry is only needed if you come here directly.
        if target:
            st.markdown(
                f"<div class='target-card'>\U0001F6A8 You are reporting <b>{_html.escape(str(target['name']))}</b> "
                f"&nbsp;\u2022&nbsp; Profile ID <b>{_html.escape(str(target['public_id']))}</b></div>",
                unsafe_allow_html=True,
            )
            f1, f2 = st.columns(2)
            f1.text_input("Profile Name (auto-filled)", value=str(target["name"]), disabled=True, key=f"rep_name_{target['uid']}")
            f2.text_input("Profile ID (auto-filled)", value=str(target["public_id"]), disabled=True, key=f"rep_pid_{target['uid']}")
            if st.button("\u2716 Report a different profile instead", key="rep_clear_target"):
                st.session_state.pop("report_target", None)
                st.rerun()
            manual_name = manual_pid = manual_email = ""
        else:
            m1, m2 = st.columns(2)
            manual_name = m1.text_input("Profile Name to Report", key=f"rep_manual_name_{nonce}")
            manual_pid = m2.text_input("Profile ID (e.g. BND-1A2B3C4D)", key=f"rep_manual_pid_{nonce}")
            manual_email = st.text_input("Their registered email, if you know it (optional)", key=f"rep_manual_email_{nonce}")
            st.caption("Tip: tap \U0001F6A8 Report & Block on any profile card, chat or video call and the name and ID fill in automatically.")

        reason = st.selectbox("Reason for Report", [
            "Fake / Misleading Profile", "Inappropriate Photos", "Harassment or Abusive Messages",
            "Asking for Money", "Already Married / Undisclosed Relationship", "Spam or Solicitation",
            "Asked for phone number / tried to move off Siddhivinayak Matrimony", "Other"
        ], key=f"rep_reason_{nonce}")
        details = st.text_area("Additional Details (optional)", key=f"rep_details_{nonce}")
        evidence = st.file_uploader("Attach Screenshot / Evidence (optional)", type=["jpg", "jpeg", "png", "pdf"], key=f"rep_evidence_{nonce}")
        also_block = st.checkbox(
            "\U0001F6AB Also block this profile \u2014 only for me. They stay visible to everyone else, and I can unblock any time.",
            value=True, key=f"rep_also_block_{nonce}",
        )

        if st.button("\U0001F6A9 Submit Report", type="primary", use_container_width=True, key=f"rep_submit_{nonce}"):
            error = None
            if target:
                rep_name, rep_uid, rep_email, rep_pid = target["name"], target["uid"], target.get("email"), target["public_id"]
            else:
                rep_name = (manual_name or "").strip()
                typed_pid = (manual_pid or "").strip().upper()
                rep_email = (manual_email or "").strip().lower() or None
                rep_uid = rep_pid = ""
                if not rep_name and not typed_pid and not rep_email:
                    error = "Please enter the profile name or ID you want to report."
                else:
                    if sync_ok and typed_pid:
                        found = db_lookup_user_by_public_id(typed_pid)
                        if found:
                            rep_email = rep_email or found.get("email")
                            rep_name = rep_name or found.get("name", "")
                    rep_uid = rep_email or typed_pid or rep_name
                    rep_pid = typed_pid or profile_public_id(rep_uid)
                    rep_name = rep_name or typed_pid or rep_email
            if not error and rep_email and rep_email == user_email:
                error = "You can't report your own profile."

            if error:
                st.warning(error)
            else:
                my_public_id = profile_public_id(user_email)
                evidence_ref = None
                if evidence is not None and sync_ok:
                    try:
                        evidence_ref = media_upload(evidence.getvalue(), evidence.name, evidence.type or "application/octet-stream")
                    except Exception:
                        evidence_ref = None

                ref_id = None
                if sync_ok:
                    ref_id = db_save_safety_report(
                        user_email, rep_name, reason, details, evidence is not None, reported_email=rep_email,
                        reporter_name=user_name, reporter_public_id=my_public_id, reported_public_id=rep_pid,
                        reported_uid=rep_uid, blocked=bool(also_block), evidence_ref=evidence_ref,
                    )
                ref_display = f"#{ref_id[-8:].upper()}" if ref_id else f"#RPT-{random.randint(10000, 99999)}"
                if not sync_ok:
                    st.session_state.report_history.append({
                        "ref": ref_display, "profile": rep_name, "reason": reason, "details": details,
                        "date": dt.datetime.now().strftime("%d %b %Y, %I:%M %p"),
                        "has_evidence": evidence is not None, "status": "Under Review", "reported_public_id": rep_pid,
                    })

                if also_block:
                    if sync_ok:
                        db_block_pair(user_email, rep_uid, rep_name)
                    elif not any(b["id"] == rep_uid for b in st.session_state.blocked_profiles):
                        st.session_state.blocked_profiles.append({"id": rep_uid, "name": rep_name})

                # ---- Tell the company right away: Company Dashboard alert + e-mail ----
                try:
                    notify_company_of_report(
                        ref_id or ref_display, ref_display,
                        {"name": user_name, "public_id": my_public_id, "email": user_email},
                        {"name": rep_name, "public_id": rep_pid, "email": rep_email},
                        reason, details, evidence is not None, bool(also_block),
                    )
                except Exception:
                    pass  # the report itself is already saved \u2014 never lose it over a notification hiccup

                # ---- Logged in the reporter's OWN Activity Log only \u2014
                # deliberately NOT sent as a notification to the reported
                # person. Telling someone "you were reported/blocked"
                # could let a bad-faith user figure out who reported them
                # and retaliate, which defeats the point of the safety
                # report. The company (Trust & Safety) is still notified
                # above, and the block itself already silently applies. ----
                db_log_activity(user_email, "reported_profile", rep_name, rep_uid, details=reason)

                msg = (f"\u2705 Report submitted against **{rep_name}** (Profile ID **{rep_pid}**). Reference: **{ref_display}**. "
                       "Our Trust & Safety team has been notified and will review within 24 hours.")
                if also_block:
                    msg += (f" \U0001F6AB **{rep_name}** is now blocked for you only \u2014 you won't see each other, "
                            "but everyone else on Siddhivinayak Matrimony can still see them. You can unblock from the Blocked Profiles tab.")
                st.session_state.report_flash = msg
                st.session_state.pop("report_target", None)
                st.session_state.report_form_nonce = nonce + 1
                st.rerun()
        st.markdown("</div>", unsafe_allow_html=True)

        report_history = db_list_my_safety_reports(user_email) if sync_ok else st.session_state.report_history
        if report_history:
            st.markdown("<div class='safety-card' style='margin-top:20px;'>", unsafe_allow_html=True)
            st.markdown("### \U0001F4CB Your Report History")
            for r in reversed(report_history) if not sync_ok else report_history:
                profile_field = r.get("profile") or r.get("profile_name", "")
                pid_field = r.get("reported_public_id")
                pid_txt = f" ({pid_field})" if pid_field else ""
                ref_field = r.get("ref") or f"#{str(r.get('_id',''))[-8:].upper()}"
                date_field = r.get("date") or (r.get("submitted_at", dt.datetime.utcnow()).strftime("%d %b %Y, %I:%M %p"))
                evidence_tag = " \U0001F4CE Evidence attached" if r.get("has_evidence") else ""
                details_html = f"<br><span style='color:#444; font-size:0.85rem;'>\u201c{_html.escape(str(r['details']))}\u201d</span>" if r.get("details") else ""
                st.markdown(f"""
                <div class="report-history-item">
                    <b>{ref_field}</b> \u2014 {_html.escape(str(profile_field))}{_html.escape(pid_txt)} \u2014 {_html.escape(str(r.get('reason','')))}{details_html}<br>
                    <span style="color:gray; font-size:0.85rem;">{date_field} \u2022 Status: {r.get('status','Under Review')}{evidence_tag}</span>
                </div>
                """, unsafe_allow_html=True)
            st.markdown("</div>", unsafe_allow_html=True)

    with tab2:
        st.markdown("<div class='safety-card'>", unsafe_allow_html=True)
        st.markdown("### Your Blocked Profiles")
        st.caption(
            "Blocking only hides you and that one person from each other (chat, video calls, search and matches). "
            "Everyone else can still see both of you. Only you \u2014 or the Siddhivinayak Matrimony Trust & Safety team \u2014 can unblock."
            if sync_ok else
            "\u26A0\uFE0F Demo mode: blocking here doesn't yet stop messages \u2014 connect MongoDB to make blocking actually enforced in Chat & Alerts."
        )
        if st.session_state.blocked_profiles:
            for b in list(st.session_state.blocked_profiles):
                c1, c2 = st.columns([4, 1])
                b_id = str(b["id"])
                id_txt = f" <span style='color:gray; font-size:0.8rem;'>\u2022 ID {profile_public_id(b_id)}</span>" if ("@" in b_id or b_id.startswith("demo::")) else ""
                c1.markdown(f"<div class='blocked-item'>\U0001F6AB {_html.escape(str(b['name']))}{id_txt}</div>", unsafe_allow_html=True)
                if c2.button("Unblock", key=f"unblock_{b['id']}"):
                    if sync_ok:
                        db_unblock_pair(user_email, b["id"])
                    else:
                        st.session_state.blocked_profiles = [x for x in st.session_state.blocked_profiles if x["id"] != b["id"]]
                    st.rerun()
        else:
            st.info("You haven't blocked any profiles yet.")
        st.markdown("</div>", unsafe_allow_html=True)

    if is_boss:
        with tab3:
            st.markdown("<div class='safety-card'>", unsafe_allow_html=True)
            st.markdown("### \U0001F916 AI Fake Profile Detection")
            st.write("Our AI continuously scans profiles for signs of fraud \u2014 stolen photos, inconsistent details, and suspicious activity patterns.")
            st.markdown("<br>", unsafe_allow_html=True)
            flagged = [
                {"id": "#BND-9021", "reason": "Reverse image search match found on stock photo site", "risk": "High"},
                {"id": "#BND-9187", "reason": "Multiple accounts from same device ID", "risk": "Medium"},
            ]
            for f in flagged:
                color = "#E53E3E" if f["risk"] == "High" else "#D4AF37"
                st.markdown(f"""
                <div style="background:white; border-left:5px solid {color}; padding:15px; border-radius:8px; margin-bottom:10px; box-shadow:0 4px 10px rgba(0,0,0,0.05);">
                    <b>{f['id']}</b> \u2014 Risk: <span style="color:{color}; font-weight:bold;">{f['risk']}</span><br>
                    <span style="color:gray; font-size:0.9rem;">{f['reason']}</span>
                </div>
                """, unsafe_allow_html=True)
            st.caption("Visible to Admin & Trust and Safety team only.")
            st.markdown("</div>", unsafe_allow_html=True)


