    TIER_ORDER = {"platinum": 0, "gold": 1, "silver": 2, "free": 3}
    TIER_LABEL = {"platinum": "\U0001F48E Platinum", "gold": "\U0001F947 Gold", "silver": "\U0001F948 Silver", "free": "Free Listing"}

    def get_sorted_vendors(category):
        # ---- BUG FIX: this page had its own separate hardcoded VENDORS
        # list, completely disconnected from real, admin-approved vendors
        # in the database \u2014 the same "vendor ecosystem" bug found and
        # fixed on Wedding Countdown / Vendor Marketplace, just missed
        # here since this page keeps its own copy of the vendor list. ----
        real_vendors = db_list_approved_vendors_for_category(category) if db_is_connected() else []
        real_entries = [
            {"name": rv.get("business_name", ""), "category": category, "city": rv.get("city", ""), "rating": 4.8,
             "phone": rv.get("contact_number", ""), "tier": db_get_vendor_tier(rv.get("registered_by_email") or rv.get("business_email")),
             "is_real": True, "email": rv.get("business_email", "")}
            for rv in real_vendors
        ]
        matched = real_entries + [v for v in VENDORS if v["category"] == category]
        # Boost Visibility promises boosted vendors "appear at the top of
        # the Verified Vendors Directory in their category" \u2014 wire that
        # in here instead of only sorting by tier.
        for v in matched:
            v["is_boosted"] = bool(db_is_connected() and db_get_active_boost(v["name"], "Vendor"))
        # Order: Platinum \u2192 Gold \u2192 Silver \u2192 Free. A boosted vendor goes first
        # WITHIN its own membership tier; ties are broken by rating.
        return sorted(matched, key=lambda v: (TIER_ORDER.get(v["tier"], 3), not v["is_boosted"], -float(v.get("rating") or 0)))

    def render_vendor_row(v, show_remove=False):
        v_uid = v["email"] if v.get("is_real") and v.get("email") else f"demo::{v['name']}"
        st.markdown(f"<div class='vendor-card tier-{v['tier']}'>", unsafe_allow_html=True)
        vc1, vc2, vc3 = st.columns([3, 1, 3])
        with vc1:
            real_tag = " \U0001F396\uFE0F" if v.get("is_real") else ""
            boost_tag = " <span style='background:#FF8C00; color:white; padding:1px 8px; border-radius:8px; font-size:0.7rem; font-weight:800;'>\U0001F680 Boosted</span>" if v.get("is_boosted") else ""
            st.markdown(f"**{v['name']}**{real_tag}{boost_tag} <span class='tier-chip-{v['tier']}'>{TIER_LABEL[v['tier']]}</span><br><span style='color:gray; font-size:0.85rem;'>{v['category']} \u2022 {v['city']}</span>", unsafe_allow_html=True)
        with vc2:
            st.markdown(f"\u2B50 {v['rating']}")
        with vc3:
            cols = st.columns(5) if show_remove else st.columns(4)
            b1, b2, b3, b4 = cols[0], cols[1], cols[2], cols[3]
            b5 = cols[4] if show_remove else None
            if v["tier"] == "free":
                # Free-listing vendors appear by NAME only \u2014 their phone number is
                # never shown to anyone (an upgrade unlocks it).
                b1.markdown("<div style='text-align:center; padding-top:4px; color:#94A3B8; font-size:0.78rem;'>\U0001F512 Number not shown<br>(Free listing)</div>", unsafe_allow_html=True)
            elif is_paid_member:
                b1.markdown(f"<div style='text-align:center; padding-top:6px;'>\U0001F4DE <b>{v['phone']}</b></div>", unsafe_allow_html=True)
            else:
                if b1.button("\U0001F4DE Call", key=f"call_{v_uid}", use_container_width=True):
                    st.warning("\U0001F512 Vendor phone numbers are visible to paid members only.")
            if b2.button("\U0001F4AC Message", key=f"msg_{v_uid}", use_container_width=True):
                st.session_state.chat_preselect_contact_id = v_uid
                st.session_state.chat_preselect_contact = v["name"]
                go_to("chat_alerts")
            already_fav = v_uid in st.session_state.vendor_favorites
            fav_label = "\u2764\uFE0F Saved" if already_fav else "\U0001FA76 Add to Favorites"
            if b3.button(fav_label, key=f"fav_{v_uid}", use_container_width=True, disabled=already_fav):
                vendor_fav_add(v_uid, v)
                st.toast(f"\u2764\uFE0F {v['name']} saved to your Favorite Vendors!")
                st.rerun()
            # ---- NEW: Send Interest \u2014 a VIP/paid feature (like phone
            # number visibility above). Sending interest hands the vendor
            # the client's own name + mobile number directly (via a real
            # in-app notification when the vendor is a real, registered
            # vendor account, plus an email either way) so the two of
            # them can start talking and book directly \u2014 exactly like
            # Send Interest already works between two matrimony profiles. ----
            if b4.button("\U0001F49B Send Interest", key=f"interest_{v_uid}", use_container_width=True):
                if not is_paid_member:
                    st.warning("\U0001F512 Send Interest to vendors is a VIP feature. Upgrade to VIP to share your contact details and get vendors to reach out to you directly.")
                else:
                    client_email = st.session_state.get("user_email") or ""
                    client_profile = db_get_profile(client_email) if db_is_connected() else None
                    client_name = (client_profile or {}).get("name") or st.session_state.get("user_name", "A Siddhivinayak Matrimony client")
                    client_phone = (client_profile or {}).get("phone", "")
                    if v.get("is_real") and v.get("email"):
                        db_add_user_notification(
                            v["email"], "vendor_interest", f"\U0001F49B {client_name} showed interest in your {v['category']} service",
                            icon="\U0001F49B", link_view="chat_alerts", extra={"contact_id": client_email, "contact_name": client_name},
                        )
                        send_notification_email(
                            v["email"], "Vendor Booking Updates", f"\U0001F49B {client_name} is interested in your {v['category']} service \u2014 Siddhivinayak Matrimony",
                            f"Hi,\n\n{client_name} showed interest in booking your {v['category']} service on Siddhivinayak Matrimony.\n\n"
                            f"Their contact number: {client_phone or 'not provided'}\n"
                            f"Their email: {client_email}\n\n"
                            "Reach out to them directly to discuss and confirm the booking.\n\n\u2014 Team Siddhivinayak Matrimony",
                            reply_to=client_email,
                        )
                        st.toast(f"\U0001F49B Interest sent to {v['name']} \u2014 they've been notified with your contact number.")
                    else:
                        st.toast(f"\U0001F49B Interest sent to {v['name']} (demo listing \u2014 no real account to notify).")
            if show_remove and b5.button("\U0001F5D1\uFE0F Remove", key=f"remove_fav_{v_uid}", use_container_width=True):
                vendor_fav_remove(v_uid)
                st.rerun()
        st.markdown("</div>", unsafe_allow_html=True)

