STORY_STATE_DISTRICTS = KUNDLI_STATE_DISTRICTS
STORY_ALL_STATES = KUNDLI_ALL_STATES
MAX_PHOTO_MB = 10


def count_faces_in_image(image_bytes):
    """Free, local, offline face detection (OpenCV's bundled Haar
    Cascade — no paid API, no internet call) used to make sure a Success
    Story photo actually shows a couple together, not a solo photo.
    Returns the face count, or None if OpenCV isn't installed (in which
    case the caller skips this check rather than blocking uploads)."""
    try:
        import cv2
        import numpy as np
        arr = np.frombuffer(image_bytes, dtype=np.uint8)
        cv_img = cv2.imdecode(arr, cv2.IMREAD_COLOR)
        if cv_img is None:
            return None
        gray = cv2.cvtColor(cv_img, cv2.COLOR_BGR2GRAY)
        cascade_path = cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
        face_cascade = cv2.CascadeClassifier(cascade_path)
        faces = face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(40, 40))
        return len(faces)
    except Exception:
        return None


def story_process_cinematic_photo(uploaded_file):
    """Builds the elegant gold-framed 'cinematic' couple photo shown on
    Success Stories. Requires a photo with the couple together (checked
    via free local face detection \u2014 imperfect, so it only blocks the
    clear case of 0-1 faces found, not a strict must-be-exactly-2 rule).
    Accepts uploads up to MAX_PHOTO_MB (10 MB) and compresses the final
    framed image down to a 500-800 KB target band (same technique as
    profile-photo compression) so it stays sharp without being a huge
    file."""
    raw_bytes = uploaded_file.getvalue()
    size_mb = len(raw_bytes) / (1024 * 1024)
    if size_mb > MAX_PHOTO_MB:
        return None, size_mb

    face_count = count_faces_in_image(raw_bytes)
    if face_count is not None and face_count < 2:
        return "single_person", size_mb

    img = Image.open(BytesIO(raw_bytes)).convert("RGB")
    canvas_w, canvas_h = 1920, 1080
    frame_thickness = 26
    inner_w, inner_h = canvas_w - frame_thickness * 2, canvas_h - frame_thickness * 2
    img_ratio = img.width / img.height
    inner_ratio = inner_w / inner_h

    if img_ratio > inner_ratio:
        new_w = inner_w
        new_h = int(inner_w / img_ratio)
    else:
        new_h = inner_h
        new_w = int(inner_h * img_ratio)

    resized = img.resize((new_w, new_h), Image.LANCZOS)

    # ---- Elegant gold double-border frame (matches the app's premium
    # gold/navy theme) instead of a plain black letterbox. ----
    canvas = Image.new("RGB", (canvas_w, canvas_h), (15, 23, 42))
    canvas.paste(resized, (frame_thickness + (inner_w - new_w) // 2, frame_thickness + (inner_h - new_h) // 2))
    draw = ImageDraw.Draw(canvas)
    gold = (212, 175, 55)
    draw.rectangle([6, 6, canvas_w - 7, canvas_h - 7], outline=gold, width=6)
    draw.rectangle([frame_thickness - 4, frame_thickness - 4, canvas_w - frame_thickness + 3, canvas_h - frame_thickness + 3], outline=gold, width=2)

    compressed_bytes = encode_jpeg_to_target_band(canvas, target_min_kb=500, target_max_kb=800, quality_start=90)
    return compressed_bytes, size_mb


