def horo_band(score):
    return "Excellent" if score >= 75 else "Good" if score >= 55 else "Mixed" if score >= 40 else "Cautious"


def horo_stars(ratio):
    n = max(1, min(5, int(round(1 + 4 * ratio))))
    return "★" * n + "☆" * (5 - n)


def _horo_swe():
    try:
        import swisseph as swe
        swe.set_sid_mode(swe.SIDM_LAHIRI)
        return swe
    except Exception:
        return None


def horo_engine_available():
    return _horo_swe() is not None


def _horo_jd(swe, date, hour_ist):
    """Julian day (UT) for a given IST clock time on a date."""
    ut = dt.datetime.combine(date, dt.time(0, 0)) + dt.timedelta(hours=hour_ist) - dt.timedelta(hours=5, minutes=30)
    return swe.julday(ut.year, ut.month, ut.day, ut.hour + ut.minute / 60 + ut.second / 3600)


def _horo_lon(swe, jd, body):
    flags = swe.FLG_SWIEPH | swe.FLG_SPEED | swe.FLG_SIDEREAL
    pos, _ = swe.calc_ut(jd, body, flags)
    return pos[0] % 360, pos[3] < 0


def horo_positions(swe, jd):
    """Sidereal (Lahiri) longitude + retrograde flag of every classical graha."""
    bodies = {"Sun": swe.SUN, "Moon": swe.MOON, "Mars": swe.MARS, "Mercury": swe.MERCURY, "Jupiter": swe.JUPITER,
              "Venus": swe.VENUS, "Saturn": swe.SATURN}
    out = {}
    for name, body in bodies.items():
        out[name] = _horo_lon(swe, jd, body)
    rahu_lon, _ = _horo_lon(swe, jd, swe.MEAN_NODE)
    out["Rahu"] = (rahu_lon, True)
    out["Ketu"] = ((rahu_lon + 180) % 360, True)
    return out


def horo_natal(dob, birth_time=None):
    """Janma Rashi & Janma Nakshatra from the real Moon position at birth (IST).
    `certain` is False when the Moon changed sign during the birth date and no
    real birth time is known — the sign could then be one of two."""
    swe = _horo_swe()
    if swe is None or not isinstance(dob, dt.date):
        return None
    hour = 12.0 if birth_time is None else birth_time.hour + birth_time.minute / 60
    jd = _horo_jd(swe, dob, hour)
    moon, _ = _horo_lon(swe, jd, swe.MOON)
    start, _ = _horo_lon(swe, _horo_jd(swe, dob, 0.0), swe.MOON)
    end, _ = _horo_lon(swe, _horo_jd(swe, dob, 23.99), swe.MOON)
    return {
        "moon_lon": moon, "rashi": int(moon // 30), "nakshatra": int(moon // (360 / 27)),
        "pada": int((moon % (360 / 27)) // (360 / 27 / 4)) + 1, "certain": int(start // 30) == int(end // 30),
    }


def _horo_tara(natal_nak, day_nak):
    n = (day_nak - natal_nak) % 27 + 1
    return ((n - 1) % 9) + 1


def horo_eval_day(natal, date):
    """One day's transit picture, measured at about sunrise (6 AM IST)."""
    swe = _horo_swe()
    pos = horo_positions(swe, _horo_jd(swe, date, 6.0))
    signs = {p: int(pos[p][0] // 30) for p in HORO_PLANETS}
    houses = {p: (signs[p] - natal["rashi"]) % 12 + 1 for p in HORO_PLANETS}
    good = {p: houses[p] in HORO_GOOD_HOUSES[p] for p in HORO_PLANETS}
    day_nak = int(pos["Moon"][0] // (360 / 27))
    tara = _horo_tara(natal["nakshatra"], day_nak)
    values = {p: (1.0 if good[p] else 0.0) for p in HORO_PLANETS}
    values["Tara"] = HORO_TARA_VALUE[tara]
    score = round(sum(HORO_SCORE_WEIGHTS[k] * values[k] for k in HORO_SCORE_WEIGHTS))
    cats = {c: sum(w * values[k] for k, w in ws.items()) / sum(ws.values()) for c, ws in HORO_CATEGORY_WEIGHTS.items()}
    tithi_idx = int(((pos["Moon"][0] - pos["Sun"][0]) % 360) // 12)
    return {
        "date": date.isoformat(), "signs": signs, "houses": houses, "good": good, "retro": {p: pos[p][1] for p in HORO_PLANETS},
        "moon_nak": day_nak, "tara": tara, "score": score, "cats": cats, "tithi": tithi_idx,
        "deg": {p: pos[p][0] % 30 for p in HORO_PLANETS},
    }


def horo_moon_ingress(date):
    """If the Moon changes sign during this IST date, returns (new_rashi_index, 'hh:mm AM/PM') else None."""
    swe = _horo_swe()
    a, b = _horo_jd(swe, date, 0.0), _horo_jd(swe, date, 24.0)
    la, _ = _horo_lon(swe, a, swe.MOON)
    lb, _ = _horo_lon(swe, b, swe.MOON)
    if int(la // 30) == int(lb // 30):
        return None
    lo, hi = a, b
    for _ in range(14):
        mid = (lo + hi) / 2
        lm, _ = _horo_lon(swe, mid, swe.MOON)
        if int(lm // 30) == int(la // 30):
            lo = mid
        else:
            hi = mid
    minutes = int(round((hi - a) * 24 * 60))
    when = (dt.datetime.combine(date, dt.time(0, 0)) + dt.timedelta(minutes=minutes)).strftime("%I:%M %p")
    return int(lb // 30), when


def horo_series(natal, start, n_days):
    """Day-by-day evaluations (plain dicts, safe to cache)."""
    return [horo_eval_day(natal, start + dt.timedelta(days=i)) for i in range(n_days)]


def horo_ingresses(days, natal, skip=("Moon",)):
    """Sign changes of the slower grahas inside a window: [(date, planet, new_house, favourable, retrograde)]."""
    events = []
    for prev, cur in zip(days, days[1:]):
        for p in HORO_PLANETS:
            if p in skip or prev["signs"][p] == cur["signs"][p]:
                continue
            events.append((cur["date"], p, cur["houses"][p], cur["good"][p], cur["retro"][p]))
    return events


def horo_sade_sati(natal, saturn_sign):
    house = (saturn_sign - natal["rashi"]) % 12 + 1
    return {12: "Sade Sati — first phase (Saturn in the 12th from your Moon)", 1: "Sade Sati — middle phase (Saturn over your Moon sign)",
            2: "Sade Sati — final phase (Saturn in the 2nd from your Moon)",
            8: "Ashtama Shani (Saturn in the 8th from your Moon) — a testing but growth-oriented phase",
            4: "Kantaka / Ardha-Ashtama Shani (Saturn in the 4th from your Moon)"}.get(house)


def horo_average(days):
    n = len(days)
    return {
        "score": round(sum(d["score"] for d in days) / n),
        "cats": {c: sum(d["cats"][c] for d in days) / n for c in HORO_CATEGORY_WEIGHTS},
    }


@st.cache_data(show_spinner=False, ttl=3600)
def _horo_series_cached(rashi, nakshatra, start_iso, n_days):
    return horo_series({"rashi": rashi, "nakshatra": nakshatra}, dt.date.fromisoformat(start_iso), n_days)


def _horo_house_line(planet, day, natal_note=""):
    house, good = day["houses"][planet], day["good"][planet]
    text = HORO_PLANET_TEXT[planet][1 if good else 2]
    retro = " (retrograde)" if day["retro"][planet] and planet not in ("Rahu", "Ketu") else ""
    return f"**{planet}{retro}** in your {cel_ordinal(house)} house — {text}"


# =====================================================================
# HOUR-BY-HOUR LUCK (for Today / Tomorrow)
# ---------------------------------------------------------------------
# Each clock hour (IST) gets a 0-100 score from real, classical factors:
#   * Chandrabala  - the Moon's ACTUAL position that hour, counted from your
#                    natal Moon sign (30%)
#   * Tarabala     - the Moon's nakshatra that hour vs your birth star (20%)
#   * Hora         - the planetary hour's lord, and whether that planet is
#                    favourable for you today (25%)
#   * The day's other transits (Sun, Mars, Mercury, Venus, Jupiter, Saturn)
#                  - the background of the day (25%)
#   * Rahu Kaal lowers the hours it covers; Abhijit Muhurta lifts them.
# Sunrise is taken as 6:00 AM and sunset as 6:00 PM IST (same convention as
# the daily reading), so Hora / Rahu Kaal / Abhijit can shift by up to about
# an hour in some cities.
# =====================================================================
HORO_CHALDEAN = ["Saturn", "Jupiter", "Mars", "Sun", "Venus", "Mercury", "Moon"]
HORO_RAHU_KAAL_PART = {0: 2, 1: 7, 2: 5, 3: 6, 4: 4, 5: 3, 6: 8}   # weekday() -> which 1/8th of the daytime
# Two more of the three classical "avoid new work" windows shown on every
# major Panchang site (Rahu Kaal is the most malefic of the three; these two
# are milder but real, and always shown alongside it). Same 1/8th-of-daytime
# convention, different weekday assignment — verified against DrikPanchang /
# BhaktiBharat / Dekho Panchang, which all agree on these tables:
HORO_YAMAGANDA_PART = {0: 4, 1: 3, 2: 2, 3: 1, 4: 7, 5: 6, 6: 5}
HORO_GULIKA_PART = {0: 6, 1: 5, 2: 4, 3: 3, 4: 2, 5: 1, 6: 7}
# Choghadiya (daytime only — see note below): the fixed 7-name cycle every
# Panchang follows, and which name opens the day for each weekday. Verified
# against live DrikPanchang/Dekho Panchang tables for two different weekdays
# before use. Night Choghadiya's *starting* name is inconsistent across
# sources (even reputable ones disagree), so — to avoid showing anything
# that isn't verifiably correct — Choghadiya is shown for daytime hours only.
CHOG_ORDER = ["Udveg", "Char", "Labh", "Amrit", "Kaal", "Shubh", "Rog"]
CHOG_DAY_START = {0: "Amrit", 1: "Rog", 2: "Labh", 3: "Shubh", 4: "Char", 5: "Kaal", 6: "Udveg"}
CHOG_NATURE = {"Amrit": 1, "Shubh": 1, "Labh": 1, "Char": 0, "Rog": -1, "Kaal": -1, "Udveg": -1}
# The two other universal checks every general Shubh Muhurat (buying a
# vehicle, Griha Pravesh, or any other important new start) applies on top
# of Choghadiya/Hora/Kaal — not specific to this feature, the same rules a
# Panchang site would use for ANY auspicious activity:
# Rikta Tithi (4th, 9th, 14th of either paksha) — traditionally avoided for
# starting new ventures.
HORO_RIKTA_TITHIS = {3, 8, 13}
# Gandmool Nakshatra (the 6 junction stars) — traditionally avoided for most
# important new beginnings.
HORO_GANDMOOL_NAKSHATRAS = {0, 8, 9, 17, 18, 26}   # Ashwini, Ashlesha, Magha, Jyeshtha, Mula, Revati
HORO_BAND_COLORS = {"Excellent": "#16A34A", "Good": "#65A30D", "Mixed": "#D97706", "Cautious": "#DC2626"}


def _horo_hour_label(h):
    h = h % 24
    return f"{h % 12 or 12} {'AM' if h < 12 else 'PM'}"


def _horo_clock(x):
    """Decimal hours (e.g. 7.5) -> '7:30 AM'."""
    total = int(round(x * 60)) % (24 * 60)
    hh, mm = divmod(total, 60)
    return f"{hh % 12 or 12}:{mm:02d} {'AM' if hh < 12 else 'PM'}"


def horo_hourly(natal, date):
    """24 hourly slots for one IST date: [{hour, label, score, band, moon_house, tara, hora, rahu, abhijit}]."""
    swe = _horo_swe()
    day = horo_eval_day(natal, date)
    others = ("Sun", "Mars", "Mercury", "Venus", "Jupiter", "Saturn")
    base = sum(HORO_SCORE_WEIGHTS[p] for p in others if day["good"][p]) / sum(HORO_SCORE_WEIGHTS[p] for p in others)
    wd = date.weekday()
    rk_p, ym_p, gl_p = HORO_RAHU_KAAL_PART[wd], HORO_YAMAGANDA_PART[wd], HORO_GULIKA_PART[wd]
    rk_start, rk_end = 6 + (rk_p - 1) * 1.5, 6 + rk_p * 1.5
    ym_start, ym_end = 6 + (ym_p - 1) * 1.5, 6 + ym_p * 1.5
    gl_start, gl_end = 6 + (gl_p - 1) * 1.5, 6 + gl_p * 1.5
    chog_start_idx = CHOG_ORDER.index(CHOG_DAY_START[wd])
    out = []
    for h in range(24):
        moon_lon, _ = _horo_lon(swe, _horo_jd(swe, date, h + 0.5), swe.MOON)
        moon_house = (int(moon_lon // 30) - natal["rashi"]) % 12 + 1
        moon_good = moon_house in HORO_GOOD_HOUSES["Moon"]
        tara = _horo_tara(natal["nakshatra"], int(moon_lon // (360 / 27)))
        if h >= 6:
            vedic_day, k = date, h - 6
        else:                                   # midnight-6 AM still belongs to the previous Vedic day
            vedic_day, k = date - dt.timedelta(days=1), h + 18
        day_lord = HORO_VARA[vedic_day.weekday()][1]
        hora = HORO_CHALDEAN[(HORO_CHALDEAN.index(day_lord) + k) % 7]
        hora_good = moon_good if hora == "Moon" else day["good"][hora]
        score = 30 * moon_good + 20 * HORO_TARA_VALUE[tara] + 25 * hora_good + 25 * base
        rk_overlap = max(0.0, min(h + 1, rk_end) - max(h, rk_start))
        score -= 20 * rk_overlap
        ym_overlap = max(0.0, min(h + 1, ym_end) - max(h, ym_start))
        score -= 12 * ym_overlap
        gl_overlap = max(0.0, min(h + 1, gl_end) - max(h, gl_start))
        score -= 10 * gl_overlap
        ab_overlap = max(0.0, min(h + 1, 12.4) - max(h, 11.6))
        score += 8 * min(1.0, ab_overlap / 0.4)
        chog_name = None
        if 6 <= h < 18:
            slot = min(7, int(((h + 0.5) - 6) // 1.5))
            chog_name = CHOG_ORDER[(chog_start_idx + slot) % 7]
            score += 10 * CHOG_NATURE[chog_name]
        score = max(0, min(100, round(score)))
        out.append({"hour": h, "label": _horo_hour_label(h), "score": score, "band": horo_band(score),
                    "moon_house": moon_house, "tara": tara, "hora": hora, "choghadiya": chog_name,
                    "rahu": rk_overlap > 0, "yamaganda": ym_overlap > 0, "gulika": gl_overlap > 0, "abhijit": ab_overlap > 0})
    return out


@st.cache_data(show_spinner=False, ttl=3600)
def _horo_hourly_cached(rashi, nakshatra, date_iso):
    return horo_hourly({"rashi": rashi, "nakshatra": nakshatra}, dt.date.fromisoformat(date_iso))


def horo_hour_windows(hours, test):
    """Contiguous runs of hours whose score passes `test` -> [(start_hour, end_hour_exclusive)]."""
    runs, start = [], None
    for slot in hours:
        if test(slot["score"]):
            if start is None:
                start = slot["hour"]
        elif start is not None:
            runs.append((start, slot["hour"]))
            start = None
    if start is not None:
        runs.append((start, 24))
    return runs


def _horo_windows_text(runs):
    return ", ".join(f"{_horo_hour_label(a)} – {_horo_hour_label(b)}" for a, b in runs)


def horo_score_chart(labels, scores, x_title="", height=280):
    """Bar chart in the correct (given) order, each bar coloured by its level:
    green = Excellent/Good, amber = Mixed, red = Cautious."""
    labels = list(labels)
    df = pd.DataFrame({"When": labels, "Score": list(scores), "Level": [horo_band(v) for v in scores]})
    try:
        import altair as alt
        chart = (
            alt.Chart(df).mark_bar().encode(
                x=alt.X("When:N", sort=labels, title=x_title, axis=alt.Axis(labelAngle=-45 if len(labels) > 12 else 0)),
                y=alt.Y("Score:Q", scale=alt.Scale(domain=[0, 100]), title="Luck score (0-100)"),
                color=alt.Color("Level:N", scale=alt.Scale(domain=list(HORO_BAND_COLORS.keys()), range=list(HORO_BAND_COLORS.values())),
                                legend=alt.Legend(title=None, orient="bottom")),
                tooltip=["When", "Score", "Level"],
            ).properties(height=height)
        )
        st.altair_chart(chart, use_container_width=True)
    except Exception:
        st.bar_chart(pd.DataFrame({"Score": list(scores)}, index=labels))


def _horo_render_hourly(natal, date, is_today, day):
    """Hour-by-hour graph + best / careful time windows. Returns share-text lines."""
    hours = _horo_hourly_cached(natal["rashi"], natal["nakshatra"], date.isoformat())
    st.markdown("#### ⏰ Hour-by-hour luck — when your time is good & when to be careful")
    horo_score_chart([h["label"] for h in hours], [h["score"] for h in hours], x_title="Time of day (IST)")

    good_runs = horo_hour_windows(hours, lambda v: v >= 55)
    care_runs = horo_hour_windows(hours, lambda v: v < 40)
    good_txt = _horo_windows_text(good_runs)
    care_txt = _horo_windows_text(care_runs)
    if good_runs:
        st.success(f"🟢 **Good time:** {good_txt}")
    else:
        st.info("No strongly favourable stretch today — keep to routine work.")
    if care_runs:
        st.warning(f"🔴 **Be careful / avoid new starts:** {care_txt}")
    else:
        st.info("No hour is especially difficult today.")

    wd = date.weekday()
    rk_p, ym_p, gl_p = HORO_RAHU_KAAL_PART[wd], HORO_YAMAGANDA_PART[wd], HORO_GULIKA_PART[wd]
    rk_a, rk_b = 6 + (rk_p - 1) * 1.5, 6 + rk_p * 1.5
    ym_a, ym_b = 6 + (ym_p - 1) * 1.5, 6 + ym_p * 1.5
    gl_a, gl_b = 6 + (gl_p - 1) * 1.5, 6 + gl_p * 1.5
    st.caption(f"🕉️ Rahu Kaal: {_horo_clock(rk_a)} – {_horo_clock(rk_b)}  •  Yamaganda: {_horo_clock(ym_a)} – {_horo_clock(ym_b)}  •  "
               f"Gulika Kaal: {_horo_clock(gl_a)} – {_horo_clock(gl_b)} (avoid starting new work in these)  •  "
               f"Abhijit Muhurta: {_horo_clock(11.6)} – {_horo_clock(12.4)} (generally auspicious for starting things)")

    meeting_share = _horo_render_meeting_window(hours, date, day)
    with st.expander("☀️ Day Choghadiya (8 daytime periods, 6 AM – 6 PM)"):
        chog_icon = {1: "✅", 0: "🟡", -1: "🔴"}
        rows = []
        # group consecutive hours with the same Choghadiya name into one row
        grouped = []
        for slot in hours[6:18]:
            if grouped and grouped[-1]["name"] == slot["choghadiya"]:
                grouped[-1]["end"] = slot["hour"] + 1
            else:
                grouped.append({"name": slot["choghadiya"], "start": slot["hour"], "end": slot["hour"] + 1})
        for g in grouped:
            nat = CHOG_NATURE[g["name"]]
            rows.append({"Choghadiya": f"{chog_icon[nat]} {g['name']}", "Time": f"{_horo_hour_label(g['start'])} – {_horo_hour_label(g['end'])}"})
        st.dataframe(pd.DataFrame(rows), hide_index=True, use_container_width=True)
        st.caption("✅ Amrit / Shubh / Labh = good for starting things  •  🟡 Char = neutral, fine for travel  •  🔴 Rog / Kaal / Udveg = avoid new starts")
    if is_today:
        cur = hours[min(23, max(0, now_ist().hour))]
        icon = {"Excellent": "🟢", "Good": "🟢", "Mixed": "🟡", "Cautious": "🔴"}[cur["band"]]
        st.markdown(f"**Right now ({cur['label']}):** {icon} {cur['band']} — {cur['score']}/100")
    with st.expander("How is each hour scored?"):
        st.markdown(
            "- **Moon (Chandrabala)** — the Moon's real position that hour, counted from your birth Moon sign\n"
            "- **Tarabala** — the Moon's star that hour against your birth star\n"
            "- **Hora** — the ruling planet of that hour, and whether it is favourable for you today\n"
            "- **The day's other transits** — the background of the day\n"
            "- **Choghadiya** (daytime only) — the classical 8-period daily cycle used across Panchang systems\n"
            "- **Rahu Kaal, Yamaganda and Gulika Kaal** lower the hours they cover; **Abhijit Muhurta** lifts them\n\n"
            "Times are IST and assume sunrise 6:00 AM / sunset 6:00 PM, so Hora and Rahu Kaal can shift by up to about an hour in some cities. "
            "Traditional guidance to reflect on — not a certainty.")
    lines = list(meeting_share)
    if good_runs:
        lines.append(f"Good time: {good_txt}")
    if care_runs:
        lines.append(f"Be careful: {care_txt}")
    return lines


def horo_meeting_windows(hours):
    """Hours that meet ALL the classical conditions for starting an important
    new meeting: auspicious or neutral Choghadiya, no overlap with Rahu Kaal /
    Yamaganda / Gulika Kaal, and a personally supportive hour (score >= 55).
    Used for 'best time to go meet a prospective match' — real rules, no
    separate made-up formula."""
    runs, start = [], None
    for h in hours:
        ok = (h["choghadiya"] is not None and CHOG_NATURE[h["choghadiya"]] >= 0 and h["score"] >= 55
              and not h["rahu"] and not h["yamaganda"] and not h["gulika"])
        if ok:
            if start is None:
                start = h["hour"]
        elif start is not None:
            runs.append((start, h["hour"]))
            start = None
    if start is not None:
        runs.append((start, 24))
    return runs


def _horo_render_meeting_window(hours, date, day):
    """'Best time to go meet someone' box — combines Choghadiya, Rahu Kaal /
    Yamaganda / Gulika Kaal and the person's own hourly score, the same real
    classical factors already computed above (not a separate invented rule)."""
    st.markdown("#### \U0001F440 Best time today to go meet a prospective match (rishta / kanya darshan)")
    local_tithi = day["tithi"] % 15
    day_caution = []
    if local_tithi in HORO_RIKTA_TITHIS:
        day_caution.append("today's Tithi is a **Rikta Tithi**, which general Shubh Muhurat rules (the same ones used for buying "
                            "a vehicle or Griha Pravesh) also treat as unfavourable for starting something important")
    if day["moon_nak"] in HORO_GANDMOOL_NAKSHATRAS:
        day_caution.append(f"today's Nakshatra, **{NAKSHATRAS[day['moon_nak']]}**, is a **Gandmool Nakshatra** \u2014 "
                            "also generally avoided for important new beginnings")
    if day_caution:
        st.warning("\u26A0\uFE0F " + "; and ".join(day_caution).capitalize() + ". If the visit can be postponed, "
                   "a different day may be a cleaner choice by these same rules.")
    runs = horo_meeting_windows(hours)
    if runs:
        st.success(f"**{_horo_windows_text(runs)}** \u2014 auspicious Choghadiya, clear of Rahu Kaal / Yamaganda / Gulika Kaal, "
                   "and a personally supportive hour for you today.")
        meet_share = [f"Best time to visit for a rishta: {_horo_windows_text(runs)}"]
    else:
        ab_ok = not any(h["hour"] in (11, 12) and (h["rahu"] or h["yamaganda"] or h["gulika"]) for h in hours)
        if ab_ok:
            st.info(f"No hour today clears every condition at once, so the safest classical choice is **Abhijit Muhurta "
                    f"({_horo_clock(11.6)} \u2013 {_horo_clock(12.4)})** \u2014 traditionally auspicious for starting anything important, "
                    "and it doesn't fall in Rahu Kaal, Yamaganda or Gulika Kaal today.")
            meet_share = [f"Best time to visit for a rishta: Abhijit Muhurta {_horo_clock(11.6)} - {_horo_clock(12.4)}"]
        else:
            st.warning("Today doesn't offer a clean window by these rules (even Abhijit Muhurta overlaps an inauspicious "
                       "kaal today) \u2014 if the visit can wait, tomorrow may give you a clearer choice.")
            meet_share = ["No fully clear window today for visiting a prospective match by these rules."]
    st.caption("Based on real classical muhurat rules for starting any important meeting \u2014 Choghadiya, Rahu Kaal / "
               "Yamaganda / Gulika Kaal and Abhijit Muhurta \u2014 combined with your own chart's hourly strength above. "
               "Traditional guidance to consider, not a guarantee.")
    return meet_share


def _horo_build_day_view(day, natal, date, name):
    """Everything shown for a single day: returns (share_lines, band)."""
    band = horo_band(day["score"])
    vara_name, vara_lord, vara_color = HORO_VARA[date.weekday()]
    tithi_idx = day["tithi"]
    paksha = "Shukla" if tithi_idx < 15 else "Krishna"
    tithi_name = "Purnima" if tithi_idx == 14 else "Amavasya" if tithi_idx == 29 else HORO_TITHIS[tithi_idx % 15]
    moon_sign = day["signs"]["Moon"]
    ingress = horo_moon_ingress(date)

    band_color = {"Excellent": "#16A34A", "Good": "#65A30D", "Mixed": "#D97706", "Cautious": "#DC2626"}[band]
    st.markdown(f"""
    <div class="horo-card" style="border-top-color:{band_color}; text-align:left;">
        <div style="font-size:0.85rem; color:gray;">{date.strftime('%A, %d %B %Y')}</div>
        <div style="font-size:1.6rem; font-weight:900; color:{band_color};">{band} day &nbsp;•&nbsp; {day['score']}/100</div>
    </div>
    """, unsafe_allow_html=True)
    st.progress(day["score"] / 100)

    cols = st.columns(4)
    for col, (cat, ratio) in zip(cols, day["cats"].items()):
        col.markdown(f"<div class='horo-card'><b>{cat}</b><br><span style='font-size:1.3rem; color:#D4AF37;'>{horo_stars(ratio)}</span></div>", unsafe_allow_html=True)

    tara_name = HORO_TARA_NAMES[day["tara"] - 1]
    moon_line = f"Moon in {RASHIS[moon_sign]}"
    if ingress:
        moon_line += f" (moves into {RASHIS[ingress[0]]} at {ingress[1]} IST)"
    st.markdown(f"""
    <div style="background:#F3E8FF; border-left:4px solid #8E2DE2; border-radius:8px; padding:12px 16px; margin:14px 0;">
        <b style="color:#4A00E0;">🪔 Panchang — {date.strftime('%d %b %Y')}</b><br>
        <span style="color:#444;">Vara: <b>{vara_name}</b> (ruled by {vara_lord}) &nbsp;|&nbsp; Tithi: <b>{paksha} {tithi_name}</b> &nbsp;|&nbsp; Nakshatra: <b>{NAKSHATRAS[day['moon_nak']]}</b><br>
        {moon_line} &nbsp;|&nbsp; Tarabala: <b>{tara_name}</b> — {HORO_TARA_MEANING[day['tara']]}<br>
        Lucky colour of the day: <b>{vara_color}</b></span>
    </div>
    """, unsafe_allow_html=True)

    hourly_share = _horo_render_hourly(natal, date, is_today=(date == now_ist().date()), day=day)

    highlights, cautions = [], []
    tara_line = f"**Tarabala — {tara_name}:** {HORO_TARA_MEANING[day['tara']]}."
    (highlights if HORO_TARA_VALUE[day["tara"]] == 1 else cautions if HORO_TARA_VALUE[day["tara"]] == 0 else []).append(tara_line)
    for p in ["Moon", "Sun", "Mars", "Mercury", "Venus", "Jupiter", "Saturn"]:
        (highlights if day["good"][p] else cautions).append(_horo_house_line(p, day))

    hc1, hc2 = st.columns(2)
    with hc1:
        st.markdown("#### ✅ Working in your favour")
        for line in highlights or ["Nothing stands out as especially strong today."]:
            st.markdown(f"- {line}")
    with hc2:
        st.markdown("#### ⚠️ Handle with care")
        for line in cautions or ["No major cautions today."]:
            st.markdown(f"- {line}")
    do_txt, avoid_txt = HORO_ADVICE[band]
    st.success(f"**Best use of the day:** {do_txt}")
    st.warning(f"**Avoid:** {avoid_txt}")

    share = [f"{band} day ({day['score']}/100) — {date.strftime('%A, %d %b %Y')}"]
    share += [f"{c}: {horo_stars(r)}" for c, r in day["cats"].items()]
    share += hourly_share
    share += [f"Tarabala: {tara_name} — {HORO_TARA_MEANING[day['tara']]}", f"Best use: {do_txt}", f"Avoid: {avoid_txt}", f"Lucky colour: {vara_color}"]
    return share, band


def _horo_build_range_view(days, natal, label, is_year):
    avg = horo_average(days)
    band = horo_band(avg["score"])
    band_color = {"Excellent": "#16A34A", "Good": "#65A30D", "Mixed": "#D97706", "Cautious": "#DC2626"}[band]
    first = dt.date.fromisoformat(days[0]["date"])
    last = dt.date.fromisoformat(days[-1]["date"])
    st.markdown(f"""
    <div class="horo-card" style="border-top-color:{band_color}; text-align:left;">
        <div style="font-size:0.85rem; color:gray;">{label} &nbsp;•&nbsp; {first.strftime('%d %b %Y')} → {last.strftime('%d %b %Y')}</div>
        <div style="font-size:1.6rem; font-weight:900; color:{band_color};">{band} period &nbsp;•&nbsp; {avg['score']}/100</div>
    </div>
    """, unsafe_allow_html=True)
    st.progress(avg["score"] / 100)
    cols = st.columns(4)
    for col, (cat, ratio) in zip(cols, avg["cats"].items()):
        col.markdown(f"<div class='horo-card'><b>{cat}</b><br><span style='font-size:1.3rem; color:#D4AF37;'>{horo_stars(ratio)}</span></div>", unsafe_allow_html=True)

    share = [f"{label}: {band} ({avg['score']}/100) — {first.strftime('%d %b')} to {last.strftime('%d %b %Y')}"]
    share += [f"{c}: {horo_stars(r)}" for c, r in avg["cats"].items()]

    # ---- score chart ----
    if is_year:
        months = {}
        for d in days:
            key = dt.date.fromisoformat(d["date"]).strftime("%b %Y")
            months.setdefault(key, []).append(d["score"])
        month_avg = {k: round(sum(v) / len(v)) for k, v in months.items()}
        st.markdown("#### 📊 Month-by-month outlook")
        horo_score_chart(list(month_avg.keys()), list(month_avg.values()), x_title="Month")
        ranked = sorted(month_avg.items(), key=lambda kv: -kv[1])
        best_m = ", ".join(f"{k} ({v})" for k, v in ranked[:3])
        tough_m = ", ".join(f"{k} ({v})" for k, v in ranked[-3:][::-1])
        st.success(f"**Strongest months:** {best_m}")
        st.warning(f"**Months needing extra care:** {tough_m}")
        share += [f"Strongest months: {best_m}", f"Months needing care: {tough_m}"]
    else:
        st.markdown("#### 📊 Day-by-day outlook")
        horo_score_chart([dt.date.fromisoformat(d["date"]).strftime("%d %b") for d in days], [d["score"] for d in days], x_title="Day")
        ranked = sorted(days, key=lambda d: (-d["score"], d["date"]))
        k = 2 if len(days) <= 7 else 4
        fmt = lambda d: f"{dt.date.fromisoformat(d['date']).strftime('%a %d %b')} ({d['score']})"
        best_d = ", ".join(fmt(d) for d in ranked[:k])
        tough_d = ", ".join(fmt(d) for d in ranked[-k:][::-1])
        st.success(f"**Best days:** {best_d}")
        st.warning(f"**Take extra care on:** {tough_d}")
        share += [f"Best days: {best_d}", f"Take care on: {tough_d}"]

    # ---- slower planets: the real story of the period ----
    snap = days[0]
    lines_good, lines_bad = [], []
    for p in (["Jupiter", "Saturn", "Rahu", "Ketu", "Sun", "Mars", "Mercury", "Venus"] if is_year else ["Sun", "Mars", "Mercury", "Venus", "Jupiter", "Saturn"]):
        (lines_good if snap["good"][p] else lines_bad).append(_horo_house_line(p, snap))
    g1, g2 = st.columns(2)
    with g1:
        st.markdown("#### ✅ Supportive influences")
        for line in lines_good or ["No strongly supportive planetary transit at the start of this period."]:
            st.markdown(f"- {line}")
    with g2:
        st.markdown("#### ⚠️ Areas needing patience")
        for line in lines_bad or ["No challenging planetary transit at the start of this period."]:
            st.markdown(f"- {line}")
    share += [re.sub(r"\*\*", "", l) for l in lines_good[:2]] + [re.sub(r"\*\*", "", l) for l in lines_bad[:2]]

    # ---- ingresses (real sign changes inside the window) ----
    events = horo_ingresses(days, natal, skip=("Moon", "Sun", "Mercury", "Venus") if is_year else ("Moon",))
    if events:
        st.markdown("#### 🔄 Major planetary sign changes in this period" if is_year else "#### 🔄 Planetary sign changes in this period")
        for d_iso, planet, house, good, retro in events:
            d = dt.date.fromisoformat(d_iso)
            mood = "✅ favourable for you" if good else "⚠️ needs care"
            st.markdown(f"- **{d.strftime('%d %b %Y')}** — {planet} enters your {cel_ordinal(house)} house ({mood})")

    if is_year:
        s_start = horo_sade_sati(natal, snap["signs"]["Saturn"])
        s_end = horo_sade_sati(natal, days[-1]["signs"]["Saturn"])
        st.markdown("#### 🪐 Saturn (Shani) status")
        if s_start or s_end:
            st.info(f"**Now:** {s_start or 'Not in Sade Sati / Dhaiya'}  \n**By the end of this year:** {s_end or 'Not in Sade Sati / Dhaiya'}  \n"
                    "Sade Sati is a long phase of testing and maturing rather than a curse — steady work, patience and health care carry most people through it well.")
            share.append(f"Saturn: {s_start or 'clear of Sade Sati'}")
        else:
            st.info("You are not in Sade Sati or Dhaiya at any point in this period.")

    return share, band


def page_daily_horoscope():
    render_global_css(bg_color="#FFFDF8", page_css=""".horo-header { background: linear-gradient(135deg, #4A00E0 0%, #8E2DE2 100%); padding: 30px; border-radius: 18px; color: white; text-align: center; margin-bottom: 25px; }
.horo-card { background: white; padding: 18px 20px; border-radius: 14px; box-shadow: 0 6px 15px rgba(0,0,0,0.06); border-top: 4px solid #8E2DE2; text-align: center; margin-bottom: 10px; }
.sync-box { background: linear-gradient(135deg, #ECFDF5, #F3E8FF); border: 1px solid #C4B5FD; border-left: 5px solid #8E2DE2; border-radius: 12px; padding: 14px 18px; margin-bottom: 14px; }""")

    st.markdown("""
    <div class="horo-header">
        <h1 style="margin:0; font-family:'Georgia', serif;">🔮 Your Horoscope</h1>
        <p style="color:#EDE7F6; margin-top:8px;">Real planetary positions, calculated from your own birth details — for today, tomorrow, this week, this month or this year.</p>
    </div>
    """, unsafe_allow_html=True)

    if not horo_engine_available():
        st.error("❌ Real horoscope calculation isn't available on this server yet — the `pyswisseph` package needs to be added to `requirements.txt` (the same one Kundli Match uses). No made-up horoscope will be shown instead.")
        return

    # ------------------------------------------------------------------
    # AUTO-SYNC from the person's Siddhivinayak Matrimony profile (name, date/time/place of birth)
    # ------------------------------------------------------------------
    email = st.session_state.get("user_email")
    profile = db_get_profile(email) if (email and db_is_connected()) else None
    profile = profile or {}
    name = profile.get("name") or st.session_state.get("user_name") or "You"
    dob = profile.get("dob") if isinstance(profile.get("dob"), dt.date) else st.session_state.get("user_dob")
    birth_time, birth_time_known = None, False
    if profile.get("birth_time"):
        try:
            birth_time = dt.time.fromisoformat(profile["birth_time"])
            birth_time_known = True
        except Exception:
            birth_time = None
    birth_place = profile.get("birth_place", "")
    synced = isinstance(dob, dt.date)

    use_custom = False
    with st.expander("🔁 Use different birth details (for a family member or a match)" if synced else "✍️ Enter your birth details", expanded=not synced):
        if synced:
            use_custom = st.checkbox("Show the horoscope for these details instead of my profile", key="horo_use_custom")
        if use_custom or not synced:
            c_name = st.text_input("Name", value="" if synced else name, key="horo_c_name")
            cc1, cc2 = st.columns(2)
            c_dob = cc1.date_input("Date of Birth", value=min(max(dob, dt.date(1940, 1, 1)), now_ist().date()) if synced else dt.date(1995, 1, 1), min_value=dt.date(1940, 1, 1), max_value=now_ist().date(), key="horo_c_dob")
            c_time = cc2.time_input("Time of Birth (if known)", value=birth_time or dt.time(12, 0), key="horo_c_time")
            name, dob, birth_time, birth_time_known, birth_place = (c_name.strip() or "Guest"), c_dob, c_time, True, ""
            synced = use_custom  # profile card wording below

    if not isinstance(dob, dt.date):
        st.info("Please enter a date of birth to see your horoscope.")
        return

    natal = horo_natal(dob, birth_time if birth_time_known else None)
    if natal is None:
        st.error("❌ Couldn't calculate planetary positions right now. Please try again.")
        return

    sync_label = "✅ Synced from your Siddhivinayak Matrimony profile" if (synced and not use_custom) else "📝 Using the birth details you entered"
    time_txt = birth_time.strftime("%I:%M %p") if birth_time_known and birth_time else "not set (noon assumed)"
    place_txt = f" &nbsp;|&nbsp; Birth place: <b>{birth_place}</b>" if birth_place else ""
    st.markdown(f"""
    <div class="sync-box">
        <span style="color:#166534; font-weight:700;">{sync_label}</span><br>
        <b style="color:#4A00E0; font-size:1.15rem;">{name}</b><br>
        Born: <b>{dob.strftime('%d %b %Y')}</b> &nbsp;|&nbsp; Time: <b>{time_txt}</b>{place_txt}<br>
        Janma Rashi (Moon sign): <b style="color:#8E2DE2;">{RASHIS[natal['rashi']]}</b> &nbsp;|&nbsp; Janma Nakshatra: <b style="color:#8E2DE2;">{NAKSHATRAS[natal['nakshatra']]} (Pada {natal['pada']})</b>
    </div>
    """, unsafe_allow_html=True)
    if not natal["certain"] and not birth_time_known:
        st.warning("⚠️ The Moon changed sign on your birth date, so your Rashi depends on your exact birth time. We've assumed 12:00 noon — please add your real birth time in **Edit My Profile** for a precise horoscope.")

    # ------------------------------------------------------------------
    # PERIOD CHOOSER
    # ------------------------------------------------------------------
    today = now_ist().date()
    PERIODS = {
        "Today": ("Today", 0, 1), "Tomorrow": ("Tomorrow", 1, 1), "This Week (7 days)": ("This Week", 0, 7),
        "This Month (30 days)": ("This Month", 0, 30), "This Year (12 months)": ("This Year", 0, 366),
    }
    choice = st.radio("Show me my horoscope for", list(PERIODS.keys()), horizontal=True, key="horo_period")
    label, offset, n_days = PERIODS[choice]
    start = today + dt.timedelta(days=offset)
    days = _horo_series_cached(natal["rashi"], natal["nakshatra"], start.isoformat(), n_days)

    if n_days == 1:
        share_lines, band = _horo_build_day_view(days[0], natal, start, name)
    else:
        share_lines, band = _horo_build_range_view(days, natal, label, is_year=(n_days > 31))

    # ------------------------------------------------------------------
    # LIVE PLANET TRACKER — the real sky on the first day of the period
    # ------------------------------------------------------------------
    snap = days[0]
    with st.expander(f"🔭 Live planet tracker — real positions on {start.strftime('%d %b %Y')} (Lahiri sidereal)"):
        rows = []
        for p in HORO_PLANETS:
            house = snap["houses"][p]
            retro = " ℞" if snap["retro"][p] and p not in ("Rahu", "Ketu") else ""
            rows.append({"Planet": p + retro, "Rashi": RASHIS[snap["signs"][p]], "Degree": f"{snap['deg'][p]:.1f}°",
                         "House from your Moon": house, "For you": "✅ Favourable" if snap["good"][p] else "⚠️ Needs care"})
        st.dataframe(pd.DataFrame(rows), hide_index=True, use_container_width=True)
        st.caption("Positions come from the Swiss Ephemeris (the same engine professional Vedic software uses). ℞ = retrograde.")

    # ------------------------------------------------------------------
    # SHARE
    # ------------------------------------------------------------------
    share_text = f"🔮 {name}'s horoscope ({RASHIS[natal['rashi']]}) — {label}\n" + "\n".join(share_lines) + "\n\n— Siddhivinayak Matrimony"
