            def travel_vendor_phone(name):
                digest = hashlib.md5(name.encode()).hexdigest()
                part1 = str(int(digest[:5], 16))[-5:].zfill(5)
                part2 = str(int(digest[5:10], 16))[-5:].zfill(5)
                return f"+91 98{part1} {part2}"

