# =====================================================================
# ANNIVERSARY & BIRTHDAY REMINDERS — persistence helpers
# =====================================================================
# ---- BEGIN CELEBRATION CORE (pure logic — no Streamlit; shared verbatim with send_celebration_emails.py) ----
_CEL_IST = dt.timezone(dt.timedelta(hours=5, minutes=30))
_CEL_SUPPORT_EMAIL = "support@firstchoiceinnovations.com"


def cel_today_ist():
    return dt.datetime.now(_CEL_IST).date()


def cel_parse_date(value):
    """Accepts a date, a datetime, or an ISO string; returns a date or None."""
    if isinstance(value, dt.datetime):
        return value.date()
    if isinstance(value, dt.date):
        return value
    if isinstance(value, str) and value.strip():
        try:
            return dt.date.fromisoformat(value.strip()[:10])
        except ValueError:
            return None
    return None


def cel_same_day_in_year(d, year):
    """Same month/day in another year. A 29 Feb date falls on 28 Feb in
    non-leap years (so leap-day birthdays/anniversaries are never missed)."""
    try:
        return d.replace(year=year)
    except ValueError:
        return d.replace(year=year, day=28)


def cel_next_occurrence(d, today):
    this_year = cel_same_day_in_year(d, today.year)
    if this_year < today:
        this_year = cel_same_day_in_year(d, today.year + 1)
    return this_year


def cel_ordinal(n):
    if 10 <= n % 100 <= 20:
        suffix = "th"
    else:
        suffix = {1: "st", 2: "nd", 3: "rd"}.get(n % 10, "th")
    return f"{n}{suffix}"


def cel_valid_email(addr):
    a = (addr or "").strip().lower()
    if "@" not in a or "." not in a.split("@")[-1] or " " in a:
        return False
    # demo/sample addresses must never receive real mail
    return not a.endswith("@example.com")


def cel_build_email(kind, person_name, pair_label, years=None):
    """Returns (subject, body) for a birthday or anniversary greeting."""
    footer = (
        "\n\n— Team Siddhivinayak Matrimony\n\n"
        "You're receiving this because these details were saved under Anniversary & Birthday Reminders "
        f"on Siddhivinayak Matrimony. To stop these emails, write to {_CEL_SUPPORT_EMAIL} or ask the account holder to "
        "switch off automatic emails for this couple."
    )
    if kind == "birthday":
        subject = f"🎂 Happy Birthday, {person_name}! — Siddhivinayak Matrimony"
        body = (
            f"Dear {person_name},\n\n"
            "🎂 Wishing you a very Happy Birthday from all of us at Siddhivinayak Matrimony!\n"
            "May the year ahead bring you good health, happiness, and endless togetherness."
            + footer
        )
    else:
        n_txt = cel_ordinal(years) if years else ""
        subject = f"🎊 Happy {n_txt} Wedding Anniversary, {pair_label}! — Siddhivinayak Matrimony".replace("  ", " ")
        body = (
            f"Dear {person_name},\n\n"
            f"🎊 Congratulations to {pair_label} on your {n_txt} Wedding Anniversary!\n".replace("  ", " ")
            + "May your bond grow stronger, warmer, and happier with every passing year. 💕"
            + footer
        )
    return subject, body


def cel_due_today(couple, today):
    """Celebrations (birthdays / anniversary) that fall on `today` for one
    saved couple. Works with real dates or ISO strings straight from MongoDB.
    An anniversary is only counted from the year AFTER the wedding — the
    wedding day itself is not an anniversary."""
    out = []
    s1 = (couple.get("spouse1_name") or "").strip()
    s2 = (couple.get("spouse2_name") or "").strip()
    pair = f"{s1} & {s2}"
    for idx, name in ((1, s1), (2, s2)):
        dob = cel_parse_date(couple.get(f"spouse{idx}_dob"))
        if dob and name and dob.year < today.year and cel_same_day_in_year(dob, today.year) == today:
            out.append({
                "kind": "birthday", "suffix": dob.isoformat(), "years": today.year - dob.year,
                "recipients": [(name, couple.get(f"spouse{idx}_email") or "")], "pair": pair,
            })
    md = cel_parse_date(couple.get("marriage_date"))
    if md and md.year < today.year and cel_same_day_in_year(md, today.year) == today:
        out.append({
            "kind": "anniversary", "suffix": md.isoformat(), "years": today.year - md.year,
            "recipients": [(s1, couple.get("spouse1_email") or ""), (s2, couple.get("spouse2_email") or "")],
            "pair": pair,
        })
    return out


def cel_run_job(db, send_fn, today=None):
    """Sends every birthday / anniversary email due today, for every saved
    couple. Safe to call as often as you like: each (recipient, kind, year,
    date) is claimed in `celebration_email_log` BEFORE sending, so nobody is
    ever emailed twice — even if two servers run this at the same moment, or
    the same couple is saved under both partners' accounts. A failed send
    releases its claim so the next run retries it."""
    from pymongo.errors import DuplicateKeyError
    today = today or cel_today_ist()
    stats = {"sent": 0, "failed": 0, "skipped_no_email": 0}
    attempted = set()  # one try per recipient per run, even if the couple is saved under both partners' accounts
    for doc in db.anniversary_couples.find({}):
        for c in doc.get("couples") or []:
            if c.get("removed") or c.get("auto_email") is False:
                continue
            for ev in cel_due_today(c, today):
                for name, addr in ev["recipients"]:
                    if not cel_valid_email(addr):
                        stats["skipped_no_email"] += 1
                        continue
                    addr = addr.strip()
                    log_id = f"{addr.lower()}|{ev['kind']}|{today.year}|{ev['suffix']}"
                    if log_id in attempted:
                        continue
                    attempted.add(log_id)
                    try:
                        db.celebration_email_log.insert_one({"_id": log_id, "sent_at": dt.datetime.utcnow(), "owner": doc.get("email")})
                    except DuplicateKeyError:
                        continue
                    subject, body = cel_build_email(ev["kind"], name, ev["pair"], ev["years"])
                    ok, info = send_fn(addr, subject, body)
                    if ok:
                        stats["sent"] += 1
                    elif info == "skipped_by_preference":
                        # they've turned "Wedding & Anniversary Reminders" or
                        # Email off \u2014 keep the claim so we don't re-attempt
                        # this same event every hour for the rest of the day.
                        stats["skipped_by_preference"] = stats.get("skipped_by_preference", 0) + 1
                    else:
                        stats["failed"] += 1
                        db.celebration_email_log.delete_one({"_id": log_id})
    return stats
# ---- END CELEBRATION CORE ----


def _couples_to_serializable(couples):
    out = []
    for c in couples:
        cc = dict(c)
        for k in ("spouse1_dob", "spouse2_dob", "marriage_date", "engagement_date"):
            if isinstance(cc.get(k), dt.date):
                cc[k] = cc[k].isoformat()
        out.append(cc)
    return out


@_invalidate_cache_after("anniversary_couples")
def db_save_couples(email, couples):
    db = get_db()
    if db is None:
        return False
    db.anniversary_couples.update_one({"email": email}, {"$set": {"couples": _couples_to_serializable(couples)}}, upsert=True)
    return True


@cached_read("anniversary_couples")
def db_load_couples(email):
    db = get_db()
    if db is None:
        return None
    doc = db.anniversary_couples.find_one({"email": email})
    if not doc:
        return None
    couples = doc.get("couples", [])
    for c in couples:
        for k in ("spouse1_dob", "spouse2_dob", "marriage_date", "engagement_date"):
            c[k] = cel_parse_date(c.get(k))
    return couples


def _ensure_couple_ids(email, couples):
    """Older saved couples have no id. Give each a stable one (and persist
    it) so edit/remove buttons keep working after reruns."""
    missing = [c for c in couples if not c.get("id")]
    for c in missing:
        c["id"] = uuid.uuid4().hex[:8]
    if missing:
        db_save_couples(email, couples)
    return couples


# =====================================================================
# AUTO-CONNECTED COUPLE DATA
# Wherever the app learns that two people are getting married — a
# confirmed match + wedding date in Wedding Countdown, a Wedding /
# Engagement invitation card, or a Success Story — the couple lands here
# automatically (no re-typing), the same way the wedding reminder works.
# =====================================================================
def _norm_name(s):
    return " ".join((s or "").lower().split())


def _names_match(a, b):
    """'Rahul' matches 'Rahul Sharma' (invitation cards usually carry first
    names only, profiles carry full names)."""
    ta, tb = set(_norm_name(a).split()), set(_norm_name(b).split())
    return bool(ta and tb and (ta <= tb or tb <= ta))


def _longer_name(a, b):
    a, b = (a or "").strip(), (b or "").strip()
    return a if len(a) >= len(b) else b


def _swap_couple_sides(c):
    out = dict(c)
    for k in ("name", "dob", "email"):
        out[f"spouse1_{k}"], out[f"spouse2_{k}"] = c.get(f"spouse2_{k}"), c.get(f"spouse1_{k}")
    return out


def _find_matching_couple(couples, inc):
    """Returns (couple, swapped) — swapped=True if the saved couple lists the
    same two people in the opposite order to `inc`."""
    for c in couples:
        if _names_match(c.get("spouse1_name"), inc.get("spouse1_name")) and _names_match(c.get("spouse2_name"), inc.get("spouse2_name")):
            return c, False
        if _names_match(c.get("spouse1_name"), inc.get("spouse2_name")) and _names_match(c.get("spouse2_name"), inc.get("spouse1_name")):
            return c, True
    return None, False


def db_upsert_auto_couple(owner_email, incoming, source):
    """Adds or refreshes a couple in `owner_email`'s Anniversary & Birthday
    list. Only non-empty incoming values overwrite, so nothing the user
    filled in by hand is ever blanked out. Returns True only if something
    actually changed (so callers can stay quiet otherwise)."""
    db = get_db()
    if db is None or not owner_email:
        return False
    if not ((incoming.get("spouse1_name") or "").strip() and (incoming.get("spouse2_name") or "").strip()):
        return False
    couples = db_load_couples(owner_email) or []
    before = json.dumps(_couples_to_serializable(couples), sort_keys=True, default=str)

    match, swapped = _find_matching_couple(couples, incoming)
    inc = _swap_couple_sides(incoming) if swapped else dict(incoming)
    if match is None:
        match = {
            "id": uuid.uuid4().hex[:8], "spouse1_name": "", "spouse1_dob": None, "spouse1_email": "",
            "spouse2_name": "", "spouse2_dob": None, "spouse2_email": "",
            "marriage_date": None, "engagement_date": None, "auto_email": True, "sources": [],
        }
        couples.append(match)
    elif match.get("removed"):
        if source == "wedding_plan":
            return False  # the person removed this couple; background syncing must not resurrect it
        match["removed"] = False

    for k in ("spouse1_name", "spouse2_name"):
        if inc.get(k):
            match[k] = _longer_name(match.get(k), inc[k])
    for k in ("spouse1_dob", "spouse1_email", "spouse2_dob", "spouse2_email", "marriage_date", "engagement_date"):
        if inc.get(k):
            match[k] = inc[k]
    if source not in (match.get("sources") or []):
        match["sources"] = (match.get("sources") or []) + [source]
    if not match.get("id"):
        match["id"] = uuid.uuid4().hex[:8]

    after = json.dumps(_couples_to_serializable(couples), sort_keys=True, default=str)
    if after == before:
        return False
    return db_save_couples(owner_email, couples)


def _person_from_profile(email, hint_name=""):
    prof = db_get_profile(email) or {}
    dob = prof.get("dob") if isinstance(prof.get("dob"), dt.date) else None
    return {
        "name": (prof.get("name") or hint_name or (email or "").split("@")[0]).strip(),
        "dob": dob, "email": email, "gender": prof.get("gender"),
    }


def sync_couples_from_wedding_plans(email):
    """Pulls every wedding plan this person is part of (as owner OR as the
    confirmed partner) into BOTH partners' Anniversary & Birthday lists —
    names, dates of birth and e-mails come from their real profiles, the
    wedding date from the Wedding Countdown. Returns True if anything changed."""
    db = get_db()
    if db is None or not email:
        return False
    changed = False
    try:
        plans = []
        own = db.wedding_plans.find_one({"email": email})
        if own:
            plans.append(own)
        plans += list(db.wedding_plans.find({"partner_email": email}))
        for plan in plans:
            a, b = plan.get("email"), plan.get("partner_email")
            date_is_set = bool(plan.get("wedding_date_set", plan.get("generated", False)))
            wdate = cel_parse_date(plan.get("wedding_date"))
            if not (a and b and date_is_set and wdate):
                continue
            pa = _person_from_profile(a)
            pb = _person_from_profile(b, plan.get("partner_name", ""))
            if pb.get("gender") == "Male" and pa.get("gender") != "Male":
                pa, pb = pb, pa  # groom listed as Spouse 1
            couple = {
                "spouse1_name": pa["name"], "spouse1_dob": pa["dob"], "spouse1_email": pa["email"],
                "spouse2_name": pb["name"], "spouse2_dob": pb["dob"], "spouse2_email": pb["email"],
                "marriage_date": wdate,
            }
            for owner in (a, b):
                changed = db_upsert_auto_couple(owner, couple, "wedding_plan") or changed
    except Exception:
        pass
    return changed


def sync_event_to_anniversary(owner_email, groom, bride, event_type, event_date, source):
    """Invitation cards and Success Stories: a Wedding (or already-married)
    date sets the anniversary; an Engagement date is tracked as an upcoming
    event. If the logged-in person is one of the two, their own profile's
    date of birth / e-mail are attached automatically."""
    if not owner_email or not (groom or "").strip() or not (bride or "").strip() or not isinstance(event_date, dt.date):
        return False
    inc = {"spouse1_name": groom.strip(), "spouse2_name": bride.strip()}
    if event_type == "Engagement":
        inc["engagement_date"] = event_date
    else:
        inc["marriage_date"] = event_date
    me = _person_from_profile(owner_email) if db_is_connected() else {}
    if me.get("name"):
        for idx, other in ((1, groom), (2, bride)):
            if _names_match(me["name"], other):
                inc[f"spouse{idx}_name"] = _longer_name(inc[f"spouse{idx}_name"], me["name"])
                inc[f"spouse{idx}_email"] = owner_email
                if me.get("dob"):
                    inc[f"spouse{idx}_dob"] = me["dob"]
                break
    changed = db_upsert_auto_couple(owner_email, inc, source)
    if changed:
        sync_couples_from_wedding_plans(owner_email)  # also fills the partner's DOB/e-mail if they're linked
    return changed


# =====================================================================
# AUTOMATIC BIRTHDAY / ANNIVERSARY E-MAILS
# Streamlit has no built-in scheduler, so the server checks for due
# greetings in the background (at most once an hour) whenever the app is
# awake. For guaranteed delivery on days when nobody opens the app, also
# run send_celebration_emails.py from a daily cron / GitHub Action — both
# use the same logic and the same "already sent" log, so nobody is ever
# emailed twice.
# =====================================================================
def _smtp_configured():
    try:
        return bool(_secret("SMTP_EMAIL")) and bool(_secret("SMTP_APP_PASSWORD"))
    except Exception:
        return False


@st.cache_resource(show_spinner=False)
def _celebration_job_state():
    return {"last_run": 0.0, "lock": threading.Lock()}


def _celebration_job_worker(db):
    try:
        cel_run_job(db, lambda to, subject, body: send_notification_email(to, "Wedding & Anniversary Reminders", subject, body))
    except Exception:
        pass


def maybe_run_celebration_emails_in_background(min_interval_seconds=3600):
    """Called on every app run. At most once an hour per server it starts a
    background thread that emails every birthday / anniversary due today
    (nothing happens on days with none, and the send-log guarantees no
    duplicates). Silent no-op if MongoDB or SMTP isn't configured yet."""
    try:
        if not db_is_connected() or not _smtp_configured():
            return
        state = _celebration_job_state()
        with state["lock"]:
            if time.time() - state["last_run"] < min_interval_seconds:
                return
            state["last_run"] = time.time()
        threading.Thread(target=_celebration_job_worker, args=(get_db(),), daemon=True).start()
    except Exception:
        pass


CELEBRATION_SOURCE_LABELS = {
    "wedding_plan": "🔗 Wedding Countdown",
    "invitation": "🎨 Invitation Card",
    "success_story": "💖 Success Story",
    "manual": "✍️ Added manually",
}


def _clamp_date(v, lo, hi):
    return min(max(v, lo), hi)


def _fmt_date(d):
    return d.strftime("%d %b %Y") if isinstance(d, dt.date) else "—"


def _build_couple_events(c, today):
    """Every upcoming event for one couple, with the wish text to send."""
    events = []
    s1, s2 = c.get("spouse1_name", ""), c.get("spouse2_name", "")
    pair = f"{s1} & {s2}"
    cid = c.get("id", "x")
    for idx, name in ((1, s1), (2, s2)):
        dob = c.get(f"spouse{idx}_dob")
        if name and isinstance(dob, dt.date):
            events.append({
                "kind": "birthday", "label": "Birthday", "icon": "🎂", "person": name,
                "date": cel_next_occurrence(dob, today),
                "recipients": [(name, c.get(f"spouse{idx}_email", ""))],
                "wish": f"🎂 Wishing you a very Happy Birthday, {name}! — Team Siddhivinayak Matrimony",
                "uid": f"{cid}_b{idx}",
            })
    md = c.get("marriage_date")
    if isinstance(md, dt.date):
        recips = [(s1, c.get("spouse1_email", "")), (s2, c.get("spouse2_email", ""))]
        nxt = cel_next_occurrence(md, today) if md <= today else md
        years = nxt.year - md.year
        if years <= 0:
            events.append({
                "kind": "wedding", "label": "Wedding Day", "icon": "💍", "person": pair, "date": md,
                "recipients": recips,
                "wish": f"💍 Shubh Vivah! Heartfelt congratulations to {pair} on the wedding day! — Team Siddhivinayak Matrimony",
                "uid": f"{cid}_wed",
            })
        else:
            events.append({
                "kind": "anniversary", "label": f"{cel_ordinal(years)} Wedding Anniversary", "icon": "🎊", "person": pair, "date": nxt,
                "recipients": recips,
                "wish": f"🎊 Congratulations & Happy {cel_ordinal(years)} Wedding Anniversary, {pair}! — Team Siddhivinayak Matrimony",
                "uid": f"{cid}_ann",
            })
    ed = c.get("engagement_date")
    if isinstance(ed, dt.date) and ed >= today:
        events.append({
            "kind": "engagement", "label": "Engagement", "icon": "💍", "person": pair, "date": ed,
            "recipients": [(s1, c.get("spouse1_email", "")), (s2, c.get("spouse2_email", ""))],
            "wish": f"💍 Congratulations {pair} on your engagement! — Team Siddhivinayak Matrimony",
            "uid": f"{cid}_eng",
        })
    return events


