# =====================================================================
# VENDOR INBOX \u2014 real two-way messaging between a client and a vendor.
# ---------------------------------------------------------------------
# A client chats with a vendor using the vendor's business e-mail as the
# contact id (that is what Wedding Services passes). Every client message
# to a REAL, approved vendor is also written into the vendor's own inbox
# (a mirror row in db.messages owned by the vendor's login), and every
# vendor reply is written into the client's thread. Neither side ever sees
# the other's phone number or e-mail.
# =====================================================================
@cached_read("vendors")
def db_vendor_login_for_contact(contact_id):
    """(vendor_login_email, business_name) if contact_id is the business
    e-mail of a real, approved vendor; otherwise None (demo vendor, match...)."""
    db = get_db()
    if db is None or not contact_id or "@" not in str(contact_id):
        return None
    docs = list(db.vendors.find({"business_email": contact_id, "status": "Approved"}).limit(1))
    if not docs:
        return None
    d = docs[0]
    return (d.get("registered_by_email") or d.get("business_email"), d.get("business_name") or str(contact_id))


@cached_read("vendors")
def db_vendor_listing_for_login(login_email):
    db = get_db()
    if db is None or not login_email:
        return None
    for q in ({"registered_by_email": login_email, "status": "Approved"}, {"business_email": login_email, "status": "Approved"}):
        docs = list(db.vendors.find(q).sort("submitted_at", -1).limit(1))
        if docs:
            return docs[0]
    return None


@cached_read("messages", "vendors")
def db_list_vendor_conversations_for_client(email):
    """Vendors this client has already messaged, so the thread stays in their
    chat list (and vendor replies are reachable) after they leave the page."""
    db = get_db()
    if db is None or not email:
        return []
    ids = {d.get("contact_id") for d in db.messages.find({"owner_email": email}, {"contact_id": 1}) if "@" in str(d.get("contact_id", ""))}
    if not ids:
        return []
    return [{"contact_id": v["business_email"], "name": v.get("business_name") or v["business_email"], "city": v.get("city")}
            for v in db.vendors.find({"business_email": {"$in": list(ids)}, "status": "Approved"})]


@_invalidate_cache_after("blocks", "messages", "profile_blocks", "user_notifications", "vendors")
def db_deliver_to_vendor(client_email, client_name, contact_id, content):
    """Client -> vendor. Returns True if the contact is a real vendor and the
    message reached their inbox (False for demo vendors / blocked pairs)."""
    info = db_vendor_login_for_contact(contact_id)
    if not info:
        return False
    vendor_login, _vendor_name = info
    if vendor_login == client_email or db_is_pair_blocked(client_email, vendor_login) or db_is_pair_blocked(client_email, contact_id):
        return False
    db = get_db()
    had_unread = db.messages.find_one({"owner_email": vendor_login, "contact_id": client_email, "unread": True}) is not None
    db.messages.insert_one({
        "conversation_id": db_conversation_id(vendor_login, client_email), "owner_email": vendor_login,
        "contact_id": client_email, "contact_name": client_name or client_email, "role": "assistant",
        "content": content, "sent_at": dt.datetime.utcnow(), "unread": True, "vendor_business_email": contact_id,
    })
    if not had_unread:   # one heads-up per unread burst, not one per message
        pid = profile_public_id(client_email)
        db_add_user_notification(vendor_login, "vendor_message", f"New message from {client_name or 'a couple'} (ID {pid})",
                                 icon="\U0001F4AC", link_view="vendor_inbox", extra={"contact_id": client_email})
        try:
            send_notification_email(
                contact_id, "Messages & Chat", "\U0001F4AC New message on your Siddhivinayak Matrimony listing",
                f"Hi,\n\n{client_name or 'A couple'} (Profile ID {pid}) sent a message to your listing. "
                "Log in to Siddhivinayak Matrimony \u2192 Vendor Inbox to read and reply.\n\nAll conversations stay inside Siddhivinayak Matrimony \u2014 "
                "phone numbers and e-mails aren't exchanged here.\n\n\u2014 Team Siddhivinayak Matrimony")
        except Exception:
            pass
    return True


def db_vendor_reply(vendor_login, client_email, client_name, content):
    """Vendor -> client. Saved in both threads; the client gets an in-app
    notification (+ e-mail). Returns False if blocked / no approved listing."""
    listing = db_vendor_listing_for_login(vendor_login)
    if not listing:
        return False
    biz_email, biz_name = listing["business_email"], listing.get("business_name") or listing["business_email"]
    if db_is_pair_blocked(vendor_login, client_email) or db_is_pair_blocked(client_email, biz_email):
        return False
    db_send_message(vendor_login, client_email, "user", content, contact_name=client_name or client_email)
    db_send_message(client_email, biz_email, "assistant", content, contact_name=biz_name)
    db_add_user_notification(client_email, "vendor_reply", f"{biz_name} replied to your message", icon="\U0001F4AC",
                             link_view="chat_alerts", extra={"contact_id": biz_email, "contact_name": biz_name})
    try:
        send_notification_email(client_email, "Messages & Chat", f"\U0001F4AC {biz_name} replied on Siddhivinayak Matrimony",
                           f"Hi,\n\n{biz_name} replied to your message. Open Chat & Alerts on Siddhivinayak Matrimony to read it.\n\n\u2014 Team Siddhivinayak Matrimony")
    except Exception:
        pass
    return True


@cached_read("messages")
def db_vendor_inbox_threads(vendor_login):
    db = get_db()
    if db is None:
        return []
    threads = {}
    for m in db.messages.find({"owner_email": vendor_login}).sort("sent_at", -1).limit(1000):
        t = threads.setdefault(m["contact_id"], {"contact_id": m["contact_id"], "contact_name": m.get("contact_name") or m["contact_id"],
                                                 "last": m.get("content", ""), "last_at": m.get("sent_at"), "unread": 0})
        if m.get("unread"):
            t["unread"] += 1
    return sorted(threads.values(), key=lambda t: t["last_at"] or dt.datetime.min, reverse=True)


@cached_read("messages")
def db_count_vendor_unread(vendor_login):
    db = get_db()
    if db is None or not vendor_login:
        return 0
    return db.messages.count_documents({"owner_email": vendor_login, "unread": True})


@_invalidate_cache_after("messages")
def db_mark_vendor_thread_read(vendor_login, contact_id):
    db = get_db()
    if db is not None:
        db.messages.update_many({"owner_email": vendor_login, "contact_id": contact_id, "unread": True}, {"$set": {"unread": False}})


def page_vendor_inbox():
    render_global_css(bg_color="#F8F9FA", page_css=""".vi-header { background: linear-gradient(135deg, #0F2027 0%, #203A43 50%, #2C5364 100%); padding: 28px; border-radius: 18px; color: white; text-align: center; border: 2px solid #D4AF37; margin-bottom: 20px; }
.vi-person { background:#F8FAFC; border:1px solid #E2E8F0; border-radius:12px; padding:10px 14px; margin-bottom:12px; }
.vi-safety { background:#FFF5F5; border:1px solid #E53E3E; border-left:6px solid #E53E3E; border-radius:10px; padding:10px 14px; color:#7B1113; margin:10px 0; font-size:0.9rem; }""")
    import html as _html
    DASH = "\u2014"

    st.markdown("""
    <div class="vi-header">
        <h1 style="margin:0; font-family:'Georgia', serif;">\U0001F4E5 Vendor Inbox</h1>
        <p style="color:#FBF5B7; margin-top:8px;">Messages from couples who found your listing on Siddhivinayak Matrimony.</p>
    </div>
    """, unsafe_allow_html=True)

    if st.session_state.get("user_role") != "vendor":
        st.error("\U0001F6AB The Vendor Inbox is for registered vendors only.")
        return
    login = st.session_state.get("user_email") or ""
    if not db_is_connected():
        st.info("\U0001F4F1 Demo mode: connect MongoDB (MONGODB_URI in Secrets) to receive real messages from couples.")
        return
    listing = db_vendor_listing_for_login(login)
    if not listing:
        st.info("Your vendor listing needs to be approved before couples can message you. Once it's live, their messages appear here.")
        if st.button("\U0001F4DD Go to Vendor Registration", key="vi_goto_reg"):
            go_to("vendor_registration")
        return

    flash = st.session_state.pop("vinbox_flash", None)
    if flash:
        st.success(flash)
    st.caption(f"Messages sent to **{listing.get('business_name', '')}**. Couples' phone numbers and e-mails are never shown \u2014 everything stays in-app.")

    threads = db_vendor_inbox_threads(login)
    if not threads:
        st.info("No messages yet. When a couple messages your listing, it will appear here and you'll get an e-mail.")
        return
    ids = [t["contact_id"] for t in threads]
    by_id = {t["contact_id"]: t for t in threads}
    pre = st.session_state.pop("vendor_inbox_preselect", None)
    if pre in ids:
        st.session_state["vinbox_thread"] = pre
    if st.session_state.get("vinbox_thread") not in ids:
        st.session_state.pop("vinbox_thread", None)

    def thread_label(cid):
        t = by_id[cid]
        badge = f" \U0001F534{t['unread']}" if t["unread"] else ""
        return f"{t['contact_name']}{badge}"

    left, right = st.columns([1, 2], gap="medium")
    with left:
        st.markdown("### \U0001F4AC Conversations")
        sel = st.radio("Conversations", ids, format_func=thread_label, key="vinbox_thread", label_visibility="collapsed")
        total_unread = sum(t["unread"] for t in threads)
        if total_unread:
            st.caption(f"\U0001F514 {total_unread} unread message(s)")

    with right:
        prof = db_get_profile(sel) or {}
        name = prof.get("name") or by_id[sel]["contact_name"]
        st.markdown(
            f"<div class='vi-person'><b>{_html.escape(str(name))}</b> &nbsp;\U0001F194 <b>{profile_public_id(sel)}</b> "
            f"&nbsp;\U0001F3D9\uFE0F {_html.escape(str(prof.get('city') or DASH))}</div>", unsafe_allow_html=True,
        )
        history = db_get_messages(login, sel) or []
        for msg in history[-40:]:
            with st.chat_message("user" if msg["role"] == "user" else "assistant"):
                st.markdown(msg["content"])
        db_mark_vendor_thread_read(login, sel)

        blocked = db_is_pair_blocked(login, sel)
        if blocked:
            st.warning("\U0001F6AB This conversation is blocked, so you can't reply.")
        else:
            nonce = st.session_state.get("vinbox_nonce", 0)
            reply = st.text_area("Your reply", key=f"vinbox_reply_{nonce}", placeholder="Type your reply\u2026", max_chars=1000, height=100)
            st.markdown("<div class='vi-safety'>\U0001F512 Please don't share phone numbers, e-mails or WhatsApp / social handles \u2014 "
                        "they're blocked automatically. Keep quotes and bookings inside Siddhivinayak Matrimony.</div>", unsafe_allow_html=True)
            if st.button("\U0001F4E4 Send Reply", type="primary", key="vinbox_send", use_container_width=True):
                text = (reply or "").strip()
                if not text:
                    st.warning("Please type a message first.")
                elif contains_contact_info(text):
                    st.error("\U0001F6AB Phone numbers, e-mail addresses and requests to move off Siddhivinayak Matrimony aren't allowed \u2014 including partial numbers "
                             "or digits spelled out in words. Tip: write prices normally (\u20b950,000).")
                elif db_vendor_reply(login, sel, name, text):
                    st.session_state.vinbox_nonce = nonce + 1
                    st.session_state.vinbox_flash = f"\u2705 Reply sent to {name}."
                    st.rerun()
                else:
                    st.error("Couldn't send the reply right now. Please try again.")
        if st.button("\U0001F6A8 Report & Block this person", key="vinbox_report", use_container_width=True):
            open_report_for(name, sel)


