# PAGE: COMPANY DASHBOARD (BOSS ONLY)
# =====================================================================
def render_safety_report_admin_card(rep, key_prefix, unread_ids=None, show_actions=True):
    """One safety report with everything the company needs: who reported,
    who was reported (name / Profile ID / email), why, evidence, whether
    the reporter has blocked them, and the actions to warn / review /
    dismiss / block / unblock. Company can lift a block the reporter made."""
    rid = str(rep["_id"])
    reporter_email = rep.get("reporter_email", "")
    reporter_prof = (db_get_profile(reporter_email) or {}) if reporter_email and "@" in reporter_email else {}
    reporter_name = rep.get("reporter_name") or reporter_prof.get("name") or "\u2014"
    reporter_pid = rep.get("reporter_public_id") or profile_public_id(reporter_email)
    reported_uid = rep.get("reported_uid") or rep.get("reported_email") or rep.get("profile_name", "")
    reported_pid = rep.get("reported_public_id") or (profile_public_id(reported_uid) if reported_uid else "\u2014")
    ref = f"#{rid[-8:].upper()}"
    is_new = bool(unread_ids and rid in unread_ids)
    is_blocked = bool(reporter_email and reported_uid and db_is_blocked(reporter_email, reported_uid))
    submitted = utc_to_ist(rep.get("submitted_at"))
    new_tag = "\U0001F195 " if is_new else ""
    dash = "\u2014"

    with st.container(border=True):
        st.markdown(f"{new_tag}**{ref}** \u2014 {rep.get('reason', '')} \u00a0\u2022\u00a0 Status: **{rep.get('status', 'Under Review')}**")
        c1, c2 = st.columns(2)
        c1.markdown(f"**Reported by**  \n{reporter_name}  \n\U0001F194 {reporter_pid}  \n\U0001F4E7 {reporter_email or dash}")
        c2.markdown(f"**Reported profile**  \n{rep.get('profile_name', '')}  \n\U0001F194 {reported_pid}  \n\U0001F4E7 {rep.get('reported_email') or 'not on file (demo / unregistered profile)'}")
        if submitted:
            st.caption(f"\U0001F552 {submitted.strftime('%d %b %Y, %I:%M %p')} IST")
        if rep.get("details"):
            st.markdown(f"> {rep['details']}")
        if rep.get("evidence_ref"):
            ev_bytes = media_get_bytes(rep["evidence_ref"])
            ev_key = str(rep["evidence_ref"].get("key", ""))
            if ev_bytes and ev_key.lower().endswith((".png", ".jpg", ".jpeg")):
                st.image(ev_bytes, width=260, caption="Evidence attached by reporter")
            elif ev_bytes:
                st.download_button("\U0001F4CE Download evidence", ev_bytes, file_name=ev_key.split("_", 1)[-1] or "evidence", key=f"{key_prefix}_ev_{rid}")
            else:
                st.caption("\U0001F4CE Evidence was attached but couldn't be loaded from storage.")
        elif rep.get("has_evidence"):
            st.caption("\U0001F4CE Evidence was attached, but this report predates evidence storage.")
        st.markdown(
            "\U0001F6AB **Blocked by reporter** \u2014 only between these two profiles; everyone else still sees both."
            if is_blocked else "\u2705 Not blocked"
        )

        if show_actions:
            rc1, rc2, rc3 = st.columns(3)
            if rc1.button("\u26A0\uFE0F Send Warning", key=f"{key_prefix}_warn_{rid}", use_container_width=True, disabled=not rep.get("reported_email")):
                sent, info = db_send_safety_warning(rid, rep.get("reported_email"))
                if sent:
                    st.success(f"\u2705 Warning email sent to {rep['reported_email']}.")
                else:
                    st.error(f"\u274C Couldn't send warning: {info}")
                st.rerun()
            if rc2.button("\u2705 Mark Reviewed", key=f"{key_prefix}_review_{rid}", use_container_width=True):
                db_update_safety_report_status(rid, "Reviewed")
                st.rerun()
            if rc3.button("\u274C Dismiss", key=f"{key_prefix}_dismiss_{rid}", use_container_width=True):
                db_update_safety_report_status(rid, "Dismissed")
                st.rerun()

        if reporter_email and reported_uid:
            if is_blocked:
                if st.button("\U0001F513 Unblock this pair (company override)", key=f"{key_prefix}_unblock_{rid}", use_container_width=True):
                    db_unblock_pair(reporter_email, reported_uid)
                    db_log_admin_action("safety_unblock", f"{reporter_email} <-> {reported_uid}", "Unblocked")
                    st.rerun()
            else:
                if st.button("\U0001F6AB Block this pair", key=f"{key_prefix}_block_{rid}", use_container_width=True):
                    db_block_pair(reporter_email, reported_uid, rep.get("profile_name"))
                    db_log_admin_action("safety_block", f"{reporter_email} <-> {reported_uid}", "Blocked")
                    st.rerun()


# =====================================================================
# ADMIN REVIEW CARD HELPERS
# * admin_photo_3x4(): shows a photo at exactly 3 x 4 inch (288 x 384 px
#   at 96 dpi). The whole photo stays visible (letterboxed on white, not
#   cropped) so the reviewer never misses part of the face.
# * admin_member_details_html(): Profile ID + full name + gender/age,
#   religion/caste, city, etc. so every verification card says clearly
#   WHO the photo belongs to.
# =====================================================================
ADMIN_PHOTO_W_PX = 288   # 3 inch x 96 dpi
ADMIN_PHOTO_H_PX = 384   # 4 inch x 96 dpi


def admin_photo_3x4(photo_bytes, caption=None):
    """Render image bytes at a fixed 3x4 inch size."""
    try:
        from PIL import ImageOps
        img = Image.open(BytesIO(photo_bytes))
        img = ImageOps.exif_transpose(img).convert("RGB")
        img = ImageOps.contain(img, (ADMIN_PHOTO_W_PX * 2, ADMIN_PHOTO_H_PX * 2))  # 2x for sharpness
        canvas = Image.new("RGB", (ADMIN_PHOTO_W_PX * 2, ADMIN_PHOTO_H_PX * 2), (255, 255, 255))
        canvas.paste(img, ((canvas.width - img.width) // 2, (canvas.height - img.height) // 2))
        st.image(canvas, width=ADMIN_PHOTO_W_PX, caption=caption)
    except Exception:
        st.image(photo_bytes, width=ADMIN_PHOTO_W_PX, caption=caption)


def admin_member_details_html(p):
    """Compact details block for a profile dict (Profile ID, name, caste, city...)."""
    email = p.get("email", "") or ""
    pid = profile_public_id(email) if email else "-"
    age_txt = ""
    try:
        dob_v = p.get("dob")
        if dob_v:
            d_ = dt.date.fromisoformat(str(dob_v)[:10])
            t_ = dt.date.today()
            age_txt = f"{t_.year - d_.year - ((t_.month, t_.day) < (d_.month, d_.day))} yrs"
    except Exception:
        age_txt = ""
    rows = [
        ("Profile ID", pid),
        ("Full Name", p.get("name", "")),
        ("Gender / Age", " / ".join(x for x in [p.get("gender", ""), age_txt] if x)),
        ("Religion", p.get("religion", "")),
        ("Caste", p.get("caste", "")),
        ("Gotra", p.get("gotra", "")),
        ("City", p.get("city", "")),
        ("Mother Tongue", p.get("mother_tongue", "")),
        ("Profession", p.get("profession", "")),
        ("Education", p.get("education", "")),
        ("Marital Status", p.get("marital_status", "")),
        ("Email", email),
    ]
    lines = "".join(
        f"<div style='margin:2px 0;'><b>{_html_escape(k)}:</b> {_html_escape(str(v))}</div>"
        for k, v in rows if v
    )
    return f"<div style='font-size:0.92rem; line-height:1.4;'>{lines}</div>"


def render_company_safety_section():
    st.markdown("### \U0001F6A8 Pending Safety Reports")
