# =====================================================================
# COMPANY DASHBOARD — drill-down lists behind each clickable metric
#
# Every metric card below (Total Registered, Active/Inactive Users,
# Active/Inactive Vendors, Paid/Unpaid Members, Boosted Profiles) now
# opens a real list of exactly who makes up that number, pulled live
# from MongoDB. Capped at `limit` (newest first) so a large user base
# can't make the dashboard itself slow to open \u2014 same reasoning as the
# rest of the app's caching work. Registered under @cached_read so
# re-opening the dashboard is instant until someone actually
# registers/logs in/upgrades, at which point the matching cache (and
# only that one) is cleared automatically.
# =====================================================================
@cached_read("users", "profiles")
def db_admin_list_users(mode="all", limit=300):
    """mode: 'all', 'active' (logged in within 30 days), 'inactive'
    (no login in 30+ days, or never), 'paid' (current membership),
    or 'unpaid'. City/name are joined in from the profile document
    since they aren't stored on the user account itself."""
    db = get_db()
    if db is None:
        return []
    now = dt.datetime.utcnow()
    cutoff = now - dt.timedelta(days=30)
    query = {}
    if mode == "active":
        query = {"last_login": {"$gte": cutoff}}
    elif mode == "inactive":
        query = {"$or": [{"last_login": {"$lt": cutoff}}, {"last_login": {"$exists": False}}]}
    elif mode == "paid":
        query = {"membership_expires_at": {"$gte": now}}
    elif mode == "unpaid":
        query = {"membership_expires_at": {"$not": {"$gte": now}}}
    projection = {"email": 1, "name": 1, "role": 1, "created_at": 1, "last_login": 1,
                  "membership_tier": 1, "membership_expires_at": 1}
    users = list(db.users.find(query, projection).sort("created_at", -1).limit(limit))
    emails = [u["email"] for u in users if u.get("email")]
    city_by_email, name_by_email = {}, {}
    if emails:
        for p in db.profiles.find({"email": {"$in": emails}}, {"email": 1, "city": 1, "name": 1}):
            city_by_email[p["email"]] = p.get("city", "")
            if p.get("name"):
                name_by_email[p["email"]] = p["name"]
    for u in users:
        u["city"] = city_by_email.get(u.get("email"), "") or "\u2014"
        if not u.get("name"):
            u["name"] = name_by_email.get(u.get("email"), "\u2014")
        u["is_paid"] = bool(u.get("membership_expires_at") and u["membership_expires_at"] >= now)
    return users


# =====================================================================
# ADMIN: ALL REGISTRATIONS (PAN-INDIA) IN ONE LIST
# One row per registered member \u2014 photo thumbnail, Profile ID, full
# name, city, caste, mobile, yearly package (income), plus verification
# status columns \u2014 so the admin can check everyone together. Searchable
# / filterable, paginated (thumbnails are only built for the visible page
# so a big member base stays fast) and downloadable as CSV.
# =====================================================================
@cached_read("users", "profiles")
def db_admin_list_all_registrations(limit=5000):
    db = get_db()
    if db is None:
        return []
    projection = {"email": 1, "name": 1, "city": 1, "caste": 1, "religion": 1, "phone": 1, "income": 1,
                  "gender": 1, "dob": 1, "photo_refs": 1, "profile_photo_index": 1, "photo_status": 1,
                  "aadhaar_masked": 1, "id_verification_status": 1, "aadhaar_verified": 1,
                  "updated_at": 1, "created_at": 1}
    docs = list(db.profiles.find({"name": {"$exists": True, "$ne": ""}}, projection).sort("updated_at", -1).limit(limit))
    emails = [d["email"] for d in docs if d.get("email")]
    created = {}
    if emails:
        for u in db.users.find({"email": {"$in": emails}}, {"email": 1, "created_at": 1}):
            created[u["email"]] = u.get("created_at")
    rows = []
    for d in docs:
        email = d.get("email", "")
        refs = d.get("photo_refs") or []
        idx = d.get("profile_photo_index", 0)
        if not isinstance(idx, int) or idx < 0 or idx >= len(refs):
            idx = 0
        reg_dt = created.get(email) or d.get("created_at") or d.get("updated_at")
        rows.append({
            "email": email,
            "profile_id": profile_public_id(email) if email else "",
            "name": d.get("name", ""),
            "gender": d.get("gender", ""),
            "age": _profile_age(d),
            "city": (d.get("city") or "").strip(),
            "caste": (d.get("caste") or "").strip(),
            "religion": d.get("religion", ""),
            "phone": d.get("phone", ""),
            "income": d.get("income", ""),
            "aadhaar_masked": d.get("aadhaar_masked", ""),
            "photo_ref": refs[idx] if refs else None,
            "photo_status": d.get("photo_status", "No Photos"),
            "id_status": d.get("id_verification_status") or ("Verified" if d.get("aadhaar_verified") else "Not Submitted"),
            "registered_at": reg_dt,
        })
    return rows


@st.cache_data(show_spinner=False, ttl=300)
def admin_thumb_data_uri(media_ref, w=72, h=96):
    """Small 3:4 thumbnail (as a data URI) for the admin list's Photo column."""
    try:
        from PIL import ImageOps
        b = media_get_bytes(media_ref)
        if not b:
            return None
        im = ImageOps.exif_transpose(Image.open(BytesIO(b))).convert("RGB")
        im = ImageOps.fit(im, (w * 2, h * 2), method=Image.LANCZOS, centering=(0.5, 0.3))
        out = BytesIO()
        im.save(out, format="JPEG", quality=80)
        return "data:image/jpeg;base64," + base64.b64encode(out.getvalue()).decode()
    except Exception:
        return None


def render_admin_registrations_list():
    st.markdown("### \U0001F4CB All Registered Members (Pan-India)")
    rows = db_admin_list_all_registrations()
    if not rows:
        st.caption("No registrations yet (or MongoDB isn't connected, so this list is empty in demo mode).")
        return

    # ---- filters ----
    f1, f2, f3, f4 = st.columns([2.2, 1.4, 1.4, 1.4])
    q = f1.text_input("\U0001F50D Search name / Profile ID / mobile / caste", key="adm_reg_q").strip().lower()
    city_opts = ["All Cities"] + sorted({r["city"] for r in rows if r["city"]}, key=str.lower)
    city_pick = f2.selectbox("City", city_opts, key="adm_reg_city")
    status_pick = f3.selectbox("Verification", ["All", "Photo pending", "ID pending", "Fully verified", "Rejected"], key="adm_reg_status")
    gender_pick = f4.selectbox("Gender", ["All", "Male", "Female"], key="adm_reg_gender")

    def keep(r):
        if q and q not in " ".join(str(r.get(k, "")) for k in ("name", "profile_id", "phone", "caste", "city", "email")).lower():
            return False
        if city_pick != "All Cities" and r["city"] != city_pick:
            return False
        if gender_pick != "All" and r["gender"] != gender_pick:
            return False
        if status_pick == "Photo pending" and r["photo_status"] != "Pending Review":
            return False
        if status_pick == "ID pending" and r["id_status"] != "Pending":
            return False
        if status_pick == "Fully verified" and not (r["photo_status"] == "Approved" and r["id_status"] == "Verified"):
            return False
        if status_pick == "Rejected" and "Rejected" not in (r["photo_status"], r["id_status"]):
            return False
        return True

    filtered = [r for r in rows if keep(r)]
    n_cities = len({r["city"] for r in rows if r["city"]})
    m1, m2, m3 = st.columns(3)
    m1.metric("Total registrations", f"{len(rows):,}")
    m2.metric("Cities covered", f"{n_cities:,}")
    m3.metric("Matching filters", f"{len(filtered):,}")

    def _fmt_dt(x):
        try:
            return x.strftime("%d %b %Y")
        except Exception:
            return ""

    # ---- CSV of ALL filtered rows (no photos) ----
    csv_df = pd.DataFrame([{
        "Profile ID": r["profile_id"], "Full Name": r["name"], "City": r["city"], "Caste": r["caste"],
        "Mobile": r["phone"], "Yearly Package": r["income"], "Gender": r["gender"], "Age": r["age"],
        "Aadhaar (masked)": r["aadhaar_masked"], "Photo Status": r["photo_status"], "ID Status": r["id_status"],
        "Registered On": _fmt_dt(r["registered_at"]), "Email": r["email"],
    } for r in filtered])
    st.download_button("\u2B07\uFE0F Download this list (CSV)", csv_df.to_csv(index=False).encode("utf-8-sig"),
                       file_name="registered_members.csv", mime="text/csv", key="adm_reg_csv")

    # ---- pagination (thumbnails built only for the visible page) ----
    pc1, pc2 = st.columns([1, 1])
    page_size = pc1.selectbox("Rows per page", [25, 50, 100], index=0, key="adm_reg_pagesize")
    total_pages = max(1, -(-len(filtered) // page_size))
    page_no = pc2.number_input(f"Page (of {total_pages})", min_value=1, max_value=total_pages, value=1, step=1, key="adm_reg_page")
    chunk = filtered[(page_no - 1) * page_size: page_no * page_size]

    table = pd.DataFrame([{
        "Photo": admin_thumb_data_uri(r["photo_ref"]) if r["photo_ref"] else None,
        "Profile ID": r["profile_id"],
        "Full Name": r["name"],
        "City": r["city"] or "\u2014",
        "Caste": r["caste"] or "\u2014",
        "Mobile": r["phone"] or "\u2014",
        "Yearly Package": r["income"] or "\u2014",
        "Gender / Age": " / ".join(x for x in [r["gender"], f"{r['age']} yrs" if r["age"] else ""] if x) or "\u2014",
        "Aadhaar": r["aadhaar_masked"] or "\u2014",
        "Photo Status": r["photo_status"],
        "ID Status": r["id_status"],
        "Registered": _fmt_dt(r["registered_at"]),
    } for r in chunk])
    cfg = {"Photo": st.column_config.ImageColumn("Photo", width="small")}
    try:
        st.dataframe(table, use_container_width=True, hide_index=True, column_config=cfg, row_height=96)
    except TypeError:
        # older Streamlit without row_height \u2014 still works, thumbnails just smaller
        st.dataframe(table, use_container_width=True, hide_index=True, column_config=cfg)
    st.caption(f"Showing {len(chunk)} of {len(filtered)} members. Approve / reject photos and IDs in the review sections below.")


# ---- Vendor Membership pricing (must match the ₹ amounts / validity
# shown on page_vendor_membership) — used only to translate a vendor's
# stored membership_tier into a rupee amount + day count for the admin
# drill-down below, since the vendor's own document doesn't store the
# price/duration itself (only the resulting tier + expiry date do, via
# db_activate_membership on the shared db.users collection). ----
VENDOR_TIER_PRICING = {
    "free": {"label": "\U0001F193 Free", "amount": 0, "days": 90},
    "silver": {"label": "\U0001F948 Silver", "amount": 699, "days": 180},
    "gold": {"label": "\U0001F947 Gold", "amount": 1199, "days": 365},
}


@cached_read("vendors", "users")
def db_admin_list_vendors(mode="all", limit=300):
    """mode: 'all', 'active' (status == Approved, i.e. currently live on
    the platform), or 'inactive' (Pending/Rejected \u2014 not currently
    visible to couples). Vendor accounts don't have their own login
    tracking yet, so approval status is the most honest real signal of
    whether a vendor listing is actually live right now.

    Each vendor is also joined (by business_email) against db.users to
    pull in which paid package they actually purchased — the amount and
    validity (in days) shown here are looked up from VENDOR_TIER_PRICING
    using their stored membership_tier, since the vendor document itself
    only ever stores the resulting tier name + expiry date, not the ₹
    amount or day-count that were true at the moment they bought it."""
    db = get_db()
    if db is None:
        return []
    query = {}
    if mode == "active":
        query = {"status": "Approved"}
    elif mode == "inactive":
        query = {"status": {"$ne": "Approved"}}
    projection = {"business_name": 1, "business_email": 1, "vendor_types": 1, "city": 1,
                  "status": 1, "submitted_at": 1}
    vendors = list(db.vendors.find(query, projection).sort("submitted_at", -1).limit(limit))
    emails = [v["business_email"] for v in vendors if v.get("business_email")]
    plan_by_email = {}
    if emails:
        for u in db.users.find({"email": {"$in": emails}}, {"email": 1, "membership_tier": 1, "membership_expires_at": 1}):
            plan_by_email[u["email"]] = u
    now = dt.datetime.utcnow()
    for v in vendors:
        u = plan_by_email.get(v.get("business_email"), {})
        tier = u.get("membership_tier")
        expires_at = u.get("membership_expires_at")
        pricing = VENDOR_TIER_PRICING.get(tier)
        v["package_label"] = pricing["label"] if pricing else "\u2014 (not purchased yet)"
        v["package_amount"] = pricing["amount"] if pricing else None
        v["package_days"] = pricing["days"] if pricing else None
        v["package_expires_at"] = expires_at
        v["package_is_active"] = bool(expires_at and expires_at >= now)
    return vendors


@cached_read("boosts")
def db_admin_list_active_boosts(limit=300):
    db = get_db()
    if db is None:
        return []
    now = dt.datetime.utcnow()
    return list(db.boosts.find({"expires_at": {"$gte": now}}, {"key": 1, "type": 1, "label": 1, "expires_at": 1})
                .sort("expires_at", -1).limit(limit))


def render_drill_metric(col, rows, cols_spec, total_count=None, empty_caption="No records yet.", button_label="\U0001F440 View list"):
    """Adds a small 'View list' popover under an st.metric() already
    placed in `col`, showing `rows` as a table. cols_spec is a list of
    (column_header, fn) pairs where fn(row) -> the value to display."""
    with col.popover(button_label, use_container_width=True):
        if rows:
            df = pd.DataFrame([{header: fn(r) for header, fn in cols_spec} for r in rows])
            st.dataframe(df, use_container_width=True, hide_index=True)
            if total_count is not None and total_count > len(rows):
                st.caption(f"Showing the most recent {len(rows):,} of {total_count:,}.")
        else:
            st.caption(empty_caption)


def _fmt_dt(v, fmt="%d %b %Y"):
    return v.strftime(fmt) if isinstance(v, (dt.datetime, dt.date)) else "\u2014"


def page_company_dashboard():
    render_global_css(bg_color="#F4F6F9", page_css="""
.admin-header { color: #1A365D; font-family: 'Helvetica Neue', sans-serif; font-weight: 900; font-size: 2.5rem; margin-bottom: 0px; }
.boss-badge { background: linear-gradient(135deg, #D4AF37, #AA771C); color: #0F2027; padding: 6px 16px; border-radius: 20px; font-weight: 800; font-size: 0.85rem; display: inline-block; }
.metric-card { background-color: white; padding: 20px; border-radius: 10px; box-shadow: 0 4px 6px rgba(0,0,0,0.05); border-top: 4px solid #D4AF37; }
.sync-pill { display:inline-block; padding: 4px 12px; border-radius: 20px; font-size: 0.8rem; font-weight: 600; }
""")

    if st.session_state.user_role != "boss":
        st.error("\U0001F6AB Your account doesn't have permission to view this page.")
        if st.button("\u2190 Back to Home"):
            go_to("home")
        return

    st.markdown("<span class='boss-badge'>\U0001F451 BOSS-ONLY VIEW</span>", unsafe_allow_html=True)
    st.markdown("<h1 class='admin-header'>Company Dashboard</h1>", unsafe_allow_html=True)
    st.markdown("<p style='color: #666;'>Full company-level overview — registrations, users, revenue, and platform health. Not visible to clients or vendors.</p>", unsafe_allow_html=True)
    st.markdown("---")

    sync_ok = db_is_connected()
    pill_style = "background:#DCFCE7; color:#166534;" if sync_ok else "background:#FEF3C7; color:#92400E;"
    pill_text = "\u2601\uFE0F Registration, vendor, and membership numbers below are live from MongoDB (revenue is still simulated pending a payment gateway)" if sync_ok else "\U0001F4F1 Demo mode \u2014 all numbers below are sample data, connect MongoDB for real figures"
    st.markdown(f"<span class='sync-pill' style='{pill_style}'>{pill_text}</span>", unsafe_allow_html=True)
    st.markdown("<br>", unsafe_allow_html=True)

    if sync_ok:
        db = get_db()
        now_utc = dt.datetime.utcnow()
        week_ago = now_utc - dt.timedelta(days=7)
        active_cutoff = now_utc - dt.timedelta(days=30)
        month_start = now_utc.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        total_registered = db.users.count_documents({})
        new_this_week = db.users.count_documents({"created_at": {"$gte": week_ago}})
        vendor_regs = db.vendors.count_documents({})
        new_vendor_regs = db.vendors.count_documents({"submitted_at": {"$gte": week_ago}})
        paid_members = db_count_paid_members()
        unpaid_members = max(total_registered - paid_members, 0)
        boosted_count = db.boosts.count_documents({"expires_at": {"$gte": now_utc}})
        active_users_count = db.users.count_documents({"last_login": {"$gte": active_cutoff}})
        inactive_users_count = max(total_registered - active_users_count, 0)
        active_vendors_count = db.vendors.count_documents({"status": "Approved"})
        inactive_vendors_count = max(vendor_regs - active_vendors_count, 0)
        # ---- BUG FIX: these two used to just show "N/A" with a caption
        # saying the tracking wasn't wired up. Both are actually derivable
        # from data the app already has, with no new instrumentation
        # needed:
        # - "Started but Not Completed": a Bride/Groom account exists in
        #   db.users the moment they sign up, but a real profile document
        #   only appears in db.profiles once they finish the Registration
        #   form \u2014 so client signups minus completed profiles IS this
        #   number, exactly.
        # - "Renewed This Month": every membership purchase now logs a
        #   membership_events entry (see db_activate_membership) tagging
        #   itself "new" vs "renewal" \u2014 count this month's renewals. ----
        client_signups = db.users.count_documents({"role": "client"})
        completed_profiles = db.profiles.count_documents({})
        started_not_completed = max(client_signups - completed_profiles, 0)
        renewed_this_month = db.membership_events.count_documents({"event_type": "renewal", "at": {"$gte": month_start}})
    else:
        total_registered, new_this_week, vendor_regs, new_vendor_regs = 12543, 324, 186, 9
        paid_members, unpaid_members, boosted_count = 3210, 9333, 417
        active_users_count, inactive_users_count = 8920, 3623
        active_vendors_count, inactive_vendors_count = 142, 44
        started_not_completed, renewed_this_month = 3812, 612

    user_cols_spec = [
        ("Name", lambda u: u.get("name", "\u2014")), ("Email", lambda u: u.get("email", "\u2014")),
        ("City", lambda u: u.get("city", "\u2014")), ("Joined", lambda u: _fmt_dt(u.get("created_at"))),
        ("Last Login", lambda u: _fmt_dt(u.get("last_login")) if u.get("last_login") else "Never"),
        ("Plan", lambda u: "Paid" if u.get("is_paid") else "Free"),
    ]
    vendor_cols_spec = [
        ("Business", lambda v: v.get("business_name", "\u2014")), ("Email", lambda v: v.get("business_email", "\u2014")),
        ("Category", lambda v: ", ".join(v.get("vendor_types") or []) or "\u2014"),
        ("City", lambda v: v.get("city", "\u2014")), ("Status", lambda v: v.get("status", "\u2014")),
        # ---- Which paid package this vendor actually purchased, how
        # much it cost, and how many days it's valid for — the exact
        # thing Boss needs to click into and check per vendor. ----
        ("Package", lambda v: v.get("package_label", "\u2014")),
        ("Amount Paid", lambda v: f"\u20b9{v['package_amount']:,}" if v.get("package_amount") is not None else "\u2014"),
        ("Valid For", lambda v: f"{v['package_days']} days" if v.get("package_days") else "\u2014"),
        ("Valid Until", lambda v: _fmt_dt(v.get("package_expires_at")) if v.get("package_expires_at") else "\u2014"),
        ("Package Active?", lambda v: "\u2705 Yes" if v.get("package_is_active") else "\u274C Expired/None"),
        ("Submitted", lambda v: _fmt_dt(v.get("submitted_at"))),
    ]
    boost_cols_spec = [
        ("Who", lambda b: b.get("key", "\u2014")), ("Type", lambda b: b.get("type", "\u2014")),
        ("Plan", lambda b: b.get("label", "\u2014")), ("Expires", lambda b: _fmt_dt(b.get("expires_at"))),
    ]

    st.markdown("### \U0001F4CB Registration Overview")
