    r4.metric("\U0001F4DD Vendor Registrations", f"{vendor_regs:,}", f"+{new_vendor_regs} this week")
    if sync_ok:
        render_drill_metric(r1, db_admin_list_users(mode="all"), user_cols_spec, total_count=total_registered)
        render_drill_metric(r3, db_admin_list_users(mode="all"), user_cols_spec, total_count=completed_profiles)
        render_drill_metric(r4, db_admin_list_vendors(mode="all"), vendor_cols_spec, total_count=vendor_regs)

    st.markdown("<br>", unsafe_allow_html=True)
    st.markdown("### \U0001F7E2 Activity Status")
    a1, a2, a3, a4 = st.columns(4)
    active_user_pct = f"{active_users_count/total_registered*100:.0f}% of total" if total_registered else ""
    inactive_user_pct = f"{inactive_users_count/total_registered*100:.0f}% of total" if total_registered else ""
    active_vendor_pct = f"{active_vendors_count/vendor_regs*100:.0f}% of vendors" if vendor_regs else ""
    inactive_vendor_pct = f"{inactive_vendors_count/vendor_regs*100:.0f}% of vendors" if vendor_regs else ""
    a1.metric("\U0001F7E2 Active Users (30 days)", f"{active_users_count:,}", active_user_pct, help="Logged in within the last 30 days." if sync_ok else None)
    a2.metric("\U0001F534 Inactive Users", f"{inactive_users_count:,}", inactive_user_pct, help="No login in 30+ days, or never logged in." if sync_ok else None)
    a3.metric("\U0001F7E2 Active Vendors", f"{active_vendors_count:,}", active_vendor_pct, help="Approved and currently live in listings." if sync_ok else None)
    a4.metric("\U0001F534 Inactive Vendors", f"{inactive_vendors_count:,}", inactive_vendor_pct, help="Pending review or rejected \u2014 not currently visible to couples." if sync_ok else None)
    if sync_ok:
        render_drill_metric(a1, db_admin_list_users(mode="active"), user_cols_spec, total_count=active_users_count)
        render_drill_metric(a2, db_admin_list_users(mode="inactive"), user_cols_spec, total_count=inactive_users_count)
        render_drill_metric(a3, db_admin_list_vendors(mode="active"), vendor_cols_spec, total_count=active_vendors_count)
        render_drill_metric(a4, db_admin_list_vendors(mode="inactive"), vendor_cols_spec, total_count=inactive_vendors_count)

    st.markdown("<br>", unsafe_allow_html=True)
    st.markdown("### \U0001F4B3 Paid vs Unpaid")
    p1, p2, p3, p4 = st.columns(4)
    paid_pct = f"{paid_members/total_registered*100:.1f}% of users" if total_registered else ""
    unpaid_pct = f"{unpaid_members/total_registered*100:.1f}% of users" if total_registered else ""
    p1.metric("\U0001F48E Paid (VIP) Members", f"{paid_members:,}", paid_pct)
    p2.metric("\U0001F193 Unpaid (Free) Members", f"{unpaid_members:,}", unpaid_pct)
