                img_bytes = media_get_bytes(ad.get("image_ref")) if ad.get("image_ref") else None
                vid_bytes = media_get_bytes(ad.get("video_ref")) if ad.get("video_ref") else None
                if vid_bytes:
                    st.video(vid_bytes)
