    st.markdown("<br>", unsafe_allow_html=True)
    st.markdown("### \U0001F4F8 Pending Profile Photo Reviews")
    pending_photos = db_list_pending_profile_photos()
    if not pending_photos:
        st.caption("No pending profile photos right now (or MongoDB isn't connected yet, so this list is empty in demo mode).")
    else:
        for p in pending_photos:
            with st.container():
                st.markdown(f"<div class='metric-card'>", unsafe_allow_html=True)
                st.markdown(f"**\U0001F194 {profile_public_id(p.get('email',''))} \u2014 {p.get('name','')}**")
                st.markdown(admin_member_details_html(p), unsafe_allow_html=True)
                _refs = (p.get("photo_refs") or [])[:5]
                if _refs:
                    # each photo is exactly 3x4 inch; wraps to next row on small screens
                    photo_cols = st.columns(min(len(_refs), 3))
                    for i, ref in enumerate(_refs):
                        photo_bytes = media_get_bytes(ref)
                        if photo_bytes:
                            with photo_cols[i % len(photo_cols)]:
                                _tags = []
                                if i == p.get("profile_photo_index", 0):
                                    _tags.append("\U0001F464 PROFILE")
                                if i == p.get("cover_photo_index", 1 if len(_refs) > 1 else 0):
                                    _tags.append("\U0001F5BC\uFE0F COVER")
                                admin_photo_3x4(photo_bytes, caption=f"{profile_public_id(p.get('email',''))} \u2022 {p.get('name','')} \u2022 Photo {i+1}" + (f" \u2022 {' + '.join(_tags)}" if _tags else ""))
                pc1, pc2 = st.columns(2)
                if pc1.button("\u2705 Approve", key=f"approve_photo_{p['email']}", use_container_width=True):
                    db_update_profile_photo_status(p["email"], "Approved")
                    st.rerun()
                if pc2.button("\u274C Reject", key=f"reject_photo_{p['email']}", use_container_width=True):
                    db_update_profile_photo_status(p["email"], "Rejected")
                    st.rerun()
                st.markdown("</div>", unsafe_allow_html=True)

    st.markdown("<br>", unsafe_allow_html=True)
