                if ac3.button("\u274C Cancel", key=f"assist_cancel_{req['_id']}", use_container_width=True):
                    db_update_assisted_request(str(req["_id"]), status="Cancelled")
                    st.rerun()
                st.markdown("</div>", unsafe_allow_html=True)

