# =====================================================================
# EMAIL NOTIFICATIONS (admin) — send-log persistence helper. Replaces the
# old WhatsApp send-log: WhatsApp Business API is a paid service, this
# admin broadcast tool now sends real Email instead (free, via the same
# SMTP setup used elsewhere in this app).
# =====================================================================
@_invalidate_cache_after("email_notification_logs")
def db_log_email_send(to_email, subject, message, success, mode):
    db = get_db()
    if db is None:
        return
    db.email_notification_logs.insert_one({
        "to_email": to_email, "subject": subject, "message": message, "success": success, "mode": mode,
        "sent_at": dt.datetime.utcnow(),
    })


@cached_read("email_notification_logs")
def db_list_email_logs(limit=20):
    db = get_db()
    if db is None:
        return []
    return list(db.email_notification_logs.find().sort("sent_at", -1).limit(limit))


# =====================================================================
def page_email_notifications():
    render_global_css(bg_color="#F0FDF4", page_css=""".wa-header { background: linear-gradient(135deg, #1A365D 0%, #2C5364 100%); padding: 30px; border-radius: 18px; color: white; text-align: center; margin-bottom: 25px; }
.wa-card { background: white; padding: 26px; border-radius: 16px; box-shadow: 0 8px 20px rgba(0,0,0,0.06); border: 1px solid #EAEAEA; }
.wa-setup-box { background: #E8F5E9; border-left: 5px solid #1A365D; padding: 16px 20px; border-radius: 10px; margin-bottom: 15px; }""")

    if st.session_state.user_role != "boss":
        st.error("\U0001F6AB Your account doesn't have permission to view this page.")
        if st.button("\u2190 Back to Home"):
            go_to("home")
