# =====================================================================
# GOVERNMENT ID VERIFICATION — Aadhaar/PAN document upload + admin review,
# assisted by FREE local OCR (Tesseract, no paid API) that cross-checks
# the name printed on the document against the name on the profile. This
# is still upload-and-manual-review, the same pattern as photo/video
# moderation above — NOT a live government database lookup (a real
# UIDAI/NSDL eKYC integration needs a licensed paid provider) — but the
# OCR name-match score gives the admin a fast, free signal on which
# submissions are safe to rubber-stamp vs which need a closer look,
# instead of reading every single document by eye.
# =====================================================================
def ocr_extract_id_text(doc_bytes, mime_type):
    """Runs local Tesseract OCR on an uploaded ID image. Returns the
    extracted text, or None if OCR isn't available (e.g. tesseract-ocr
    isn't installed on the server yet — add it to packages.txt) or the
    file is a PDF (skipped here; admin reviews those visually as before)."""
    try:
        import pytesseract
        if not (mime_type or "").startswith("image/"):
            return None
        img = Image.open(io.BytesIO(doc_bytes))
        return pytesseract.image_to_string(img)
    except Exception:
        return None


def _clean_name_for_match(name):
    cleaned = re.sub(r"\b(mr|mrs|ms|dr|shri|smt|kumari|s/o|d/o|w/o)\b\.?", "", (name or "").lower())
    cleaned = re.sub(r"[^a-z\s]", "", cleaned)
    return " ".join(cleaned.split())


def name_match_against_ocr_text(registered_name, ocr_text):
    """0-100 best-line similarity between the registered name and any
    single line of OCR-extracted text (the name usually sits on its own
    line on Aadhaar/PAN cards) — pure Python difflib, no paid API."""
    target = _clean_name_for_match(registered_name)
    if not target or not ocr_text:
        return 0
    best = 0
    for line in ocr_text.split("\n"):
        line_clean = _clean_name_for_match(line)
        if not line_clean:
            continue
        score = round(difflib.SequenceMatcher(None, target, line_clean).ratio() * 100)
        best = max(best, score)
    return best


@_invalidate_cache_after("profiles")
def db_submit_id_verification(email, doc_ref, id_type, doc_bytes=None, mime_type=None, registered_name=None):
    db = get_db()
    if db is None:
        return False
    update_fields = {
        "id_doc_ref": doc_ref, "id_type": id_type,
        "id_verification_status": "Pending", "id_submitted_at": dt.datetime.utcnow(),
    }
    if doc_bytes is not None:
        ocr_text = ocr_extract_id_text(doc_bytes, mime_type)
        update_fields["id_ocr_text"] = (ocr_text or "").strip()
        update_fields["id_name_match_score"] = name_match_against_ocr_text(registered_name, ocr_text) if ocr_text else None
    db.profiles.update_one({"email": email}, {"$set": update_fields})
    return True


