# ASSISTED MATCHMAKING — a member requests a human Relationship Manager
# to personally shortlist profiles for them, instead of searching
# themselves. Boss/admin sees the request queue and updates status.
# =====================================================================
@_invalidate_cache_after("assisted_matchmaking")
def db_create_assisted_request(email, name, phone, preferences, preferred_call_time):
    db = get_db()
    if db is None:
        return False
    db.assisted_matchmaking.insert_one({
        "email": email, "name": name, "phone": phone, "preferences": preferences,
        "preferred_call_time": preferred_call_time, "status": "New", "notes": "",
        "created_at": dt.datetime.utcnow(),
    })
    # ---- BUG FIX: this used to only save to the database — the company
    # never actually got a message about the new request unless someone
    # happened to open the Company Dashboard and scroll to this section.
    # Now an email actually lands in the company's own inbox (BOSS_EMAIL),
    # and — this is the important part — Reply-To is set to the REAL
    # member's own e-mail address (`email`, the person submitting the
    # request), not the company's own SMTP account. Sending "From" our
    # own Gmail account is unavoidable (Gmail refuses to send mail
    # claiming to be "From" an address it hasn't verified — see
    # send_generic_email's docstring), but hitting "Reply" on this email
    # now goes straight to the member who asked for a Relationship
    # Manager, instead of the company's own inbox replying to itself. ----
    boss_email, _ = get_boss_credentials()
    send_generic_email(
        boss_email, f"\U0001F91D New Assisted Matchmaking request \u2014 {name}",
        f"A member has requested Assisted Matchmaking on Siddhivinayak Matrimony.\n\n"
        f"Name: {name}\nMember's Email: {email}\nPhone: {phone}\n"
        f"Preferred call time: {preferred_call_time}\n\nPartner preferences:\n{preferences or '(none specified)'}\n\n"
        f"Reply directly to this email to reach {name} at {email}, or manage this request from the Company Dashboard.",
        reply_to=email,
    )
    return True


@cached_read("assisted_matchmaking")
def db_list_assisted_requests(email=None, status=None):
    db = get_db()
    if db is None:
        return []
    query = {}
    if email:
        query["email"] = email
    if status:
        query["status"] = status
    return list(db.assisted_matchmaking.find(query).sort("created_at", -1))


@_invalidate_cache_after("assisted_matchmaking")
def db_update_assisted_request(request_id, status=None, notes=None):
    db = get_db()
    if db is None:
        return False
    updates = {}
    if status:
        updates["status"] = status
    if notes is not None:
        updates["notes"] = notes
    if not updates:
        return False
    db.assisted_matchmaking.update_one({"_id": ObjectId(request_id)}, {"$set": updates})
    if status:
        req = db.assisted_matchmaking.find_one({"_id": ObjectId(request_id)})
        if req and req.get("email"):
            send_notification_email(req["email"], "New Matches", "Update on your Assisted Matchmaking request", f"Your Assisted Matchmaking request status is now: {status}." + (f"\n\nNote from your Relationship Manager: {notes}" if notes else ""))
    return True


def compress_uploaded_video(video_bytes, filename_hint="clip.mp4", target_min_mb=10, target_max_mb=12):
    """Re-encodes an uploaded/recorded video down to a 10-12 MB target
    size (instead of just rejecting anything over a fixed size cap) so a
    50-200MB phone-camera clip still stays clear after compression.
    Calculates a target bitrate from the clip's duration via ffprobe, then
    re-encodes with ffmpeg.

    Needs ffmpeg + ffprobe on the server — add a packages.txt file with
    the single line "ffmpeg" for this to work on Streamlit Cloud. If
    ffmpeg isn't available, this returns (None, reason) and the caller
    falls back to its own size-limit check on the original file."""
    import subprocess
    import tempfile
    import os
    import shutil
    import json

    if shutil.which("ffmpeg") is None or shutil.which("ffprobe") is None:
        return None, "ffmpeg isn't installed on this server (add 'ffmpeg' to packages.txt for Streamlit Cloud)."

    suffix = os.path.splitext(filename_hint)[1] or ".mp4"
    in_path = out_path = None
    try:
        with tempfile.NamedTemporaryFile(suffix=suffix, delete=False) as in_file:
            in_file.write(video_bytes)
            in_path = in_file.name
        out_path = in_path + "_compressed.mp4"

        try:
            probe = subprocess.run(
                ["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "json", in_path],
                capture_output=True, text=True, timeout=30,
            )
            duration = float(json.loads(probe.stdout)["format"]["duration"])
            if duration <= 0:
                duration = 60.0
        except Exception:
            duration = 60.0

        target_mb = (target_min_mb + target_max_mb) / 2
        target_kbits = target_mb * 8192  # MB -> kilobits (8192 kilobits/MB)
        audio_kbps = 64
        video_kbps = max(int(target_kbits / duration) - audio_kbps, 150)

        result = subprocess.run(
            [
                "ffmpeg", "-y", "-i", in_path,
                "-vcodec", "libx264", "-b:v", f"{video_kbps}k",
                "-acodec", "aac", "-b:a", f"{audio_kbps}k",
                "-preset", "fast", "-movflags", "+faststart",
                out_path,
            ],
            capture_output=True, timeout=180,
        )
        if result.returncode != 0 or not os.path.exists(out_path):
            return None, "ffmpeg failed to re-encode this video."

        with open(out_path, "rb") as f:
            compressed_bytes = f.read()
        return compressed_bytes, None
    except Exception as e:
        return None, str(e)
    finally:
        for p in (in_path, out_path):
            if p and os.path.exists(p):
                try:
                    os.remove(p)
                except Exception:
                    pass


def render_video_profile_section(user_email, sync_ok):
    """Intro-video record/upload + preview + tips. Shared by the Registration
    'Video Intro' tab and Edit My Profile (and the legacy standalone page),
    so the video is part of registration instead of a separate page.
    Must be called OUTSIDE st.form (it uses st.button)."""
    st.markdown("""<style>
    .vidpro-card { background: white; padding: 22px; border-radius: 14px; box-shadow: 0 6px 15px rgba(0,0,0,0.06); border: 1px solid #EAEAEA; margin-bottom: 18px; }
    .vidpro-badge { background: #DCFCE7; color: #166534; padding: 8px 16px; border-radius: 10px; font-weight: 700; display:inline-block; }
    </style>""", unsafe_allow_html=True)
    if sync_ok:
        storage_note = "\u2601\uFE0F Video files are stored in AWS S3" if media_storage_is_cloud() else "\U0001F4BE Video files are stored on local server disk (demo) \u2014 configure AWS S3 in secrets for production, since local disk isn't persistent."
        st.caption(storage_note)

    if "profile_video_loaded" not in st.session_state:
        existing = db_get_profile_video(user_email) if sync_ok else None
        if existing:
            st.session_state.profile_video_bytes = media_get_bytes(existing.get("video_ref"))
            st.session_state.profile_video_status = existing["status"]
        st.session_state.profile_video_loaded = True

    if "profile_video_bytes" not in st.session_state:
        st.session_state.profile_video_bytes = None
        st.session_state.profile_video_status = "Not uploaded"

    st.markdown("<div class='vidpro-card'>", unsafe_allow_html=True)
    st.markdown("### \U0001F4F9 Record or Upload Your Intro")
    # ---- Raw uploads up to 200MB are now accepted (instead of a hard
    # 50MB rejection) — the video is then automatically compressed down to
    # ~10-12MB via ffmpeg before storage, so clarity is preserved instead
    # of the old fixed-quality guesswork. If ffmpeg isn't installed on the
    # server, this falls back to the original raw-size limit below. ----
    RAW_UPLOAD_MAX_MB = 200
    TARGET_MIN_MB, TARGET_MAX_MB = 10, 12
    tab1, tab2 = st.tabs(["\U0001F4F7 Record with Camera", "\U0001F4C1 Upload a Video File"])
    with tab1:
        st.caption(f"Tip: introduce yourself, your interests, and what you're looking for in a partner. Keep it 30\u201360 seconds \u2014 we'll automatically compress it to ~{TARGET_MIN_MB}-{TARGET_MAX_MB}MB (max raw file size {RAW_UPLOAD_MAX_MB}MB).")
        cam_video = st.camera_input("Record a short intro (webcam)", key="vidpro_camera")
        if cam_video is not None and st.session_state.get("_vidpro_last_sig") != ("cam", cam_video.name, cam_video.size):
            st.session_state._vidpro_last_sig = ("cam", cam_video.name, cam_video.size)
            raw_bytes = cam_video.getvalue()
            raw_size_mb = len(raw_bytes) / (1024 * 1024)
            if raw_size_mb > RAW_UPLOAD_MAX_MB:
                st.error(f"\u274C This clip is {raw_size_mb:.1f}MB, which is over the {RAW_UPLOAD_MAX_MB}MB raw upload limit. Please record a shorter clip.")
            else:
                with st.spinner("Compressing your video for HD-quality playback at a smaller size..."):
                    compressed_bytes, compress_err = compress_uploaded_video(raw_bytes, "intro.mp4", TARGET_MIN_MB, TARGET_MAX_MB)
                video_bytes = compressed_bytes if compressed_bytes else raw_bytes
                size_mb = len(video_bytes) / (1024 * 1024)
                st.session_state.profile_video_bytes = video_bytes
                st.session_state.profile_video_status = "Pending Review"
                if sync_ok:
                    video_ref = media_upload(video_bytes, f"{user_email}_intro.mp4", "video/mp4")
                    db_save_profile_video(user_email, video_ref, round(size_mb, 1))
                if compressed_bytes:
                    st.success(f"\u2705 Intro clip captured and compressed from {raw_size_mb:.1f}MB to {size_mb:.1f}MB! It's been sent for admin review and will appear on your profile once approved.")
                else:
                    st.success(f"\u2705 Intro clip captured ({size_mb:.1f}MB)! It's been sent for admin review and will appear on your profile once approved.")
                    if compress_err:
                        st.caption(f"\u2139\uFE0F Compression skipped: {compress_err}")
    with tab2:
        st.caption(f"We'll automatically compress your video to ~{TARGET_MIN_MB}-{TARGET_MAX_MB}MB while keeping it clear \u2014 max raw file size {RAW_UPLOAD_MAX_MB}MB before compression.")
        uploaded_video = st.file_uploader("Upload MP4/MOV (max 60 seconds recommended)", type=["mp4", "mov", "m4v"], key="vidpro_upload")
        if uploaded_video is not None and st.session_state.get("_vidpro_last_sig") != ("up", uploaded_video.name, uploaded_video.size):
            st.session_state._vidpro_last_sig = ("up", uploaded_video.name, uploaded_video.size)
            raw_bytes = uploaded_video.getvalue()
            raw_size_mb = len(raw_bytes) / (1024 * 1024)
            if raw_size_mb > RAW_UPLOAD_MAX_MB:
                st.error(f"\u274C This file is {raw_size_mb:.1f}MB, which is over the {RAW_UPLOAD_MAX_MB}MB raw upload limit. Please upload a shorter clip.")
            else:
                with st.spinner("Compressing your video for HD-quality playback at a smaller size..."):
                    compressed_bytes, compress_err = compress_uploaded_video(raw_bytes, uploaded_video.name, TARGET_MIN_MB, TARGET_MAX_MB)
                video_bytes = compressed_bytes if compressed_bytes else raw_bytes
                size_mb = len(video_bytes) / (1024 * 1024)
                st.session_state.profile_video_bytes = video_bytes
                st.session_state.profile_video_status = "Pending Review"
                if sync_ok:
                    video_ref = media_upload(video_bytes, uploaded_video.name, uploaded_video.type or "video/mp4")
                    db_save_profile_video(user_email, video_ref, round(size_mb, 1))
                if compressed_bytes:
                    st.success(f"\u2705 Video uploaded and compressed from {raw_size_mb:.1f}MB to {size_mb:.1f}MB! It's been sent for admin review and will appear on your profile once approved.")
                else:
                    st.success(f"\u2705 Video uploaded ({size_mb:.1f}MB)! It's been sent for admin review and will appear on your profile once approved.")
                    if compress_err:
                        st.caption(f"\u2139\uFE0F Compression skipped: {compress_err}")
    st.markdown("</div>", unsafe_allow_html=True)

    st.markdown("<div class='vidpro-card'>", unsafe_allow_html=True)
    st.markdown("### \U0001F441\uFE0F Preview")
    if st.session_state.profile_video_bytes:
        st.video(st.session_state.profile_video_bytes)
        status = st.session_state.profile_video_status
        badge_color = "#DCFCE7" if status == "Approved" else ("#FEE2E2" if status == "Rejected" else "#FEF3C7")
        text_color = "#166534" if status == "Approved" else ("#991B1B" if status == "Rejected" else "#92400E")
        render_html(f"<span class='vidpro-badge' style='background:{badge_color}; color:{text_color};'>Status: {status}</span>")
        if status == "Pending Review":
            st.caption("\u23F3 An admin needs to review this before it appears publicly on your profile \u2014 this is no longer a self-approve step.")
        if st.button("\U0001F5D1\uFE0F Remove Video", use_container_width=True):
            st.session_state.profile_video_bytes = None
            st.session_state.profile_video_status = "Not uploaded"
            st.session_state.pop("_vidpro_last_sig", None)
            if sync_ok:
                db_delete_profile_video(user_email)
            st.rerun()
    else:
        st.info("No intro video yet — record or upload one above so matches can see and hear you.")
    st.markdown("</div>", unsafe_allow_html=True)

    st.markdown("### \U0001F4A1 Tips for a Great Intro Video")
    st.write("""
    - Keep it 30-60 seconds — short and genuine works best
    - Good lighting and a quiet background make a big difference
    - Talk about your interests, values, and what you're looking for
    - Avoid sharing phone numbers, addresses, or social media handles on camera
    - All videos are moderated by our admin team before appearing publicly on your profile
    """)


