# =====================================================================
# AGORA — real two-way video calling. Generates a secure, short-lived
# join token server-side (never expose the App Certificate to the
# browser) and renders a small Agora Web SDK page via components.html()
# so both participants who join the same channel actually see and hear
# each other. Falls back to a clear "not configured" message rather than
# crashing if AGORA_APP_ID / AGORA_APP_CERTIFICATE aren't in Secrets yet.
# =====================================================================
def agora_get_credentials():
    try:
        app_id = _secret("AGORA_APP_ID")
        app_cert = _secret("AGORA_APP_CERTIFICATE")
        if not app_id or not app_cert:
            return None, None
        return app_id, app_cert
    except Exception:
        return None, None


def agora_channel_name(email_a, email_b):
    """Deterministic, safe channel name for a pair of participants \u2014
    same two people always land in the same private room, regardless of
    who joins first. Hashed because Agora channel names must be short
    (<64 chars) and raw emails could exceed that or contain characters
    Agora doesn't allow."""
    pair = "::".join(sorted([str(email_a), str(email_b)]))
    return "bandhan_" + hashlib.sha256(pair.encode()).hexdigest()[:24]


def agora_generate_token(channel_name, uid=0, expire_seconds=3600):
    """Builds a secure RTC join token using the official agora-token-builder
    library (never hand-roll this crypto \u2014 use the maintained package).
    Returns None if the library or credentials aren't available, so the
    caller can show a friendly setup message instead of crashing."""
    app_id, app_cert = agora_get_credentials()
    if not app_id or not app_cert:
        return None, None
    try:
        from agora_token_builder import RtcTokenBuilder
        expire_ts = int(time.time()) + expire_seconds
        token = RtcTokenBuilder.buildTokenWithUid(app_id, app_cert, channel_name, uid, 1, expire_ts)
        return app_id, token
    except ImportError:
        return None, None
    except Exception:
        return None, None


def agora_diagnose():
    """Pinpoints exactly which of the two setup requirements is missing,
    so 'still in demo mode' doesn't stay a mystery: (1) AGORA_APP_ID /
    AGORA_APP_CERTIFICATE in Secrets, and (2) the agora-token-builder
    PyPI package in requirements.txt. Both are needed \u2014 people
    commonly add the Secrets but forget the package, or vice versa."""
    app_id, app_cert = agora_get_credentials()
    if not app_id or not app_cert:
        return "\u274C **AGORA_APP_ID / AGORA_APP_CERTIFICATE not found in Secrets.** Double-check: exact key names (case-sensitive), no quotes issues, no leading/trailing spaces, and that you clicked Save + the app rebooted after editing Secrets."
    try:
        import agora_token_builder  # noqa: F401
    except ImportError:
        return "\u274C **Secrets look good, but the `agora-token-builder` Python package isn't installed.** Add a line `agora-token-builder` to your `requirements.txt` file (same folder as app.py) and redeploy \u2014 Secrets alone aren't enough, this package is also required to actually build the call token."
    try:
        test_token = agora_generate_token("diagnostic_test_channel", uid=0)
        if test_token[1]:
            return "\u2705 Agora is fully configured and working \u2014 Secrets found, package installed, token generated successfully."
        return "\u26A0\uFE0F Secrets and package both found, but token generation still failed \u2014 double check your AGORA_APP_ID and AGORA_APP_CERTIFICATE values are copied correctly (no extra spaces) from the Agora Console."
    except Exception as e:
        return f"\u26A0\uFE0F Unexpected error while generating a test token: {e}"


def agora_video_widget_html(app_id, channel_name, token, uid, display_name):
    """The actual video call UI \u2014 loads Agora's Web SDK from their CDN
    and joins the given channel. Both people calling this with the same
    channel_name (and their own uid/token) will see & hear each other."""
    safe_name = (display_name or "You").replace('"', "")
    return f"""
    <div id="agora-root" style="font-family:Helvetica,Arial,sans-serif;">
      <style>
        #video-streams {{ display:flex; gap:10px; flex-wrap:wrap; justify-content:center; }}
        .video-tile {{ width:280px; height:210px; background:#0F2027; border-radius:12px; overflow:hidden; position:relative; border:2px solid #D4AF37; }}
        .video-tile .tag {{ position:absolute; bottom:6px; left:8px; color:#fff; font-size:12px; background:rgba(0,0,0,0.5); padding:2px 8px; border-radius:8px; }}
        #agora-controls {{ text-align:center; margin-top:14px; }}
        #agora-controls button {{ background:#1A365D; color:#D4AF37; border:1px solid #D4AF37; padding:8px 18px; margin:0 6px; border-radius:8px; cursor:pointer; font-size:14px; }}
        #agora-controls button.leave {{ background:#B03A2E; color:white; border-color:#B03A2E; }}
        #agora-status {{ text-align:center; color:#555; font-size:13px; margin-bottom:10px; }}
      </style>
      <div id="agora-status">\U0001F7E1 Connecting...</div>
      <div id="video-streams">
        <div class="video-tile" id="local-tile"><span class="tag">{safe_name} (You)</span></div>
      </div>
      <div id="agora-controls">
        <button id="btn-mic">\U0001F3A4 Mute</button>
        <button id="btn-cam">\U0001F4F9 Camera Off</button>
      </div>
    </div>
    <script src="https://download.agora.io/sdk/release/AgoraRTC_N-4.20.0.js"></script>
    <script>
    (function() {{
      const client = AgoraRTC.createClient({{ mode: "rtc", codec: "vp8" }});
      const statusEl = document.getElementById("agora-status");
      let micOn = true, camOn = true, localAudioTrack, localVideoTrack;

      async function start() {{
        try {{
          await client.join("{app_id}", "{channel_name}", "{token}", {uid});
          [localAudioTrack, localVideoTrack] = await AgoraRTC.createMicrophoneAndCameraTracks();
          localVideoTrack.play("local-tile");
          await client.publish([localAudioTrack, localVideoTrack]);
          statusEl.innerText = "\\uD83D\\uDFE2 Connected \\u2014 waiting for the other person to join...";

          client.on("user-published", async (user, mediaType) => {{
            await client.subscribe(user, mediaType);
            let tile = document.getElementById("remote-tile-" + user.uid);
            if (!tile) {{
              tile = document.createElement("div");
              tile.className = "video-tile";
              tile.id = "remote-tile-" + user.uid;
              tile.innerHTML = '<span class="tag">Other person</span>';
              document.getElementById("video-streams").appendChild(tile);
            }}
            if (mediaType === "video") user.videoTrack.play(tile);
            if (mediaType === "audio") user.audioTrack.play();
            statusEl.innerText = "\\uD83D\\uDFE2 Connected \\u2014 call in progress";
          }});
          client.on("user-left", (user) => {{
            const tile = document.getElementById("remote-tile-" + user.uid);
            if (tile) tile.remove();
            statusEl.innerText = "\\uD83D\\uDFE1 The other person left the call.";
          }});
        }} catch (e) {{
          statusEl.innerText = "\\u274C Could not connect: " + e.message;
        }}
      }}

      document.getElementById("btn-mic").onclick = () => {{
        micOn = !micOn;
        if (localAudioTrack) localAudioTrack.setEnabled(micOn);
        document.getElementById("btn-mic").innerText = micOn ? "\\uD83C\\uDFA4 Mute" : "\\uD83D\\uDD07 Unmute";
      }};
      document.getElementById("btn-cam").onclick = () => {{
        camOn = !camOn;
        if (localVideoTrack) localVideoTrack.setEnabled(camOn);
        document.getElementById("btn-cam").innerText = camOn ? "\\uD83D\\uDCF9 Camera Off" : "\\uD83D\\uDCF7 Camera On";
      }};
      start();
    }})();
    </script>
    """


# =====================================================================
# LIVE VIDEO CALL \u2014 scheduled calls between two REAL members.
# ---------------------------------------------------------------------
# * A request is stored ONCE in db.video_calls and is visible to BOTH
#   people (recipient can Accept / Decline).
# * Times are stored as UTC and always shown in IST.
# * 15 minutes before an accepted call BOTH people get an in-app
#   notification (banner + toast + Alerts centre) and an e-mail.
#   Streamlit has no background scheduler, so the reminder fires the
#   first time EITHER person's open session polls inside the window
#   (the banner below re-checks every 60 s while the app is open).
# =====================================================================
VCALL_REMINDER_MINUTES = 15      # heads-up window before the call
VCALL_JOIN_GRACE_MINUTES = 120   # call room stays joinable this long after the start time


@_invalidate_cache_after("video_calls")
def db_create_video_call(from_email, to_email, from_name, to_name, scheduled_ist):
    db = get_db()
    if db is None:
        return None
    scheduled_utc = scheduled_ist.astimezone(dt.timezone.utc).replace(tzinfo=None)
    res = db.video_calls.insert_one({
        "from_email": from_email, "to_email": to_email, "from_name": from_name, "to_name": to_name,
        "scheduled_at_utc": scheduled_utc, "status": "Pending", "reminder_sent": False,
        "created_at": dt.datetime.utcnow(),
    })
    return str(res.inserted_id)


@cached_read("video_calls")
def db_list_video_calls(email, limit=60):
    db = get_db()
    if db is None or not email:
        return []
    return list(db.video_calls.find({"$or": [{"from_email": email}, {"to_email": email}]}).sort("scheduled_at_utc", -1).limit(limit))


@_invalidate_cache_after("video_calls")
def db_set_video_call_status(call_id, status):
    db = get_db()
    if db is None:
        return False
    db.video_calls.update_one({"_id": ObjectId(str(call_id))}, {"$set": {"status": status, "updated_at": dt.datetime.utcnow()}})
    return True


def vcall_other_party(call, my_email):
    if call["from_email"] == my_email:
        return call["to_email"], call.get("to_name", "")
    return call["from_email"], call.get("from_name", "")


def vcall_when_text(call):
    return utc_to_ist(call["scheduled_at_utc"]).strftime("%a, %d %b %Y at %I:%M %p") + " IST"


def vcall_join_state(call):
    """('early', mins) before the reminder window, ('open', mins) inside it
    (mins < 0 once the call time has passed), ('over', mins) after the grace period."""
    mins = (call["scheduled_at_utc"] - dt.datetime.utcnow()).total_seconds() / 60
    if mins > VCALL_REMINDER_MINUTES:
        return "early", mins
    if mins < -VCALL_JOIN_GRACE_MINUTES:
        return "over", mins
    return "open", mins


def vcall_notify(call, event):
    """Sends the in-app notification(s) AND e-mail(s) for a call event.
    event: requested | accepted | declined | cancelled | reminder.
    Contact details (phone / email) of the other person are never included."""
    from_e, to_e = call["from_email"], call["to_email"]
    from_n = call.get("from_name") or "A Siddhivinayak Matrimony member"
    to_n = call.get("to_name") or "A Siddhivinayak Matrimony member"
    from_id, to_id = profile_public_id(from_e), profile_public_id(to_e)
    when = vcall_when_text(call)
    footer = ("\n\nAll video calls happen inside Siddhivinayak Matrimony. Please never share phone numbers, addresses or "
              "social-media handles on the call \u2014 if anyone asks you to, report them from Report & Safety.\n\n\u2014 Team Siddhivinayak Matrimony")
    # each entry: recipient -> (icon, in-app text, email subject, email body)
    out = {}
    if event == "requested":
        out[to_e] = ("\U0001F4F9", f"{from_n} (ID {from_id}) requested a live video call on {when}. Open Live Video Call to accept or decline.",
                     "\U0001F4F9 New video call request on Siddhivinayak Matrimony",
                     f"Hi {to_n},\n\n{from_n} (Profile ID {from_id}) has requested a live video call with you on {when}.\n"
                     f"Log in to Siddhivinayak Matrimony \u2192 Live Video Call to accept or decline." + footer)
        out[from_e] = ("\U0001F4E4", f"Your video call request to {to_n} (ID {to_id}) for {when} was sent.",
                       "\U0001F4E4 Video call request sent",
                       f"Hi {from_n},\n\nYour live video call request to {to_n} (Profile ID {to_id}) for {when} has been sent. "
                       f"You'll be notified as soon as they respond." + footer)
    elif event == "accepted":
        text_from = f"{to_n} (ID {to_id}) accepted your video call for {when}. You'll get a reminder {VCALL_REMINDER_MINUTES} minutes before."
        text_to = f"You accepted the video call with {from_n} (ID {from_id}) on {when}. You'll get a reminder {VCALL_REMINDER_MINUTES} minutes before."
        out[from_e] = ("\u2705", text_from, "\u2705 Video call confirmed", f"Hi {from_n},\n\n{text_from}" + footer)
        out[to_e] = ("\u2705", text_to, "\u2705 Video call confirmed", f"Hi {to_n},\n\n{text_to}" + footer)
    elif event == "declined":
        t = f"{to_n} (ID {to_id}) couldn't accept your video call request for {when}. You can propose another time."
        out[from_e] = ("\u274C", t, "Video call request declined", f"Hi {from_n},\n\n{t}" + footer)
    elif event == "cancelled":
        # cancelled by whoever is NOT the recipient of this notice: tell both, it's harmless and clear
        t = f"The video call scheduled for {when} between {from_n} (ID {from_id}) and {to_n} (ID {to_id}) was cancelled."
        out[from_e] = ("\u274C", t, "Video call cancelled", f"Hi {from_n},\n\n{t}" + footer)
        out[to_e] = ("\u274C", t, "Video call cancelled", f"Hi {to_n},\n\n{t}" + footer)
    elif event == "reminder":
        t_from = f"\u23F0 Your live video call with {to_n} (ID {to_id}) starts in about {VCALL_REMINDER_MINUTES} minutes ({when}). Open Live Video Call to join."
        t_to = f"\u23F0 Your live video call with {from_n} (ID {from_id}) starts in about {VCALL_REMINDER_MINUTES} minutes ({when}). Open Live Video Call to join."
        out[from_e] = ("\u23F0", t_from, f"\u23F0 Video call in {VCALL_REMINDER_MINUTES} minutes", f"Hi {from_n},\n\n{t_from}" + footer)
        out[to_e] = ("\u23F0", t_to, f"\u23F0 Video call in {VCALL_REMINDER_MINUTES} minutes", f"Hi {to_n},\n\n{t_to}" + footer)

    for recipient, (icon, text, subject, body) in out.items():
        db_add_user_notification(recipient, f"video_call_{event}", text, icon=icon, link_view="live_video_call", extra={"call_id": str(call.get("_id", ""))})
        try:
            send_notification_email(recipient, "Messages & Chat", subject, body)
        except Exception:
            pass  # in-app notification is already saved


def _vcall_reminder_body():
    """Banner shown on EVERY page (for clients) while an accepted call is
    inside its reminder window. First detection also creates the in-app
    notification + e-mail for BOTH people, exactly once."""
    email = st.session_state.get("user_email")
    if not email or st.session_state.get("user_role") != "client" or not db_is_connected():
        return
    import html as _html
    try:
        db = get_db()
        now = dt.datetime.utcnow()
        calls = list(db.video_calls.find({
            "status": "Accepted",
            "$or": [{"from_email": email}, {"to_email": email}],
            "scheduled_at_utc": {
                "$gte": now - dt.timedelta(minutes=VCALL_JOIN_GRACE_MINUTES),
                "$lte": now + dt.timedelta(minutes=VCALL_REMINDER_MINUTES),
            },
        }).sort("scheduled_at_utc", 1).limit(3))
    except Exception:
        return

    toasted = st.session_state.setdefault("vcall_toasted", set())
    for c in calls:
        cid = str(c["_id"])
        _, other_name = vcall_other_party(c, email)
        other_name = other_name or "your match"
        mins = (c["scheduled_at_utc"] - now).total_seconds() / 60

        if not c.get("reminder_sent"):
            try:
                res = db.video_calls.update_one({"_id": c["_id"], "reminder_sent": {"$ne": True}}, {"$set": {"reminder_sent": True}})
                if res.modified_count:
                    vcall_notify(c, "reminder")
            except Exception:
                pass

        if mins > 0:
            plain = f"\u23F0 Live video call with {other_name} starts in {max(1, int(round(mins)))} min ({vcall_when_text(c)})"
        else:
            plain = f"\U0001F534 Your live video call with {other_name} is due now ({vcall_when_text(c)})"
        headline = _html.escape(plain)
        if cid not in toasted:
            toasted.add(cid)
            st.toast(plain, icon="\U0001F4F9")

        if st.session_state.get("vcall_active_call") == cid:
            continue
        st.markdown(
            f"<div style='background:linear-gradient(90deg,#FFF7D6,#FFE9A8); border:2px solid #D4AF37; border-radius:12px; "
            f"padding:10px 16px; margin-bottom:8px; font-weight:700; color:#1A365D;'>{headline}</div>",
            unsafe_allow_html=True,
        )
        if st.button("\U0001F4F9 Join Call Room", key=f"vcall_banner_join_{cid}", type="primary"):
            st.session_state.vcall_focus_call = cid
            st.session_state.current_view = "live_video_call"
            try:
                st.rerun(scope="app")
            except TypeError:
                st.rerun()


if hasattr(st, "fragment"):
    @st.fragment(run_every=60)
    def render_video_call_reminders():
        _vcall_reminder_body()
else:
    def render_video_call_reminders():
        _vcall_reminder_body()


