@_invalidate_cache_after("vendor_reviews")
def db_add_vendor_review(vendor_name, reviewer_name, rating, review_text):
    db = get_db()
    if db is None:
        return False
    db.vendor_reviews.insert_one({
        "vendor_name": vendor_name, "reviewer_name": reviewer_name, "rating": rating,
        "review_text": review_text, "posted_at": dt.datetime.utcnow(),
    })
    return True


@cached_read("vendor_reviews")
def db_get_vendor_reviews(vendor_name):
    db = get_db()
    if db is None:
        return []
    return list(db.vendor_reviews.find({"vendor_name": vendor_name}).sort("posted_at", -1))


# =====================================================================
# ASTROLOGER WALLET & COMMISSION SYSTEM
# Every astrologer keeps a prepaid wallet balance. When a booked session
# is completed, 10% of the session fee is auto-deducted from that
# astrologer's wallet straight to the company's commission ledger. An
# astrologer whose wallet balance falls below the MIN_ASTRO_WALLET_BALANCE
# threshold shows as Inactive (can't be booked) until they recharge \u2014
# this is what makes sure the company always collects its 10% even
# though the client pays the astrologer's fee directly via the
# astrologer's own UPI QR code (there's no payment gateway wired up here
# to automatically split the payment at the moment it happens).
# =====================================================================
MIN_ASTRO_WALLET_BALANCE = 100
ASTRO_COMMISSION_RATE = 0.10


@_invalidate_cache_after("astrologers")
def db_create_astrologer(name, specialty, experience, price, qr_ref, email="", tier="Free"):
    db = get_db()
    if db is None:
        return False
    db.astrologers.insert_one({
        "name": name, "specialty": specialty, "experience": experience, "price": price,
        "qr_ref": qr_ref, "email": email, "wallet_balance": 0, "tier": tier, "created_at": dt.datetime.utcnow(),
    })
    return True


@cached_read("astrologers")
def db_list_astrologers():
    db = get_db()
    if db is None:
        return []
    astros = list(db.astrologers.find().sort("created_at", -1))
    for a in astros:
        a["is_active"] = a.get("wallet_balance", 0) >= MIN_ASTRO_WALLET_BALANCE
        a.setdefault("tier", "Free")
    return astros


@cached_read("astro_bookings")
def db_list_pending_astro_requests():
    """Every client's pending astrology booking request, across all
    clients, so admin can Accept/Decline on the astrologer's behalf
    (there's no separate astrologer login/portal here for them to do
    this themselves yet \u2014 see db_recharge_astrologer_wallet)."""
    db = get_db()
    if db is None:
        return []
    out = []
    for doc in db.astro_bookings.find({}):
        for idx, b in enumerate(doc.get("bookings", [])):
            if b.get("status") == "Pending Astrologer Approval":
                out.append({"client_email": doc["email"], "booking_index": idx, **b})
    return out


@_invalidate_cache_after("astro_bookings")
def db_update_astro_booking_status(client_email, booking_index, new_status):
    db = get_db()
    if db is None:
        return False
    db.astro_bookings.update_one(
        {"email": client_email},
        {"$set": {f"bookings.{booking_index}.status": new_status}},
    )
    return True


@_invalidate_cache_after("admin_audit_log", "astrologers")
def db_recharge_astrologer_wallet(astrologer_id, amount):
    """Admin-assisted top-up (there's no separate astrologer login/portal
    here for them to self-recharge yet \u2014 an astrologer would hand the
    company their recharge amount off-platform, and admin credits it
    here). Logs the recharge for audit."""
    db = get_db()
    if db is None:
        return False
    db.astrologers.update_one({"_id": ObjectId(astrologer_id)}, {"$inc": {"wallet_balance": amount}})
    db_log_admin_action("astrologer_wallet_recharge", astrologer_id, f"+\u20b9{amount}")
    return True


@_invalidate_cache_after("astro_commission_ledger", "astrologers")
def db_deduct_commission(astrologer_id, session_fee):
    """Called once a booked session is marked Completed. Deducts 10% of
    the session fee from the astrologer's wallet into the company's
    commission ledger, and returns the astrologer to Inactive status if
    that drops them below the minimum balance."""
    db = get_db()
    if db is None:
        return False
    commission = round(session_fee * ASTRO_COMMISSION_RATE, 2)
    db.astrologers.update_one({"_id": ObjectId(astrologer_id)}, {"$inc": {"wallet_balance": -commission}})
    db.astro_commission_ledger.insert_one({
        "astrologer_id": str(astrologer_id), "session_fee": session_fee, "commission": commission,
        "deducted_at": dt.datetime.utcnow(),
    })
    return True


@cached_read("astro_commission_ledger")
def db_get_total_commission_earned():
    db = get_db()
    if db is None:
        return 0
    total = list(db.astro_commission_ledger.aggregate([{"$group": {"_id": None, "total": {"$sum": "$commission"}}}]))
    return total[0]["total"] if total else 0


